    def _v342_versions(_html):
        if not isinstance(_html, str):
            return _html
        _html = _v342_re.sub(r"const\s+V\s*=\s*(['\"])v\d+\1", "const V='v342'", _html)
        _html = _v342_re.sub(r'TAK-Map/1\.1\.0\s+v\d+', 'TAK-Map/1.2.0 v342', _html)
        _html = _v342_re.sub(r'TAKDashboard/v\d+', 'TAKDashboard/v342', _html)
        _html = _v342_re.sub(r'(<span[^>]*class=["\'][^"\']*iteration-(?:chip|marker)[^"\']*["\'][^>]*>)v\d+(</span>)', r'\1v342\2', _html, flags=_v342_re.I)
        _html = _v342_re.sub(r'(<div[^>]*class=["\'][^"\']*iteration-marker[^"\']*["\'][^>]*>)v\d+(</div>)', r'\1v342\2', _html, flags=_v342_re.I)
        _html = _v342_re.sub(r'(<[^>]+data-iteration=["\'])v\d+(["\'][^>]*>)', r'\1v342\2', _html, flags=_v342_re.I)
        return _html

    def _v342_feature_route_score(f, kind=''):
        score=0
        reasons=[]
        try:
            pts=_local_data_feature_points(f) or []
        except Exception:
            pts=[]
        if len(pts) >= 2:
            score += 2; reasons.append('multi-point')
        else:
            return 0, reasons
        try:
            base_kind=_local_data_feature_kind(f)
            if base_kind == 'route':
                score += 3; reasons.append('local-kind-route')
        except Exception:
            pass
        k=str(kind or '').strip().lower()
        if k in ('routes','route'):
            score += 4; reasons.append('request-kind-route')
        f=f or {}
        props=f.get('properties') if isinstance(f.get('properties'), dict) else {}
        blob=' '.join(str(x or '') for x in [
            f.get('kind'), f.get('geometry'), f.get('geometry_type'), f.get('type'), f.get('cot_type'),
            f.get('atak_cot_type'), f.get('source'), f.get('name'), f.get('title'), f.get('import_name'),
            props.get('kind'), props.get('geometry'), props.get('geometry_type'), props.get('type'), props.get('cot_type'),
            props.get('atak_cot_type'), props.get('source'), props.get('route_type'), props.get('route_method'),
            props.get('checkpoint_prefix'), props.get('atak_route_metadata')
        ]).lower()
        for needle, val in (('route',3), ('linestring',3), ('line string',3), ('track',2), ('path',1), ('b-m-r',4), ('tak map route tool',4), ('checkpoint',2)):
            if needle in blob:
                score += val; reasons.append(needle)
        try:
            # GeoJSON routes are stored as LineString coordinates in either coords or geometry.
            geom=f.get('geometry')
            if isinstance(geom, dict) and str(geom.get('type') or '').lower() in ('linestring','multilinestring'):
                score += 4; reasons.append('geojson-linestring')
            if isinstance(f.get('coords'), list) and len(f.get('coords') or []) >= 2 and k in ('routes','route'):
                score += 2; reasons.append('coords-with-route-kind')
        except Exception:
            pass
        return score, reasons

    def _v342_route_features(features, kind=''):
        feats=list(features or [])
        if not feats:
            return []
        out=[]; debug=[]
        for f in feats:
            score,reasons=_v342_feature_route_score(f, kind)
            debug.append({'score':score,'reasons':reasons,'name':str((f or {}).get('name') or (f or {}).get('title') or '')[:80]})
            if score >= 4:
                out.append(f)
        # Do not mix route and non-route items in this route-specific path.
        return out if len(out) == len(feats) and out else []

