            associated=int(assoc.get('associated_count') or (len(shape_uids) if assoc.get('ok') else 0)) if isinstance(assoc, dict) else 0
            rec={'creator_uid':creator_uid,'source':cand.get('source'),'create_mission':create,'shapes':records,'sent_event_uids':sent,'associate_uids':assoc,'expected_count':len(shape_features),'associated_count':associated,'ok':bool(assoc.get('ok') and associated==len(shape_uids) and len(shape_uids)==len(shape_features))}
