    TAK_MAP_HTML=_v345_patch_html(TAK_MAP_HTML); TAK_MAP_LOGIN_HTML=_v345_versions(TAK_MAP_LOGIN_HTML); LOGIN_HTML=_v345_versions(LOGIN_HTML)
