    def _tak_v415_versions(_html):
        if not isinstance(_html,str): return _html
        # Public release remains v1.3.0; internal/UI iteration is i442.
        _html=_re_v414.sub(r"TAK-Map/\d+\.\d+\.\d+\s+[vi]\d+","TAK-Map/1.3.0 i442",_html)
        _html=_re_v414.sub(r"TAKDashboard/[vi]\d+","TAKDashboard/i442",_html)
        # Package/archive naming intentionally remains vxxx.
        _html=_re_v414.sub(r"tak-map-v\d+","tak-map-v442",_html)
        _html=_re_v414.sub(r"(<span[^>]*class=[\"'][^\"']*iteration-(?:chip|marker)[^\"']*[\"'][^>]*>)[vi]\d+(</span>)",r"\1i442\2",_html,flags=_re_v414.I)
        _html=_re_v414.sub(r"(<div[^>]*class=[\"'][^\"']*iteration-marker[^\"']*[\"'][^>]*>)[vi]\d+(</div>)",r"\1i442\2",_html,flags=_re_v414.I)
        _html=_re_v414.sub(r"(<[^>]+data-iteration=[\"'])[vi]\d+([\"'][^>]*>)",r"\1i442\2",_html,flags=_re_v414.I)
        _html=_re_v414.sub(r"(<span[^>]*class=[\"'][^\"']*release-main[^\"']*[\"'][^>]*>)\d+\.\d+\.\d+(</span>)",r"\g<1>1.3.0\g<2>",_html,flags=_re_v414.I)
        _html=_re_v414.sub(r"(<[^>]+data-release=[\"'])\d+\.\d+\.\d+([\"'][^>]*>)",r"\g<1>1.3.0\g<2>",_html,flags=_re_v414.I)
        # Version is shown only in the sidebar footer. Remove any header badge
        # injected by older packages before the response reaches the browser.
        _html=_re_v414.sub(r"<span[^>]*(?:id=[\"']takMapHeaderRelease[^\"']*[\"']|class=[\"'][^\"']*tak-map-header-release[^\"']*[\"'])[^>]*>[\s\S]*?</span>","",_html,flags=_re_v414.I)
        return _html
    def _tak_v415_add(_html):
        if not isinstance(_html,str): return _html
        _html=re.sub(r'<script[^>]*id=["\']v415ReplayModeIntegrationPatch["\'][\s\S]*?</script>','',_html,flags=re.I)
        _html=_tak_v415_versions(_html)
        if 'id="v415ReplayModeIntegrationPatch"' not in _html:
            _html=_html.replace('</body>',_v415_script+'\n</body>',1) if '</body>' in _html else _html+_v415_script
        return _tak_v415_versions(_html)
