    TAK_MAP_TILE_CACHE_DIR=DATA_DIR/'tak_map_tile_cache'
    TAK_MAP_TILE_CACHE_MAX_BYTES=max(256*1024*1024,int(os.environ.get('TAK_MAP_TILE_CACHE_MAX_BYTES',str(10*1024*1024*1024)) or 0))
