    TAK_MAP_TILE_CACHE_STATS={'hits':0,'misses':0,'stores':0,'errors':0,'stale_served':0,'prefetch_requests':0,'interactive_requests':0,'bytes':None,'last_prune':0,'evictions':0,'policy_skips':0,'key_locks':0}

    def _i462_tile_paths(provider,z,x,y):
        safe=re.sub(r'[^A-Za-z0-9_.-]+','-',str(provider or '')).strip('-_.')[:80]
