    def _i491_adsb_visibility_patch_html(html):
        if not isinstance(html,str): return html
        renderer=r"""function renderAircraft(input){const layer=ensureLayer();if(!layer)return [];const allRows=normalizeList(input),rows=filtered(allRows);ADSB.lastList=allRows.slice();ADSB.lastGoodAt=Date.now();window.lastAircraft=allRows.slice();ADSB.data.clear();allRows.forEach(function(a){ADSB.data.set(idOf(a),a)});const seen=new Set();rows.forEach(function(a){const id=idOf(a);seen.add(id);let mk=ADSB.markers.get(id);const ll=[a.lat,a.lon];if(!mk){mk=L.marker(ll,{icon:iconFor(a),zIndexOffset:900,interactive:true,riseOnHover:true}).addTo(layer);ADSB.markers.set(id,mk);mk.on('popupopen',function(){setTimeout(syncButtons,20)});}else{mk.setLatLng(ll);const el=mk.getElement&&mk.getElement();const img=el&&el.querySelector&&el.querySelector('img');const lab=el&&el.querySelector&&el.querySelector('.aircraft-label');const want=iconPath(a);if(img){try{if(!(String(img.getAttribute('src')||'').endsWith(want)))img.src=want;img.style.transform='rotate('+((n(a.track_deg??a.track??a.heading)||0))+'deg)'}catch(_){}}else{try{mk.setIcon(iconFor(a))}catch(_){}}if(lab)lab.textContent=titleOf(a,id)}try{mk._takAdsbAircraft=a;mk._takAdsbId=id;if(!mk.isPopupOpen()){mk.bindPopup(popupHtml(a),{className:'adsb-v309-popup adsb-object-popup',autoPan:false,closeButton:false,autoClose:false,closeOnClick:false});try{if(mk.__v463LifecycleBound&&mk._openPopup)mk.off('click',mk._openPopup,mk)}catch(_){}}else mk.setPopupContent(popupHtml(a))}catch(_){}if(ADSB.tracking.id===id)addTrackPoint(a)});ADSB.markers.forEach(function(mk,id){if(seen.has(id))return;try{const interp=window.TakMapLiveInterpolationV476||window.TakMapLiveInterpolationV477;interp&&interp.cancel&&interp.cancel(mk)}catch(_){}try{layer.removeLayer(mk)}catch(_){}ADSB.markers.delete(id);if(ADSB.tracking.id===id){try{clearTrackVisual()}catch(_){}ADSB.tracking.id=null;ADSB.tracking.meta=null;ADSB.tracking.points=[]}});publishMaps();updateStatus(rows.length);syncButtons();return rows}"""
        pattern=r"function renderAircraft\(input\)\{const layer=ensureLayer\(\);if\(!layer\)return \[\];.*?publishMaps\(\);updateStatus\(rows.length\);syncButtons\(\);return rows\}"
        html,count=_i491_adsb_re.subn(pattern,renderer,html,count=1,flags=_i491_adsb_re.S)
        if count!=1:
            raise RuntimeError('i491 active ADS-B renderer replacement count '+str(count))
        redraw=r"""function redrawAdsbFiltered(){try{const api=window.TakMapAdsbWorkerV477||window.TakMapAdsbWorkerV476;if(api&&typeof api.refreshVisibility==='function')return api.refreshVisibility();window.__takMapAdsbExplicitClear=true;window.__adsbForceClear=true;window.__takMapAllowExternalAdsbDraw=true;if(typeof window.drawAircraft==='function')window.drawAircraft(window.lastAircraft||[]);else if(typeof drawAircraft==='function')drawAircraft(window.lastAircraft||[])}catch(e){console.warn('i491 ADS-B redraw failed',e)}finally{setTimeout(function(){window.__takMapAdsbExplicitClear=false;window.__adsbForceClear=false;window.__takMapAllowExternalAdsbDraw=false},120)}}"""
        html,count=_i491_adsb_re.subn(r"function redrawAdsbFiltered\(\)\{try\{window\.__takMapAdsbExplicitClear=true;.*?\}\s*(?=function bindAdsbAutosave)",redraw+'\n  ',html,count=1,flags=_i491_adsb_re.S)
        if count!=1:
            raise RuntimeError('i491 ADS-B redraw replacement count '+str(count))
        html=html.replace("setInterval(()=>{if(state.live.adsb_aircraft)refreshAdsb()},30000);","/* i491 dedicated ADS-B worker owns polling cadence */")
        return html

    TAK_MAP_HTML=_i491_adsb_visibility_patch_html(TAK_MAP_HTML); INDEX_HTML=TAK_MAP_HTML
