    def _i506_gateway_family(*values):
        text=' '.join(str(v or '') for v in values).lower().replace('_','-')
        kind='street' if any(x in text for x in ('street','strt','road')) else 'imagery' if any(x in text for x in ('imagery','img','satellite')) else ''
        provider=''
        if 'rainviewer' in text: provider='rainviewer'
        elif 'imerg' in text: provider='imerg'
        elif 'goes-18' in text or 'goes18' in text: provider='goes18'
        elif 'goes-19' in text or 'goes19' in text: provider='goes19'
        elif 'noaa' in text or 'radar' in text: provider='noaa'
        return (provider+'-'+kind).strip('-') if provider else ''

    def _i506_management_source(row):
        text=' '.join(str((row or {}).get(k) or '') for k in ('label','gateway_catalog_id','source_xml_name','upstream_url')).lower()
        if 'rainviewer' in text: return 'RainViewer'
        if 'imerg' in text: return 'NASA IMERG'
        if 'goes-18' in text or 'goes18' in text: return 'GOES-18 Pacific'
        if 'goes-19' in text or 'goes19' in text: return 'GOES-19 Atlantic'
        if 'noaa' in text or 'radar' in text: return 'NOAA Radar'
        return 'TAK Gateway' if str((row or {}).get('source_kind') or '')=='tak-gateway' else 'Custom XML'

    _i506_original_save_custom_basemaps = _i505_save_custom_basemaps
    def _i506_save_custom_basemaps(rows):
        TAK_MAP_OFFLINE_DIR.mkdir(parents=True, exist_ok=True)
        final=list(rows or [])[-TAK_MAP_CUSTOM_BASEMAP_LIMIT:]
        atomic_write_json(TAK_MAP_CUSTOM_BASEMAPS_FILE, {'version':'i506','basemaps':final,'updated':datetime.now(timezone.utc).isoformat()})
        return final
    _i505_save_custom_basemaps = _i506_save_custom_basemaps

    _i506_original_public_basemap = _i505_public_basemap
    def _i506_public_basemap(row):
        item=_i506_original_public_basemap(row)
        item['managementSource']=_i506_management_source(row)
        item['managementType']='gateway' if str((row or {}).get('source_kind') or '')=='tak-gateway' else 'custom'
        if (row or {}).get('gateway_catalog_id'):
            item['gatewayCatalogId']=str((row or {}).get('gateway_catalog_id'))
        return item
    _i505_public_basemap = _i506_public_basemap

    def _i506_result(message='', imported=None, errors=None, **extra):
        custom=_i505_public_custom_basemaps()
        result={'ok':not bool(errors and not imported),'version':'i506','message':message,'imported':imported or [],'errors':errors or [],'custom_basemaps':custom,'basemaps':tak_map_config().get('basemaps') or [],'storage':str(TAK_MAP_CUSTOM_BASEMAPS_FILE)}
        result.update(extra)
        return result
    _i505_custom_basemap_result = _i506_result

    def _i506_fetch_gateway_json(url):
        req=_i505_urlreq.Request(url,headers={'Accept':'application/json','User-Agent':'TAK-Map/1.3.0-i506 Gateway-Basemap-Catalog'})
        with _i505_urlreq.urlopen(req,timeout=TAK_MAP_GATEWAY_BASEMAP_TIMEOUT) as resp:
            body=resp.read(TAK_MAP_GATEWAY_CATALOG_LIMIT+1)
            if len(body)>TAK_MAP_GATEWAY_CATALOG_LIMIT:
                raise ValueError('Gateway basemap catalog exceeds the configured size limit.')
            return json.loads(body.decode('utf-8','replace') or '{}')

    def _i506_catalog_rows(payload):
        if isinstance(payload,list): return payload
        if not isinstance(payload,dict): return []
        for key in ('basemaps','items','rows','sources','catalog','maps'):
            rows=payload.get(key)
            if isinstance(rows,list): return rows
        return []

    def _i506_catalog_candidates(base,payload):
        out=[];seen=set();base_parsed=urlparse(base)
        for raw in _i506_catalog_rows(payload):
            if isinstance(raw,str):
                row={'id':raw,'name':raw}
            elif isinstance(raw,dict):
                row=raw
            else:
                continue
            bid=str(row.get('id') or row.get('basemap_id') or row.get('xml_id') or row.get('slug') or '').strip()
            name=str(row.get('name') or row.get('label') or row.get('title') or bid).strip()
            group=str(row.get('group') or row.get('category') or row.get('type') or '').strip()
            hay=(bid+' '+name+' '+group).lower()
            if not (bid.lower().startswith('tg-') or name.lower().startswith('tg-') or 'composite' in hay or any(p in hay for p in ('rainviewer','imerg','goes-18','goes18','goes-19','goes19'))):
                continue
            xml_ref=str(row.get('xml_url') or row.get('xmlUrl') or row.get('href') or row.get('url') or '').strip()
            if xml_ref:
                xml_url=_i506_urljoin(base.rstrip('/')+'/',xml_ref)
                parsed=urlparse(xml_url)
                if parsed.hostname!=base_parsed.hostname or parsed.port!=base_parsed.port:
                    xml_url=''
            else:
                xml_url=''
            if not xml_url and bid:
                xml_url=base.rstrip('/')+'/basemaps/xml/'+quote(bid,safe='')+'.xml'
            if not bid or not xml_url or bid in seen: continue
            seen.add(bid);out.append({'id':bid,'name':name,'xml_url':xml_url,'group':group})
        return out

    def _i506_parse_gateway_xml(blob,xml_id,xml_url='',catalog_source='fallback'):
        item=_i505_parse_basemap_xml(blob,xml_id+'.xml','tak-gateway')
        item['gateway_catalog_id']=str(xml_id or '')[:160]
        item['gateway_catalog_source']=str(catalog_source or '')[:200]
        item['gateway_xml_url']=str(xml_url or '')[:500]
        item['management_source']=_i506_management_source(item)
        return item

    def _i506_import_gateway_basemaps():
        base=_i505_gateway_asset_base()
        if not base:
            return {'ok':False,'version':'i506','error':'TAK Gateway basemap address is not configured. Set TAK_MAP_GATEWAY_BASEMAP_URL or configure the existing Gateway Replay address.'}
        imported=[];warnings=[];catalog_source='';catalog_entries=0;attempted_ids=[]
        imported_hashes=set();families=set()

        for path in _I506_GATEWAY_CATALOG_PATHS:
            url=base.rstrip('/')+path
            try:
                payload=_i506_fetch_gateway_json(url)
                candidates=_i506_catalog_candidates(base,payload)
                if not candidates:
                    continue
                catalog_source=url;catalog_entries=len(candidates)
                for candidate in candidates:
                    bid=candidate['id'];attempted_ids.append(bid)
                    try:
                        item=_i506_parse_gateway_xml(_i505_fetch_gateway_xml(candidate['xml_url']),bid,candidate['xml_url'],url)
                        if item['id'] not in imported_hashes:
                            imported_hashes.add(item['id']);imported.append(item)
                        family=_i506_gateway_family(bid,candidate.get('name'),item.get('label'),item.get('upstream_url'))
                        if family: families.add(family)
                    except Exception as exc:
                        warnings.append({'id':bid,'url':candidate['xml_url'],'error':str(exc)[:240]})
                break
            except Exception:
                continue

        for family,aliases in _I506_GATEWAY_FALLBACK_GROUPS:
            if family in families: continue
            last_error=''
            for bid in aliases:
                if bid in attempted_ids: continue
                attempted_ids.append(bid)
                url=base.rstrip('/')+'/basemaps/xml/'+quote(bid,safe='')+'.xml'
                try:
                    item=_i506_parse_gateway_xml(_i505_fetch_gateway_xml(url),bid,url,'known-id-fallback')
                    if item['id'] not in imported_hashes:
                        imported_hashes.add(item['id']);imported.append(item)
                    families.add(family);last_error='';break
                except Exception as exc:
                    last_error=str(exc)[:240]
            if last_error:
                warnings.append({'family':family,'error':'No hosted XML was found for this composite family.'})

        if imported:
            _i505_upsert_custom_basemaps(imported)
        unavailable=sum(1 for w in warnings if w.get('family'))
        message='Imported or refreshed '+str(len(imported))+' TAK Gateway composite basemap(s).'
        if unavailable:
            message+=' '+str(unavailable)+' known composite family/families were unavailable on this Gateway.'
        result=_i506_result(message,imported,[] if imported else warnings,
            warnings=warnings if imported else [],gateway_base_url=base,catalog_source=catalog_source,
            catalog_entries=catalog_entries,attempted_ids=attempted_ids,composite_families=sorted(families))
        if not imported:
            result['ok']=False;result['error']='Could not import any TAK Gateway composite basemap XMLs.'
        return result
    _i505_import_gateway_basemaps = _i506_import_gateway_basemaps

    def _i506_bulk_delete(scope):
        scope=str(scope or '').strip().lower()
        rows=_i505_load_custom_basemaps()
        if scope in ('gateway','tak-gateway','composite'):
            removed=[x for x in rows if str(x.get('source_kind') or '')=='tak-gateway']
            kept=[x for x in rows if str(x.get('source_kind') or '')!='tak-gateway']
            label='TAK Gateway composite import'
        elif scope in ('custom','manual','xml'):
            removed=[x for x in rows if str(x.get('source_kind') or '')!='tak-gateway']
            kept=[x for x in rows if str(x.get('source_kind') or '')=='tak-gateway']
            label='custom XML basemap'
        elif scope in ('all',''):
            removed=rows;kept=[];label='imported basemap'
        else:
            return {'ok':False,'version':'i506','error':'Unknown basemap removal scope.'}
        _i506_save_custom_basemaps(kept)
        count=len(removed)
        return _i506_result('Removed '+str(count)+' '+label+('s' if count!=1 else '')+'.',removed=[],errors=[],removed_ids=[str(x.get('id') or '') for x in removed],removed_count=count,scope=scope or 'all')

    _i506_prev_config=tak_map_config
