    def _i506_patch_html(html):
        if not isinstance(html,str): return html
        html=html.replace('1.3.0-i505','1.3.0-i506').replace('TAKDashboard/i505','TAKDashboard/i506').replace('TAK-Map/1.3.0 i505','TAK-Map/1.3.0 i506')
        html=_i491_re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)',r'\1i506\2',html)
        old_relief='<div class="relief-controls"><label><input type="checkbox" id="reliefOverlayToggle" onchange="toggleReliefOverlay(this.checked)"> USGS Shaded Relief</label><input id="reliefOpacity" type="range" min="0" max="100" value="35" oninput="setReliefOpacity(this.value)"></div>'
        new_relief='<div class="relief-controls tak-relief-controls-v506"><input type="checkbox" id="reliefOverlayToggle" aria-hidden="true"><button id="reliefOverlayButtonV506" class="tak-relief-toggle-v506" type="button" aria-pressed="false" onclick="toggleReliefButtonV506()">USGS Shaded Relief</button><input id="reliefOpacity" type="range" min="0" max="100" value="35" oninput="setReliefOpacity(this.value)"></div>'
        if old_relief in html: html=html.replace(old_relief,new_relief,1)
        old_buttons='<button class="layer-button" onclick="triggerBasemapXmlImport()">Add Basemap</button><button class="layer-button" onclick="importTakGatewayBasemapsV505()">Import Gateway</button><button class="layer-button" onclick="clearCustomBasemaps()">Clear Custom</button>'
        new_buttons='<button class="layer-button" onclick="triggerBasemapXmlImport()">Add Basemap</button><button class="layer-button" onclick="importTakGatewayBasemapsV506()">Import Gateway</button><button class="layer-button" onclick="openBasemapManagerV506()">Manage Basemaps</button>'
        if old_buttons in html: html=html.replace(old_buttons,new_buttons,1)
        rows='<div id="customBasemapRowsV505"></div>'
