        if sess: _I512_REQUEST_CONTEXT.identity={'username':sess.get('username'),'callsign':sess.get('callsign'),'tak_uid':sess.get('tak_uid') or (sess.get('profile') or {}).get('tak_uid')}
        try: return _i512_do_post_before(self)
        finally: _I512_REQUEST_CONTEXT.identity={}
