    def _i517_post(self):
        path = urlparse(self.path).path
        mutation = path in ('/api/tak-map/custom-basemap-upload','/api/tak-map/custom-basemap-import-gateway')
        removal = path in ('/api/tak-map/custom-basemap-delete','/api/tak-map/custom-basemap-clear','/api/tak-map/custom-basemap-bulk-delete')
        if removal:
            if not self._tak_map_auth_ok():
                return self._require_tak_map_login()
            sess = self._tak_map_session() or {}
            if not bool(sess.get('is_admin')):
                return self._send_json({'ok':False,'version':'i517','error':'Removing shared imported basemaps requires an administrator account.','admin_required':True},403)
        if mutation:
            sess = self._tak_map_session() or {}
            _I517_IMPORT_CONTEXT.username = str(sess.get('username') or (sess.get('profile') or {}).get('username') or '')
        try:
            return _i517_post_before(self)
        finally:
            if mutation:
                _I517_IMPORT_CONTEXT.username = ''
    Handler.do_POST = _i517_post

