    def _i528_filter_live_rows(rows):
        kept = []
        removed = []
        for row in rows or []:
            if _i528_is_mission_point_live_row(row):
                if len(removed) < 80:
                    values, labels = _i528_row_identity(row)
                    removed.append({'uids': sorted(values)[:6], 'labels': sorted(labels)[:6], 'reason': 'Mission-backed point is authoritative in Data Sync and must not render/list as an EUD or live CoT duplicate.'})
                continue
            kept.append(row)
        return kept, removed

