    def _i529_version_html(html):
        if not isinstance(html, str):
            return html
        html = re.sub(r'1\.3\.0-i\d+', '1.3.0-i529', html)
        html = re.sub(r'TAKDashboard/i\d+', 'TAKDashboard/i529', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i\d+', 'TAK-Map/1.3.0 i529', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i529\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i529\2', html)
        return html

    def _i529_patch_html(html):
        html = _i529_version_html(html)
        if not isinstance(html, str):
            return html
        html = re.sub(r'<script[^>]*id=["\']takMapPerUserDataSyncIdentityI529["\'][^>]*>[\s\S]*?</script>\s*', '', html, flags=re.I)
        return html.replace('</body>', _I529_RUNTIME + '\n</body>', 1) if '</body>' in html else html + _I529_RUNTIME

    TAK_MAP_HTML = _i529_patch_html(TAK_MAP_HTML)
    INDEX_HTML = TAK_MAP_HTML
    TAK_MAP_LOGIN_HTML = _i529_version_html(TAK_MAP_LOGIN_HTML)
    LOGIN_HTML = TAK_MAP_LOGIN_HTML
    TAK_MAP_ITERATION = 'i529'

    _i529_config_before = tak_map_config
    def tak_map_config():
        cfg = _i529_config_before()
        if not isinstance(cfg, dict):
            return cfg
        cfg = dict(cfg)
        cfg['tak_map_iteration'] = 'i529'
        cfg['version'] = '1.3.0-i529'
        ots = dict(cfg.get('ots_integration') or {})
        ots.update({
            'version': 'i529',
            'per_user_marti_certificate_required': True,
            'automatic_certificate_enrollment_at_login': True,
            'certificate_cn_matches_ots_username': True,
            'private_key_encrypted_at_rest': True,
            'private_key_never_sent_to_browser': True,
            'user_password_not_retained_after_enrollment': True,
            'shared_service_certificate_fallback': False,
            'user_write_blocked_when_identity_unavailable': True,
        })
        cfg['ots_integration'] = ots
        native = dict(cfg.get('data_sync_native_point_publish') or {})
        native.update({
            'version': 'i529',
            'identity_mode': 'per-user-enrolled-marti-certificate',
            'shared_service_certificate_fallback': False,
            'synthetic_creator_uid_without_certificate_disabled': True,
            'user_certificate_required': True,
        })
        cfg['data_sync_native_point_publish'] = native
        return cfg
    globals()['tak_map_config'] = tak_map_config

