    def _i531_wait_for_cot_ingest(event_uid, timeout_seconds=15.0):
        uid = _i529_text(event_uid)
        if not uid:
            return {
                'ok': False,
                'source': 'opentakserver-cot-database',
                'error': 'No exact mission-object UID was available for CoT ingest confirmation.',
                'attempts': [],
            }
        try:
            timeout_seconds = max(2.0, min(float(timeout_seconds or 15.0), 20.0))
        except Exception:
            timeout_seconds = 15.0
        deadline = time.monotonic() + timeout_seconds
        attempts = []
        while True:
            try:
                result = _cot_db_lookup(uid, '', '', '', timeout=3)
            except Exception as exc:
                result = {'ok': False, 'error': str(exc), 'rows': []}
            rows = list(result.get('rows') or []) if isinstance(result, dict) else []
            exact_rows = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                row_uid = _i529_text(row.get('uid'))
                xml_preview = _i529_text(row.get('xml_preview'))
                if row_uid == uid or uid in xml_preview:
                    exact_rows.append(row)
            attempts.append({
                'ok': bool(exact_rows),
                'error': _i529_text(result.get('error'))[:300] if isinstance(result, dict) else '',
                'row_count': len(rows),
                'exact_row_count': len(exact_rows),
            })
            if exact_rows:
                return {
                    'ok': True,
                    'source': 'opentakserver-cot-database-exact-uid',
                    'event_uid': uid,
                    'rows': exact_rows[:4],
                    'attempts': attempts,
                }
            error = _i529_text(result.get('error')).lower() if isinstance(result, dict) else ''
            if 'no opentakserver postgresql uri' in error:
                return {
                    'ok': False,
                    'source': 'opentakserver-cot-database',
                    'event_uid': uid,
                    'error': result.get('error'),
                    'attempts': attempts,
                }
            if time.monotonic() >= deadline:
                return {
                    'ok': False,
                    'source': 'opentakserver-cot-database-exact-uid',
                    'event_uid': uid,
                    'error': 'The exact mission-object UID was not visible in the OpenTAKServer CoT database before the ingest timeout.',
                    'attempts': attempts,
                }
            time.sleep(0.35)

    globals()['_i531_wait_for_cot_ingest'] = _i531_wait_for_cot_ingest

