    def _i531_associate_uid(mission, creator_uid, uid, token='', server_host=''):
        mission_q = quote(_i529_text(mission), safe='')
        creator_q = quote(_i529_text(creator_uid), safe='')
        path = f'/Marti/api/missions/{mission_q}/contents?creatorUid={creator_q}'
        body = json.dumps({'uids': [_i529_text(uid)]}).encode('utf-8')
        attempts = []
        for number in range(1, 7):
            result = _ots_mission_api_request(
                path,
                method='PUT',
                body=body,
                headers={'Content-Type': 'application/json', 'Content-Length': str(len(body))},
                token=token,
                public_host=server_host,
                timeout=25,
            )
            record = dict(result or {})
            record.update({
                'attempt': number,
                'method': 'PUT',
                'path': path,
                'body_variant': 'uids-json',
                'event_uid': _i529_text(uid),
            })
            attempts.append(record)
            status = int(record.get('status') or 0)
            if record.get('ok') or status == 409:
                out = dict(record)
                out['ok'] = True
                out['attempts'] = attempts
                out['association_endpoint'] = 'mission-contents-uids'
                out['already_associated'] = status == 409
                out['provisional_until_exact_cot_readback'] = status == 409
                return out
            if status in (400, 401, 403, 405):
                break
            if number < 6:
                time.sleep(0.4)
        return {
            'ok': False,
            'error': 'Mission UID association through PUT /contents failed.',
            'event_uid': _i529_text(uid),
            'association_endpoint': 'mission-contents-uids',
            'attempts': attempts,
        }

