    _I532_TOKEN_KEYS = {}
    _I532_HEARTBEAT_SECONDS = 30.0
    _I532_RECONNECT_SECONDS = 5.0

    _i532_certificate_status_before = _i529_public_certificate_status
    def _i529_public_certificate_status(username, expected_uid=''):
        status = _i532_certificate_status_before(username, expected_uid)
        if isinstance(status, dict):
            status = dict(status)
            status['version'] = 'i532'
            status['shared_service_fallback'] = False
        return status
    globals()['_i529_public_certificate_status'] = _i529_public_certificate_status

    def _i532_session_snapshot(token):
        token = _i529_text(token)
        if not token:
            return {}
        with TAK_MAP_SESSIONS_LOCK:
            sess = TAK_MAP_SESSIONS.get(token)
            if not isinstance(sess, dict):
                return {}
            if float(sess.get('expires') or 0) <= time.time():
                return {}
            return dict(sess)

    def _i532_session_identity(sess):
        sess = sess if isinstance(sess, dict) else {}
        profile = dict(sess.get('profile') or {})
        username = _i529_text(profile.get('username') or sess.get('username'))
        callsign = _i529_text(
            profile.get('selected_callsign')
            or profile.get('callsign')
            or profile.get('suggested_callsign')
            or sess.get('callsign')
            or sess.get('display_identity')
            or username
        )
        uid = _i529_text(sess.get('tak_uid') or profile.get('tak_uid'))
        return {'username': username, 'callsign': callsign, 'uid': uid}

    def _i532_presence_key(sess):
        ident = _i532_session_identity(sess)
        return (_i529_text(ident.get('uid')) or ('user:' + _i529_text(ident.get('username')))).lower()

    def _i532_session_credential(sess):
        ident = _i532_session_identity(sess)
        status = dict(_i529_public_certificate_status(ident.get('username'), ident.get('uid')) or {})
        status['username'] = ident.get('username') or status.get('username')
        status['client_uid'] = ident.get('uid') or status.get('client_uid')
        status['callsign'] = ident.get('callsign')
        return status

    def _i532_presence_xml(sess, credential):
        ident = _i532_session_identity(sess)
        client_uid = _i529_text(ident.get('uid') or credential.get('client_uid'))
        username = _i529_text(ident.get('username') or credential.get('username') or credential.get('certificate_cn'))
        callsign = _i529_text(ident.get('callsign') or username or credential.get('certificate_cn'))
        if not client_uid:
            return {'ok': False, 'error': 'The authenticated OTS user has no stable TAK UID for persistent EUD presence.'}
        if not callsign:
            return {'ok': False, 'error': 'The authenticated OTS user has no callsign or username for persistent EUD presence.'}
        now = datetime.now(timezone.utc)
        stale = now + timedelta(minutes=3)
        event = ET.Element('event', {
            'version': '2.0',
            'uid': client_uid,
            'type': 'a-f-G-U-C',
            'how': 'm-g',
            'time': _cot_time(now),
            'start': _cot_time(now),
            'stale': _cot_time(stale),
            'access': 'Undefined',
        })
        ET.SubElement(event, 'point', {
            'lat': '0.0000000',
            'lon': '0.0000000',
            'hae': '0',
            'ce': '9999999.0',
            'le': '9999999.0',
        })
        detail = ET.SubElement(event, 'detail')
        ET.SubElement(detail, 'contact', {'callsign': callsign, 'endpoint': '*:-1:stcp'})
        ET.SubElement(detail, 'uid', {'Droid': callsign})
        ET.SubElement(detail, 'takv', {
            'device': 'TAK Map',
            'platform': 'TAK Map',
            'os': 'Web',
            'version': '1.3.0-i532',
        })
        ET.SubElement(detail, '__group', {'name': 'Cyan', 'role': 'Team Member'})
        ET.SubElement(detail, 'status', {'battery': '100'})
        ET.SubElement(detail, 'track', {'course': '0.0', 'speed': '0.0'})
        ET.SubElement(detail, 'takmap_user_presence', {
            'version': 'i532',
            'purpose': 'persistent-authenticated-web-session-eud',
            'username': username,
            'callsign': callsign,
            'missionObject': 'false',
            'serviceCredentialFallback': 'false',
        })
        xml = '<?xml version="1.0" encoding="UTF-8"?>\n' + ET.tostring(event, encoding='unicode', short_empty_elements=True)
        return {'ok': True, 'xml': xml, 'uid': client_uid, 'callsign': callsign, 'username': username}

    def _i532_close_locked(state, reason='disconnected'):
        tls = state.get('tls')
        state['tls'] = None
        if tls is not None:
            try:
                tls.shutdown(socket.SHUT_RDWR)
            except Exception:
                pass
            try:
                tls.close()
            except Exception:
                pass
        state['connected'] = False
        state['state'] = 'disconnected'
        state['disconnect_reason'] = _i529_text(reason)
        state['disconnected_at'] = datetime.now(timezone.utc).isoformat()

    def _i532_live_session(state):
        live = []
        for token in list(state.get('tokens') or set()):
            sess = _i532_session_snapshot(token)
            if sess and _i529_text(sess.get('auth_mode')).startswith('ots-'):
                live.append((token, sess))
            else:
                state['tokens'].discard(token)
                with _I532_PRESENCE_GUARD:
                    _I532_TOKEN_KEYS.pop(token, None)
        if not live:
            return '', {}
        live.sort(key=lambda pair: float(pair[1].get('created') or 0), reverse=True)
        return live[0]

    def _i532_connect_locked(state, sess):
        credential = _i532_session_credential(sess)
        if not credential.get('ok'):
            raise RuntimeError('Per-user OTS certificate unavailable: ' + _i529_text(credential.get('error')))
        cfg = _i509_load_ots_config()
        host, port = _i531_cot_endpoint(cfg)
        presence = _i532_presence_xml(sess, credential)
        if not presence.get('ok'):
            raise RuntimeError(_i529_text(presence.get('error')))
        _i532_close_locked(state, 'reconnecting')
        ctx = _i529_strict_tls_context(cfg, credential.get('ca_chain_path'))
        ctx.load_cert_chain(
            credential['certificate_path'],
            credential['private_key_path'],
            password=credential['key_password'],
        )
        raw = socket.create_connection((host, int(port)), timeout=8)
        try:
            raw.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
        except Exception:
            pass
        try:
            raw.settimeout(10)
            tls = ctx.wrap_socket(raw, server_hostname=host)
        except Exception:
            try:
                raw.close()
            except Exception:
                pass
            raise
        payload = _normalize_traditional_xml_stream_doc(presence['xml']).encode('utf-8')
        tls.sendall(payload)
        state.update({
            'tls': tls,
            'connected': True,
            'state': 'connected',
            'host': host,
            'port': int(port),
            'certificate_cn': credential.get('certificate_cn'),
            'client_uid': presence.get('uid'),
            'callsign': presence.get('callsign'),
            'username': presence.get('username'),
            'connected_at': datetime.now(timezone.utc).isoformat(),
            'last_heartbeat_at': datetime.now(timezone.utc).isoformat(),
            'last_heartbeat_monotonic': time.monotonic(),
            'last_error': '',
            'disconnect_reason': '',
        })
        return presence

    def _i532_send_presence_locked(state, sess, force=False):
        current = _i532_session_identity(sess)
        age = time.monotonic() - float(state.get('last_heartbeat_monotonic') or 0)
        changed = _i529_text(current.get('callsign')) != _i529_text(state.get('callsign'))
        if not force and state.get('tls') is not None and age < _I532_HEARTBEAT_SECONDS and not changed:
            return {'ok': True, 'uid': state.get('client_uid'), 'callsign': state.get('callsign')}
        if state.get('tls') is None:
            return _i532_connect_locked(state, sess)
        credential = _i532_session_credential(sess)
        presence = _i532_presence_xml(sess, credential)
        if not presence.get('ok'):
            raise RuntimeError(_i529_text(presence.get('error')))
        state['tls'].sendall(_normalize_traditional_xml_stream_doc(presence['xml']).encode('utf-8'))
        state.update({
            'callsign': presence.get('callsign'),
            'username': presence.get('username'),
            'client_uid': presence.get('uid'),
            'last_heartbeat_at': datetime.now(timezone.utc).isoformat(),
            'last_heartbeat_monotonic': time.monotonic(),
            'connected': True,
            'state': 'connected',
            'last_error': '',
        })
        return presence

    def _i532_presence_worker(key, state):
        try:
            while not state['stop'].is_set():
                token, sess = _i532_live_session(state)
                if not token or not sess:
                    break
                delay = _I532_HEARTBEAT_SECONDS
                try:
                    with state['io_lock']:
                        _i532_send_presence_locked(state, sess, force=state.get('tls') is None)
                except Exception as exc:
                    with state['io_lock']:
                        state['last_error'] = str(exc)
                        state['state'] = 'reconnecting'
                        _i532_close_locked(state, 'connection-error')
                    delay = _I532_RECONNECT_SECONDS
                state['wake'].wait(delay)
                state['wake'].clear()
        finally:
            with state['io_lock']:
                _i532_close_locked(state, 'logout-or-session-expired')
            with _I532_PRESENCE_GUARD:
                if _I532_PRESENCE.get(key) is state:
                    _I532_PRESENCE.pop(key, None)
                for token in list(state.get('tokens') or set()):
                    if _I532_TOKEN_KEYS.get(token) == key:
                        _I532_TOKEN_KEYS.pop(token, None)

    def _i532_ensure_presence(token, sess=None):
        token = _i529_text(token)
        sess = dict(sess or _i532_session_snapshot(token) or {})
        if not token or not sess or not _i529_text(sess.get('auth_mode')).startswith('ots-'):
            return {'ok': False, 'state': 'not-applicable', 'connected': False, 'error': 'Persistent EUD presence requires an authenticated OpenTAKServer session.'}
        key = _i532_presence_key(sess)
        if not key:
            return {'ok': False, 'state': 'unavailable', 'connected': False, 'error': 'No stable per-user identity is available for persistent EUD presence.'}
        start = False
        with _I532_PRESENCE_GUARD:
            state = _I532_PRESENCE.get(key)
            if state is None or state.get('stop').is_set():
                state = {
                    'key': key,
                    'tokens': set(),
                    'stop': threading.Event(),
                    'wake': threading.Event(),
                    'io_lock': threading.RLock(),
                    'tls': None,
                    'connected': False,
                    'state': 'starting',
                    'last_error': '',
                }
                _I532_PRESENCE[key] = state
                start = True
            state['tokens'].add(token)
            _I532_TOKEN_KEYS[token] = key
        if start:
            thread = threading.Thread(target=_i532_presence_worker, args=(key, state), name='tak-map-i532-eud-' + hashlib.sha256(key.encode()).hexdigest()[:8], daemon=True)
            state['thread'] = thread
            thread.start()
        else:
            state['wake'].set()
        return _i532_presence_public(token, state)

    def _i532_presence_public(token='', state=None):
        token = _i529_text(token)
        if state is None:
            with _I532_PRESENCE_GUARD:
                key = _I532_TOKEN_KEYS.get(token, '')
                state = _I532_PRESENCE.get(key)
        if not isinstance(state, dict):
            return {'ok': False, 'version': 'i532', 'state': 'disconnected', 'connected': False, 'persistent': True}
        return {
            'ok': bool(state.get('connected')),
            'version': 'i532',
            'state': _i529_text(state.get('state') or ('connected' if state.get('connected') else 'starting')),
            'connected': bool(state.get('connected')),
            'persistent': True,
            'username': _i529_text(state.get('username')),
            'callsign': _i529_text(state.get('callsign')),
            'client_uid': _i529_text(state.get('client_uid')),
            'certificate_cn': _i529_text(state.get('certificate_cn')),
            'connected_at': _i529_text(state.get('connected_at')),
            'last_heartbeat_at': _i529_text(state.get('last_heartbeat_at')),
            'last_error': _i529_text(state.get('last_error')),
            'heartbeat_seconds': int(_I532_HEARTBEAT_SECONDS),
            'shared_service_fallback': False,
        }

    def _i532_remove_session_token(token, reason='logout'):
        token = _i529_text(token)
        if not token:
            return
        with _I532_PRESENCE_GUARD:
            key = _I532_TOKEN_KEYS.pop(token, '')
            state = _I532_PRESENCE.get(key)
            if not state:
                return
            state['tokens'].discard(token)
            has_live = any(_i532_session_snapshot(candidate) for candidate in list(state['tokens']))
            if not has_live:
                state['stop'].set()
                state['wake'].set()
                with state['io_lock']:
                    _i532_close_locked(state, reason)

    def _i532_stop_all_presence(reason='service-shutdown'):
        with _I532_PRESENCE_GUARD:
            states = list(_I532_PRESENCE.values())
        for state in states:
            state['stop'].set()
            state['wake'].set()
            with state['io_lock']:
                _i532_close_locked(state, reason)

    _i532_atexit.register(_i532_stop_all_presence)

    if '_i512_disconnect_ots' in globals():
        _i532_disconnect_ots_before = _i512_disconnect_ots
        def _i512_disconnect_ots():
            result = _i532_disconnect_ots_before()
            if isinstance(result, dict) and result.get('ok'):
                _i532_stop_all_presence('ots-disconnect')
            return result
        globals()['_i512_disconnect_ots'] = _i512_disconnect_ots

    _i532_destroy_session_before = destroy_tak_map_session
    def destroy_tak_map_session(token):
        _i532_remove_session_token(token, 'logout')
        return _i532_destroy_session_before(token)
    globals()['destroy_tak_map_session'] = destroy_tak_map_session

    if '_i511_create_profile_session' in globals():
        _i532_create_profile_session_before = _i511_create_profile_session
        def _i511_create_profile_session(username, password, auth_mode, is_admin, auth, profile):
            token = _i532_create_profile_session_before(username, password, auth_mode, is_admin, auth, profile)
            if _i529_text(auth_mode).startswith('ots-'):
                _i532_ensure_presence(token, _i532_session_snapshot(token))
            return token
        globals()['_i511_create_profile_session'] = _i511_create_profile_session

    if '_i512_update_callsign' in globals():
        _i532_update_callsign_before = _i512_update_callsign
        def _i512_update_callsign(sess, raw):
            out = _i532_update_callsign_before(sess, raw)
            username = _i529_text((sess or {}).get('username')).lower()
            with _I532_PRESENCE_GUARD:
                states = [state for state in _I532_PRESENCE.values() if _i529_text(state.get('username')).lower() == username or any(_i529_text((_i532_session_snapshot(token) or {}).get('username')).lower() == username for token in state.get('tokens') or set())]
            for state in states:
                state['wake'].set()
            return out
        globals()['_i512_update_callsign'] = _i512_update_callsign

    def _i532_send_per_user_cot(xml, event_uid=''):
        token = _i529_text(getattr(_I529_REQUEST_CONTEXT, 'session_token', ''))
        sess = _i532_session_snapshot(token)
        if not token or not sess:
            return {
                'ok': False,
                'status': 401,
                'error': 'The authenticated TAK Map session is unavailable for persistent per-user CoT publication.',
                'identity_mode': 'per-user-enrolled-marti-certificate',
                'persistent_user_eud': True,
                'shared_service_fallback': False,
            }
        presence_status = _i532_ensure_presence(token, sess)
        with _I532_PRESENCE_GUARD:
            key = _I532_TOKEN_KEYS.get(token, '')
            state = _I532_PRESENCE.get(key)
        if not state:
            return {'ok': False, 'status': 503, 'error': presence_status.get('error') or 'Persistent per-user EUD connection could not be created.', 'shared_service_fallback': False}
        uid = _i529_text(event_uid)
        if not uid:
            try:
                uid = _cot_xml_ids(xml)[0]
            except Exception:
                uid = ''
        started = time.monotonic()
        last_error = ''
        for attempt in range(1, 3):
            try:
                with state['io_lock']:
                    _i532_send_presence_locked(state, sess, force=False)
                    state['tls'].sendall(_normalize_traditional_xml_stream_doc(xml).encode('utf-8'))
                    state['last_object_uid'] = uid
                    state['last_object_sent_at'] = datetime.now(timezone.utc).isoformat()
                ingest = _i531_wait_for_cot_ingest(uid, 15.0) if uid else {'ok': False, 'error': 'No event UID was available for ingest confirmation.'}
                if not ingest.get('ok'):
                    return {
                        'ok': False,
                        'status': 504,
                        'error': _i529_text(ingest.get('error') or 'The point was not visible in OTS after the persistent CoT write.'),
                        'event_uid': uid,
                        'ingest_confirmation': ingest,
                        'ingest_confirmed': False,
                        'identity_mode': 'per-user-enrolled-marti-certificate',
                        'persistent_user_eud': True,
                        'connection_identity_uid': state.get('client_uid'),
                        'connection_identity_callsign': state.get('callsign'),
                        'point_uid_used_as_eud_identity': False,
                        'shared_service_fallback': False,
                    }
                return {
                    'ok': True,
                    'status': 202,
                    'host': state.get('host'),
                    'port': state.get('port'),
                    'tls': True,
                    'strict_tls': True,
                    'socket_framing': 'traditional-xml',
                    'event_uid': uid,
                    'duration_seconds': round(time.monotonic() - started, 3),
                    'ingest_confirmation': ingest,
                    'ingest_confirmed': True,
                    'identity_mode': 'per-user-enrolled-marti-certificate',
                    'certificate_cn': state.get('certificate_cn'),
                    'client_uid': state.get('client_uid'),
                    'connection_identity_uid': state.get('client_uid'),
                    'connection_identity_callsign': state.get('callsign'),
                    'persistent_user_eud': True,
                    'persistent_connection_reused': True,
                    'mission_object_uid': uid,
                    'point_uid_used_as_eud_identity': False,
                    'shared_service_fallback': False,
                    'plaintext_fallback': False,
                    'http_cot_fallback': False,
                    'mission_cot_write_endpoint_used': False,
                }
            except Exception as exc:
                last_error = str(exc)
                with state['io_lock']:
                    state['last_error'] = last_error
                    _i532_close_locked(state, 'object-send-error')
                    if attempt < 2:
                        try:
                            _i532_connect_locked(state, sess)
                        except Exception as reconnect_exc:
                            last_error = str(reconnect_exc)
                if attempt < 2:
                    time.sleep(0.2)
        return {
            'ok': False,
            'status': 502,
            'error': 'Per-user certificate-authenticated persistent SSL CoT publication failed: ' + last_error,
            'event_uid': uid,
            'identity_mode': 'per-user-enrolled-marti-certificate',
            'persistent_user_eud': True,
            'shared_service_fallback': False,
            'plaintext_fallback': False,
            'http_cot_fallback': False,
        }

    globals()['_i531_send_per_user_cot'] = _i532_send_per_user_cot

    def _i526_send_native_mission_cot(mission, creator_uid, xml, server_host=''):
        event_uids = _cot_xml_ids(xml)
        event_uid = event_uids[0] if event_uids else ''
        result = dict(_i532_send_per_user_cot(xml, event_uid) or {})
        result['mission'] = _i529_text(mission)
        result['creator_uid'] = _i529_text(creator_uid)
        result['publication_stage'] = 'persistent-per-user-ssl-cot-ingest-exact-uid-confirmed'
        result['mission_cot_endpoint'] = 'GET-only; not used for publication'
        result['mission_cot_write_endpoint_used'] = False
        return result
    globals()['_i526_send_native_mission_cot'] = _i526_send_native_mission_cot

    _i532_point_xml_before = _i526_point_xml
    def _i526_point_xml(feature, mission_name, creator_uid=''):
        built = _i532_point_xml_before(feature, mission_name, creator_uid)
        if not isinstance(built, dict) or not built.get('ok'):
            return built
        built = dict(built)
        try:
            root = ET.fromstring(_i529_text(built.get('xml')).encode('utf-8'))
            detail = root.find('detail')
            if detail is not None:
                transport = detail.find('takmap')
                if transport is not None:
                    transport.set('version', 'i532')
                    transport.set('publicationFlow', 'persistent-user-eud-cot-then-mission-uid-association')
                    transport.set('persistentUserEud', 'true')
                point_meta = detail.find('takmap_point')
                if point_meta is not None:
                    point_meta.set('version', 'i532')
                    point_meta.set('publicationFlow', 'persistent-user-eud-cot-then-mission-uid-association')
                    point_meta.set('eudPresence', 'false')
            built['xml'] = '<?xml version="1.0" encoding="UTF-8"?>\n' + ET.tostring(root, encoding='unicode', short_empty_elements=True)
            built['version'] = 'i532'
            built['publication_flow'] = 'persistent-user-eud-cot-then-mission-uid-association'
            built['persistent_user_eud'] = True
            built['mission_object_uid_independent'] = True
        except Exception as exc:
            built['i532_publication_xml_warning'] = str(exc)
        return built
    globals()['_i526_point_xml'] = _i526_point_xml

