    def tak_map_publish_native_points_to_mission_i526(points, mission_name='', server_host='', creator_uid=''):
        result = _i532_native_publish_before(points, mission_name, server_host, creator_uid)
        if isinstance(result, dict):
            result = dict(result)
            result['version'] = 'i532'
            result['publish_mode'] = 'persistent-per-user-cot-mission-uid-i532'
            result['persistent_authenticated_user_eud'] = True
            result['mission_object_uid_independent'] = True
