    _i533_do_get_before = Handler.do_GET
    def _i533_do_get(self):
        parsed = urlparse(self.path)
        if parsed.path == '/api/tak-map/ots/user-certificate':
            sess = self._tak_map_session() if self._tak_map_auth_ok() else None
            if not sess:
                return self._require_tak_map_login()
            if not _i529_text(sess.get('auth_mode')).startswith('ots-'):
                return self._send_json({'ok': False, 'error': 'Per-user Data Sync certificates apply only to OpenTAKServer sessions.', 'version': 'i533'}, 409)
            token = self._tak_map_token() if callable(getattr(self, '_tak_map_token', None)) else ''
            profile = dict(sess.get('profile') or {})
            status = dict(_i529_public_certificate_status(
                _i529_text(sess.get('username')),
                _i529_text(sess.get('tak_uid') or profile.get('tak_uid')),
            ) or {})
            safe = {key: value for key, value in status.items() if key not in ('key_password', 'private_key_path', 'certificate_path', 'ca_chain_path')}
            safe['version'] = 'i533'
            safe['user_presence'] = _i532_presence_public(token)
            return self._send_json(safe, 200 if status.get('ok') else 428)
        return _i533_do_get_before(self)
    Handler.do_GET = _i533_do_get

    _i533_point_xml_before = _i526_point_xml
    def _i526_point_xml(feature, mission_name, creator_uid=''):
        built = _i533_point_xml_before(feature, mission_name, creator_uid)
        if not isinstance(built, dict) or not built.get('ok'):
            return built
        built = dict(built)
        try:
            root = ET.fromstring(_i529_text(built.get('xml')).encode('utf-8'))
            detail = root.find('detail')
            if detail is not None:
                transport = detail.find('takmap')
                if transport is not None:
                    transport.set('version', 'i533')
                    transport.set('publicationFlow', 'ots-confirmed-persistent-user-eud-cot-then-mission-uid-association')
                    transport.set('persistentUserEud', 'true')
                    transport.set('otsEudConfirmed', 'true')
                point_meta = detail.find('takmap_point')
                if point_meta is not None:
                    point_meta.set('version', 'i533')
                    point_meta.set('publicationFlow', 'ots-confirmed-persistent-user-eud-cot-then-mission-uid-association')
                    point_meta.set('eudPresence', 'false')
            built['xml'] = '<?xml version="1.0" encoding="UTF-8"?>\n' + ET.tostring(root, encoding='unicode', short_empty_elements=True)
            built['version'] = 'i533'
            built['publication_flow'] = 'ots-confirmed-persistent-user-eud-cot-then-mission-uid-association'
            built['persistent_user_eud'] = True
            built['ots_eud_confirmation_required'] = True
            built['mission_object_uid_independent'] = True
        except Exception as exc:
            built['i533_publication_xml_warning'] = str(exc)
        return built
    globals()['_i526_point_xml'] = _i526_point_xml

