    def _i533_version_html(html):
        if not isinstance(html, str):
            return html
        html = re.sub(r'1\.3\.0-i\d+', '1.3.0-i533', html)
        html = re.sub(r'TAKDashboard/i\d+', 'TAKDashboard/i533', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i\d+', 'TAK-Map/1.3.0 i533', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i533\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i533\2', html)
        return html

    def _i533_patch_html(html):
        html = _i533_version_html(html)
        if not isinstance(html, str):
            return html
        for script_id in (
            'takMapPerUserDataSyncIdentityI529', 'takMapPerUserDataSyncIdentityI531',
            'takMapPerUserDataSyncIdentityI532', 'takMapPerUserDataSyncIdentityI533',
        ):
            html = re.sub(r'<script[^>]*id=["\']' + re.escape(script_id) + r'["\'][^>]*>[\s\S]*?</script>\s*', '', html, flags=re.I)
        return html.replace('</body>', _I533_RUNTIME + '\n</body>', 1) if '</body>' in html else html + _I533_RUNTIME

    TAK_MAP_HTML = _i533_patch_html(TAK_MAP_HTML)
    INDEX_HTML = TAK_MAP_HTML
    TAK_MAP_LOGIN_HTML = _i533_version_html(TAK_MAP_LOGIN_HTML)
    LOGIN_HTML = TAK_MAP_LOGIN_HTML
    TAK_MAP_ITERATION = 'i533'

