    def _i535_user_ref(sess):
        sess = sess if isinstance(sess, dict) else {}
        profile = dict(sess.get('profile') or {})
        key = _i529_text(profile.get('identity_key'))
        if key:
            return 'identity:' + key
        return '%s:%s' % (_i529_text(sess.get('auth_mode') or 'user'), _i529_text(sess.get('username')).casefold())

    def _i535_user_hash(sess_or_ref):
        ref = sess_or_ref if isinstance(sess_or_ref, str) else _i535_user_ref(sess_or_ref)
        return hashlib.sha256(_i529_text(ref).encode('utf-8')).hexdigest()[:48]

    def _i535_user_paths(sess):
        root = _I535_SENTINEL_ROOT / _i535_user_hash(sess)
        return {'root': root, 'credential': root / 'credentials.json', 'cache': _I535_SENTINEL_CACHE_ROOT / _i535_user_hash(sess)}

    def _i535_secret_keys(user_ref):
        seed = hmac.new(_i529_master_secret(), ('tak-map-i535-sentinel:' + _i529_text(user_ref)).encode('utf-8'), hashlib.sha256).digest()
        return (
            hmac.new(seed, b'encryption', hashlib.sha256).digest(),
            hmac.new(seed, b'authentication', hashlib.sha256).digest(),
        )

    def _i535_stream(key, nonce, length):
        out = bytearray()
        counter = 0
        while len(out) < length:
            out.extend(hmac.new(key, nonce + counter.to_bytes(8, 'big'), hashlib.sha256).digest())
            counter += 1
        return bytes(out[:length])

    def _i535_encrypt(user_ref, value):
        plain = _i529_text(value).encode('utf-8')
        enc_key, mac_key = _i535_secret_keys(user_ref)
        nonce = secrets.token_bytes(16)
        stream = _i535_stream(enc_key, nonce, len(plain))
        ciphertext = bytes(a ^ b for a, b in zip(plain, stream))
        body = b'TSH1' + nonce + ciphertext
        tag = hmac.new(mac_key, body, hashlib.sha256).digest()
        return base64.urlsafe_b64encode(body + tag).decode('ascii')

    def _i535_decrypt(user_ref, value):
        try:
            raw = base64.urlsafe_b64decode(_i529_text(value).encode('ascii'))
        except Exception as exc:
            raise ValueError('Stored Sentinel Hub credential is not valid base64.') from exc
        if len(raw) < 4 + 16 + 32 or raw[:4] != b'TSH1':
            raise ValueError('Stored Sentinel Hub credential format is invalid.')
        body, tag = raw[:-32], raw[-32:]
        enc_key, mac_key = _i535_secret_keys(user_ref)
        expected = hmac.new(mac_key, body, hashlib.sha256).digest()
        if not hmac.compare_digest(tag, expected):
            raise ValueError('Stored Sentinel Hub credential authentication failed.')
        nonce, ciphertext = body[4:20], body[20:]
        stream = _i535_stream(enc_key, nonce, len(ciphertext))
        return bytes(a ^ b for a, b in zip(ciphertext, stream)).decode('utf-8')

    def _i535_load_record(sess):
        path = _i535_user_paths(sess)['credential']
        try:
            value = json.loads(path.read_text(encoding='utf-8'))
            return value if isinstance(value, dict) else {}
        except Exception:
            return {}

    def _i535_load_credentials(sess):
        record = _i535_load_record(sess)
        if not record:
            return {'ok': False, 'configured': False, 'error': 'Sentinel Hub is not configured for this user.'}
        user_ref = _i535_user_ref(sess)
        try:
            client_id = _i535_decrypt(user_ref, record.get('client_id_encrypted'))
            client_secret = _i535_decrypt(user_ref, record.get('client_secret_encrypted'))
        except Exception as exc:
            return {'ok': False, 'configured': True, 'error': 'Could not decrypt this user’s Sentinel Hub credentials: ' + str(exc)}
        if not client_id or not client_secret:
            return {'ok': False, 'configured': True, 'error': 'Stored Sentinel Hub credentials are incomplete.'}
        return {
            'ok': True, 'configured': True, 'client_id': client_id, 'client_secret': client_secret,
            'configured_at': _i529_text(record.get('configured_at')),
            'verified_at': _i529_text(record.get('verified_at')),
            'last_tested_at': _i529_text(record.get('last_tested_at')),
        }

    def _i535_mask(value):
        value = _i529_text(value)
        if len(value) <= 8:
            return ('•' * max(0, len(value) - 2)) + value[-2:]
        return value[:4] + '…' + value[-4:]

    def _i535_public_status(sess):
        loaded = _i535_load_credentials(sess)
        return {
            'ok': True,
            'credential_valid': bool(loaded.get('ok')),
            'version': 'i535',
            'configured': bool(loaded.get('configured')),
            'verified': bool(loaded.get('ok') and loaded.get('verified_at')),
            'client_id_hint': _i535_mask(loaded.get('client_id')) if loaded.get('ok') else '',
            'configured_at': _i529_text(loaded.get('configured_at')),
            'verified_at': _i529_text(loaded.get('verified_at')),
            'last_tested_at': _i529_text(loaded.get('last_tested_at')),
            'error': '' if loaded.get('ok') else _i529_text(loaded.get('error')),
            'credential_scope': 'current-authenticated-user-only',
            'credential_storage': 'authenticated-encryption-server-side',
            'shared_credential_fallback': False,
            'secret_returned_to_browser': False,
        }

    def _i535_http_error(exc, label):
        status = getattr(exc, 'code', 0) or 0
        body = ''
        try:
            body = exc.read(4000).decode('utf-8', errors='replace')
        except Exception:
            body = str(exc)
        try:
            parsed = json.loads(body)
            detail = parsed.get('error_description') or parsed.get('message') or parsed.get('error') or body
        except Exception:
            detail = re.sub(r'<[^>]+>', ' ', body)
            detail = re.sub(r'\s+', ' ', detail).strip()
        return RuntimeError('%s failed%s: %s' % (label, (' with HTTP ' + str(status)) if status else '', detail[:900] or str(exc)))

    def _i535_request_token(client_id, client_secret, cache_key='', force=False):
        client_id = _i529_text(client_id)
        client_secret = _i529_text(client_secret)
        if not client_id or not client_secret:
            raise ValueError('Client ID and Client Secret are required.')
        fingerprint = hashlib.sha256((client_id + '\0' + client_secret).encode('utf-8')).hexdigest()
        if cache_key and not force:
            with _I535_TOKEN_LOCK:
                cached = dict(_I535_TOKEN_CACHE.get(cache_key) or {})
            if cached.get('fingerprint') == fingerprint and float(cached.get('expires_at') or 0) > time.time() + 60:
                return cached['access_token']
        body = urlencode({'grant_type': 'client_credentials', 'client_id': client_id, 'client_secret': client_secret}).encode('utf-8')
        request = Request(_I535_TOKEN_ENDPOINT, data=body, method='POST', headers={
            'Content-Type': 'application/x-www-form-urlencoded',
            'Accept': 'application/json',
            'User-Agent': 'TAK-Map/1.3.0-i535 Sentinel-Hub',
        })
        try:
            with urlopen(request, timeout=25, context=ssl.create_default_context()) as response:
                payload = json.loads(response.read().decode('utf-8'))
        except HTTPError as exc:
            raise _i535_http_error(exc, 'Sentinel Hub OAuth token request')
        except Exception as exc:
            raise RuntimeError('Sentinel Hub OAuth token request failed: ' + str(exc))
        token = _i529_text(payload.get('access_token'))
        if not token:
            raise RuntimeError('Sentinel Hub did not return an access token.')
        expires_in = max(120, int(payload.get('expires_in') or 600))
        if cache_key:
            with _I535_TOKEN_LOCK:
                _I535_TOKEN_CACHE[cache_key] = {
                    'access_token': token, 'expires_at': time.time() + expires_in,
                    'fingerprint': fingerprint,
                }
        return token

    def _i535_api_request(url, token, method='GET', payload=None, accept='application/json'):
        data = None
        headers = {
            'Authorization': 'Bearer ' + _i529_text(token),
            'Accept': accept,
            'User-Agent': 'TAK-Map/1.3.0-i535 Sentinel-Hub',
        }
        if payload is not None:
            data = json.dumps(payload, separators=(',', ':')).encode('utf-8')
            headers['Content-Type'] = 'application/json'
        request = Request(url, data=data, method=method, headers=headers)
        try:
            with urlopen(request, timeout=35, context=ssl.create_default_context()) as response:
                return response.status, response.headers, response.read()
        except HTTPError:
            raise

    def _i535_test_credentials(client_id, client_secret, cache_key=''):
        token = _i535_request_token(client_id, client_secret, cache_key=cache_key, force=True)
        try:
            status, headers, body = _i535_api_request(_I535_CATALOG_BASE + '/collections/sentinel-2-l2a', token)
        except HTTPError as exc:
            raise _i535_http_error(exc, 'Sentinel Hub Sentinel-2 L2A catalogue test')
        if status < 200 or status >= 300:
            raise RuntimeError('Sentinel Hub catalogue test returned HTTP ' + str(status) + '.')
        try:
            payload = json.loads(body.decode('utf-8'))
        except Exception as exc:
            raise RuntimeError('Sentinel Hub catalogue test returned invalid JSON: ' + str(exc))
        collection_id = _i529_text(payload.get('id'))
        if collection_id and collection_id != 'sentinel-2-l2a':
            raise RuntimeError('Sentinel Hub returned an unexpected collection: ' + collection_id)
        return {'ok': True, 'collection': collection_id or 'sentinel-2-l2a', 'title': _i529_text(payload.get('title'))}

    def _i535_save_credentials(sess, client_id, client_secret):
        client_id = _i529_text(client_id)
        client_secret = _i529_text(client_secret)
        if len(client_id) < 8 or len(client_id) > 300:
            raise ValueError('Enter a valid Sentinel Hub Client ID.')
        if len(client_secret) < 12 or len(client_secret) > 1000:
            raise ValueError('Enter a valid Sentinel Hub Client Secret.')
        key = _i535_user_hash(sess)
        tested = _i535_test_credentials(client_id, client_secret, cache_key=key)
        now = datetime.now(timezone.utc).isoformat()
        record = {
            'version': 'i535',
            'client_id_encrypted': _i535_encrypt(_i535_user_ref(sess), client_id),
            'client_secret_encrypted': _i535_encrypt(_i535_user_ref(sess), client_secret),
            'configured_at': now,
            'verified_at': now,
            'last_tested_at': now,
            'identity_hash': key,
        }
        paths = _i535_user_paths(sess)
        with _I535_SENTINEL_LOCK:
            _i529_atomic_write(paths['credential'], json.dumps(record, indent=2, sort_keys=True) + '\n', 0o600, False)
        _i512_audit('sentinel-hub-user-config', _i529_text(sess.get('username')), True, 'configured and verified per-user OAuth client')
        status = _i535_public_status(sess)
        status.update({'ok': True, 'message': 'Sentinel Hub credentials saved and verified.', 'test': tested})
        return status

    def _i535_remove_credentials(sess):
        paths = _i535_user_paths(sess)
        with _I535_SENTINEL_LOCK:
            try:
                paths['credential'].unlink()
            except FileNotFoundError:
                pass
            try:
                if paths['root'].is_dir() and not any(paths['root'].iterdir()):
                    paths['root'].rmdir()
            except Exception:
                pass
        key = _i535_user_hash(sess)
        with _I535_TOKEN_LOCK:
            _I535_TOKEN_CACHE.pop(key, None)
        try:
            shutil.rmtree(paths['cache'])
        except FileNotFoundError:
            pass
        except Exception:
            pass
        _i512_audit('sentinel-hub-user-config', _i529_text(sess.get('username')), True, 'removed per-user OAuth client')
        return {'ok': True, 'version': 'i535', 'configured': False, 'verified': False, 'message': 'Sentinel Hub credentials removed.', 'shared_credential_fallback': False}

    def _i535_credentials_for_request(sess):
        loaded = _i535_load_credentials(sess)
        if not loaded.get('ok'):
            raise RuntimeError(_i529_text(loaded.get('error') or 'Sentinel Hub is not configured for this user.'))
        return loaded

    def _i535_user_token(sess, force=False):
        credentials = _i535_credentials_for_request(sess)
        return _i535_request_token(credentials['client_id'], credentials['client_secret'], cache_key=_i535_user_hash(sess), force=force)

    def _i535_json_with_refresh(sess, url, method='GET', payload=None):
        token = _i535_user_token(sess, False)
        try:
            status, headers, body = _i535_api_request(url, token, method, payload)
        except HTTPError as exc:
            if exc.code != 401:
                raise _i535_http_error(exc, 'Sentinel Hub API request')
            token = _i535_user_token(sess, True)
            try:
                status, headers, body = _i535_api_request(url, token, method, payload)
            except HTTPError as retry_exc:
                raise _i535_http_error(retry_exc, 'Sentinel Hub API request')
        try:
            value = json.loads(body.decode('utf-8'))
        except Exception as exc:
            raise RuntimeError('Sentinel Hub API returned invalid JSON: ' + str(exc))
        return value

    def _i535_search_bbox(value):
        if not isinstance(value, (list, tuple)) or len(value) != 4:
            raise ValueError('A four-value map bounding box is required.')
        west, south, east, north = [float(x) for x in value]
        if not all(math.isfinite(x) for x in (west, south, east, north)):
            raise ValueError('Map bounding box must contain finite coordinates.')
        south = max(-85.0, min(85.0, south))
        north = max(-85.0, min(85.0, north))
        west = max(-180.0, min(180.0, west))
        east = max(-180.0, min(180.0, east))
        if south >= north:
            raise ValueError('Map bounding box latitude range is invalid.')
        if west == east:
            raise ValueError('Map bounding box longitude range is empty.')
        if west < east:
            return [[west, south, east, north]]
        return [[west, south, 180.0, north], [-180.0, south, east, north]]

    def _i535_catalog_features(sess, bbox, start_iso, end_iso, max_cloud):
        base = {
            'bbox': bbox,
            'datetime': start_iso + '/' + end_iso,
            'collections': ['sentinel-2-l2a'],
            'limit': 100,
            'filter': 'eo:cloud_cover <= ' + str(int(max_cloud)),
        }
        features = []
        next_token = None
        for _ in range(4):
            request = dict(base)
            if next_token not in (None, ''):
                request['next'] = next_token
            payload = _i535_json_with_refresh(sess, _I535_CATALOG_BASE + '/search', 'POST', request)
            features.extend(list(payload.get('features') or []))
            context = payload.get('context') if isinstance(payload.get('context'), dict) else {}
            next_token = context.get('next')
            if next_token in (None, ''):
                break
        return features

    def _i535_search_scenes(sess, payload):
        payload = payload if isinstance(payload, dict) else {}
        bboxes = _i535_search_bbox(payload.get('bbox'))
        days = max(1, min(1825, int(payload.get('days') or 180)))
        max_cloud = max(0, min(100, int(payload.get('max_cloud') if payload.get('max_cloud') is not None else 35)))
        now = datetime.now(timezone.utc)
        start = now - timedelta(days=days)
        start_iso = start.strftime('%Y-%m-%dT00:00:00Z')
        end_iso = now.strftime('%Y-%m-%dT23:59:59Z')
        cache_key = hashlib.sha256(json.dumps({'u': _i535_user_hash(sess), 'b': bboxes, 'd': days, 'c': max_cloud}, sort_keys=True).encode('utf-8')).hexdigest()
        with _I535_SEARCH_LOCK:
            cached = dict(_I535_SEARCH_CACHE.get(cache_key) or {})
        if cached and float(cached.get('expires_at') or 0) > time.time():
            result = dict(cached.get('result') or {})
            result['cached'] = True
            return result
        grouped = {}
        seen_ids = set()
        for bbox in bboxes:
            for feature in _i535_catalog_features(sess, bbox, start_iso, end_iso, max_cloud):
                feature = feature if isinstance(feature, dict) else {}
                fid = _i529_text(feature.get('id'))
                if fid and fid in seen_ids:
                    continue
                if fid:
                    seen_ids.add(fid)
                props = feature.get('properties') if isinstance(feature.get('properties'), dict) else {}
                dt_text = _i529_text(props.get('datetime') or props.get('start_datetime'))
                try:
                    dt = datetime.fromisoformat(dt_text.replace('Z', '+00:00'))
                except Exception:
                    continue
                date_key = dt.astimezone(timezone.utc).strftime('%Y-%m-%d')
                cloud = props.get('eo:cloud_cover')
                try:
                    cloud = float(cloud)
                except Exception:
                    cloud = None
                row = grouped.setdefault(date_key, {
                    'date': date_key, 'latest_acquisition': dt.astimezone(timezone.utc).isoformat(),
                    'cloud_values': [], 'scene_ids': set(), 'platforms': set(),
                })
                try:
                    current_latest = datetime.fromisoformat(_i529_text(row.get('latest_acquisition')).replace('Z', '+00:00'))
                except Exception:
                    current_latest = datetime.min.replace(tzinfo=timezone.utc)
                if dt.astimezone(timezone.utc) > current_latest.astimezone(timezone.utc):
                    row['latest_acquisition'] = dt.astimezone(timezone.utc).isoformat()
                if cloud is not None and math.isfinite(cloud):
                    row['cloud_values'].append(cloud)
                if fid:
                    row['scene_ids'].add(fid)
                platform = _i529_text(props.get('platform') or props.get('constellation'))
                if platform:
                    row['platforms'].add(platform)
        scenes = []
        for date_key, row in grouped.items():
            clouds = row['cloud_values']
            scenes.append({
                'date': date_key,
                'latest_acquisition': row['latest_acquisition'],
                'cloud_cover': min(clouds) if clouds else None,
                'scene_count': max(1, len(row['scene_ids'])),
                'platforms': sorted(row['platforms']),
            })
        scenes.sort(key=lambda row: row['date'], reverse=True)
        scenes = scenes[:80]
        result = {
            'ok': True, 'version': 'i535', 'source': 'Copernicus Sentinel Hub Catalog API',
            'collection': 'sentinel-2-l2a', 'scenes': scenes,
            'lookback_days': days, 'max_cloud': max_cloud, 'bbox_parts': len(bboxes),
            'credential_scope': 'current-authenticated-user-only', 'shared_credential_fallback': False,
            'cached': False,
        }
        with _I535_SEARCH_LOCK:
            _I535_SEARCH_CACHE[cache_key] = {'expires_at': time.time() + _I535_SEARCH_CACHE_SECONDS, 'result': dict(result)}
        return result

    def _i535_tile_bbox(z, x, y):
        n = 1 << z
        if x < 0 or y < 0 or x >= n or y >= n:
            raise ValueError('Tile coordinates are outside the requested zoom level.')
        origin = 20037508.342789244
        span = (origin * 2.0) / n
        minx = -origin + x * span
        maxx = minx + span
        maxy = origin - y * span
        miny = maxy - span
        return [minx, miny, maxx, maxy]

    def _i535_tile_lock(key):
        with _I535_TILE_LOCK_GUARD:
            lock = _I535_TILE_LOCKS.get(key)
            if lock is None:
                lock = threading.Lock()
                _I535_TILE_LOCKS[key] = lock
            return lock

    def _i535_user_semaphore(sess):
        key = _i535_user_hash(sess)
        with _I535_TILE_LOCK_GUARD:
            sem = _I535_USER_SEMAPHORES.get(key)
            if sem is None:
                sem = threading.BoundedSemaphore(4)
                _I535_USER_SEMAPHORES[key] = sem
            return sem

    def _i535_process_tile(sess, z, x, y, date_text, product, max_cloud):
        if product not in _I535_SENTINEL_PRODUCTS or product not in _I535_EVALSCRIPTS:
            raise ValueError('Unsupported Sentinel-2 product.')
        if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_text or ''):
            raise ValueError('Sentinel-2 tile date must use YYYY-MM-DD.')
        try:
            selected = datetime.strptime(date_text, '%Y-%m-%d').replace(tzinfo=timezone.utc)
        except Exception:
            raise ValueError('Sentinel-2 tile date is invalid.')
        if selected < datetime(2015, 6, 1, tzinfo=timezone.utc) or selected > datetime.now(timezone.utc) + timedelta(days=2):
            raise ValueError('Sentinel-2 tile date is outside the supported acquisition range.')
        z, x, y = int(z), int(x), int(y)
        if z < 0 or z > 16:
            raise ValueError('Sentinel-2 native tile zoom must be between 0 and 16.')
        max_cloud = max(0, min(100, int(max_cloud)))
        paths = _i535_user_paths(sess)
        cache_path = paths['cache'] / date_text / product / ('cc-' + str(max_cloud)) / str(z) / str(x) / (str(y) + '.png')
        try:
            if cache_path.is_file() and time.time() - cache_path.stat().st_mtime <= _I535_TILE_CACHE_SECONDS:
                body = cache_path.read_bytes()
                if body.startswith(b'\x89PNG\r\n\x1a\n'):
                    return body, True
        except Exception:
            pass
        lock_key = str(cache_path)
        with _i535_tile_lock(lock_key):
            try:
                if cache_path.is_file() and time.time() - cache_path.stat().st_mtime <= _I535_TILE_CACHE_SECONDS:
                    body = cache_path.read_bytes()
                    if body.startswith(b'\x89PNG\r\n\x1a\n'):
                        return body, True
            except Exception:
                pass
            bbox = _i535_tile_bbox(z, x, y)
            request_payload = {
                'input': {
                    'bounds': {'bbox': bbox, 'properties': {'crs': 'http://www.opengis.net/def/crs/EPSG/0/3857'}},
                    'data': [{
                        'type': 'sentinel-2-l2a',
                        'dataFilter': {
                            'timeRange': {'from': date_text + 'T00:00:00Z', 'to': date_text + 'T23:59:59Z'},
                            'maxCloudCoverage': max_cloud,
                            'mosaickingOrder': 'leastCC',
                        },
                        'processing': {'upsampling': 'BILINEAR', 'downsampling': 'BILINEAR'},
                    }],
                },
                'output': {
                    'width': 256, 'height': 256,
                    'responses': [{'identifier': 'default', 'format': {'type': 'image/png'}}],
                },
                'evalscript': _I535_EVALSCRIPTS[product],
            }
            sem = _i535_user_semaphore(sess)
            acquired = sem.acquire(timeout=30)
            if not acquired:
                raise RuntimeError('Sentinel Hub tile queue is busy. Try again shortly.')
            try:
                token = _i535_user_token(sess, False)
                try:
                    status, headers, body = _i535_api_request(_I535_PROCESS_ENDPOINT, token, 'POST', request_payload, 'image/png')
                except HTTPError as exc:
                    if exc.code != 401:
                        raise _i535_http_error(exc, 'Sentinel Hub Process API tile request')
                    token = _i535_user_token(sess, True)
                    try:
                        status, headers, body = _i535_api_request(_I535_PROCESS_ENDPOINT, token, 'POST', request_payload, 'image/png')
                    except HTTPError as retry_exc:
                        raise _i535_http_error(retry_exc, 'Sentinel Hub Process API tile request')
            finally:
                sem.release()
            if status < 200 or status >= 300:
                raise RuntimeError('Sentinel Hub Process API returned HTTP ' + str(status) + '.')
            if not body.startswith(b'\x89PNG\r\n\x1a\n'):
                preview = body[:500].decode('utf-8', errors='replace')
                raise RuntimeError('Sentinel Hub Process API did not return a PNG tile: ' + preview)
            _i529_atomic_write(cache_path, body, 0o600, True)
            return body, False

    _i535_get_before = Handler.do_GET
    def _i535_do_get(self):
        parsed = urlparse(self.path)
        if parsed.path == _I535_SENTINEL_ASSET_PATH:
            fp = Path(__file__).resolve().parent / 'assets' / _I535_SENTINEL_ASSET_NAME
            if not fp.is_file():
                self.send_response(404); self.send_header('Cache-Control', 'no-store'); self.end_headers(); return
            body = fp.read_bytes()
            self.send_response(200)
            self.send_header('Content-Type', 'application/javascript; charset=utf-8')
            self.send_header('Cache-Control', 'no-store, max-age=0')
            self.send_header('X-TAK-Map-Module', 'i535-sentinel-hub')
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            if getattr(self, 'command', 'GET') != 'HEAD': self.wfile.write(body)
            return
        if parsed.path == '/api/tak-map/account/sentinel-hub':
            if not self._tak_map_auth_ok(): return self._require_tak_map_login()
            sess = self._tak_map_session()
            if _i512_forced_change(sess): return self._send_json({'ok': False, 'password_change_required': True, 'error': 'Change the default local administrator password first.'}, 428)
            status = _i535_public_status(sess)
            return self._send_json(status, 200)
        tile_match = re.fullmatch(r'/api/tak-map/sentinel-hub/tile/(\d+)/(\d+)/(\d+)\.png', parsed.path)
        if tile_match:
            if not self._tak_map_auth_ok(): return self._require_tak_map_login()
            sess = self._tak_map_session()
            query = parse_qs(parsed.query)
            try:
                body, cached = _i535_process_tile(
                    sess, int(tile_match.group(1)), int(tile_match.group(2)), int(tile_match.group(3)),
                    _i529_text((query.get('date') or [''])[0]),
                    _i529_text((query.get('product') or ['true_color'])[0]),
                    int((query.get('maxcc') or ['35'])[0]),
                )
                self.send_response(200)
                self.send_header('Content-Type', 'image/png')
                self.send_header('Cache-Control', 'private, max-age=3600')
                self.send_header('X-TAK-Map-Sentinel-Cache', 'HIT' if cached else 'MISS')
                self.send_header('X-Content-Type-Options', 'nosniff')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                if getattr(self, 'command', 'GET') != 'HEAD': self.wfile.write(body)
                return
            except Exception as exc:
                message = str(exc)
                body = message.encode('utf-8', errors='replace')[:3000]
                self.send_response(428 if 'not configured' in message.lower() else 502)
                self.send_header('Content-Type', 'text/plain; charset=utf-8')
                self.send_header('Cache-Control', 'no-store')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                if getattr(self, 'command', 'GET') != 'HEAD': self.wfile.write(body)
                return
        return _i535_get_before(self)
    Handler.do_GET = _i535_do_get

    _i535_post_before = Handler.do_POST
    def _i535_do_post(self):
        parsed = urlparse(self.path)
        if parsed.path == '/api/tak-map/account/sentinel-hub':
            if not self._tak_map_auth_ok(): return self._require_tak_map_login()
            sess = self._tak_map_session()
            if _i512_forced_change(sess): return self._send_json({'ok': False, 'password_change_required': True, 'error': 'Change the default local administrator password first.'}, 428)
            payload = _read_json_body(self)
            action = _i529_text(payload.get('action') or 'test').lower()
            try:
                if action in ('save', 'replace'):
                    return self._send_json(_i535_save_credentials(sess, payload.get('client_id'), payload.get('client_secret')))
                if action == 'remove':
                    return self._send_json(_i535_remove_credentials(sess))
                if action == 'test':
                    client_id = _i529_text(payload.get('client_id'))
                    client_secret = _i529_text(payload.get('client_secret'))
                    if not client_id and not client_secret:
                        loaded = _i535_credentials_for_request(sess)
                        client_id, client_secret = loaded['client_id'], loaded['client_secret']
                    elif not client_id or not client_secret:
                        raise ValueError('Enter both Client ID and Client Secret, or leave both blank to test the saved credentials.')
                    tested = _i535_test_credentials(client_id, client_secret, cache_key=_i535_user_hash(sess))
                    now = datetime.now(timezone.utc).isoformat()
                    # Testing stored credentials refreshes the verification timestamp without returning either secret.
                    stored = _i535_load_credentials(sess)
                    if stored.get('ok') and stored.get('client_id') == client_id and stored.get('client_secret') == client_secret:
                        record = _i535_load_record(sess)
                        record['verified_at'] = now
                        record['last_tested_at'] = now
                        _i529_atomic_write(_i535_user_paths(sess)['credential'], json.dumps(record, indent=2, sort_keys=True) + '\n', 0o600, False)
                    status = _i535_public_status(sess)
                    status.update({'ok': True, 'verified': True, 'verified_at': now, 'last_tested_at': now, 'message': 'Sentinel Hub connection verified.', 'test': tested})
                    return self._send_json(status)
                raise ValueError('Unsupported Sentinel Hub action.')
            except Exception as exc:
                return self._send_json({'ok': False, 'version': 'i535', 'error': str(exc), 'shared_credential_fallback': False}, 400)
        if parsed.path == '/api/tak-map/sentinel-hub/search':
            if not self._tak_map_auth_ok(): return self._require_tak_map_login()
            sess = self._tak_map_session()
            if _i512_forced_change(sess): return self._send_json({'ok': False, 'password_change_required': True, 'error': 'Change the default local administrator password first.'}, 428)
            try:
                return self._send_json(_i535_search_scenes(sess, _read_json_body(self)))
            except Exception as exc:
                status = 428 if 'not configured' in str(exc).lower() else 502
                return self._send_json({'ok': False, 'version': 'i535', 'error': str(exc), 'shared_credential_fallback': False}, status)
        return _i535_post_before(self)
    Handler.do_POST = _i535_do_post

