    def _i535_version_html(html):
        if not isinstance(html, str): return html
        html = re.sub(r'1\.3\.0-i\d+', '1.3.0-i535', html)
        html = re.sub(r'TAKDashboard/i\d+', 'TAKDashboard/i535', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i\d+', 'TAK-Map/1.3.0 i535', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i535\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i535\2', html)
        return html

    def _i535_patch_html(html):
        html = _i535_version_html(html)
        if not isinstance(html, str): return html
        html = re.sub(r'<script[^>]*id=["\']takMapNrtSatelliteLoaderI525["\'][^>]*></script>\s*', '', html, flags=re.I)
        html = re.sub(r'<script[^>]*id=["\']takMapNrtSatelliteLoaderI535["\'][^>]*></script>\s*', '', html, flags=re.I)
        html = re.sub(r'<script[^>]*id=["\']takMapSentinelHubI535["\'][^>]*>[\s\S]*?</script>\s*', '', html, flags=re.I)
        payload = _I535_SENTINEL_LOADER + '\n' + _I535_RUNTIME
        return html.replace('</body>', payload + '\n</body>', 1) if '</body>' in html else html + payload

    TAK_MAP_HTML = _i535_patch_html(TAK_MAP_HTML)
