        key = _i537_identity_key()
        if not key:
            return False
        uid = _i537_object_uid(row if isinstance(row, dict) else {'xml': xml})
        if not uid and xml:
            uid = _i537_object_uid({'xml': xml})
        return bool(uid and uid in _i537_cached_mission_uids(key))

