    def _i537_send_static(handler, path, content_type, cache_control):
        try:
            body = path.read_bytes()
        except FileNotFoundError:
            return False
        handler.send_response(200)
        handler.send_header('Content-Type', content_type)
        handler.send_header('Cache-Control', cache_control)
        handler.send_header('X-Content-Type-Options', 'nosniff')
        handler.send_header('X-TAK-Map-Module', 'i537-milstd2525c')
        handler.send_header('Content-Length', str(len(body)))
        handler.end_headers()
        if getattr(handler, 'command', 'GET') != 'HEAD':
            try:
                handler.wfile.write(body)
            except (BrokenPipeError, ConnectionResetError):
                pass
        return True

    _i537_get_before = Handler.do_GET
    def _i537_do_get(self):
        parsed = urlparse(self.path)
        path = parsed.path or ''
        if path == '/assets/runtime/tak-map-milstd2525c-i537.js':
            if _i537_send_static(self, _I537_RUNTIME_ASSET, 'application/javascript; charset=utf-8', 'no-store, max-age=0'):
                return
        if path in ('/mil2525/icons.json', '/assets/mil2525/icons.json'):
            if _i537_send_static(self, _i537_mil_root() / 'icons.json', 'application/json; charset=utf-8', 'public, max-age=3600'):
                return
        if path.startswith('/mil2525/svg/') or path.startswith('/assets/mil2525/svg/'):
            try:
                name = unquote(path.split('/svg/', 1)[1])
            except Exception:
                name = ''
            if name and '/' not in name and '\\' not in name and '..' not in name and name.lower().endswith('.svg'):
                if _i537_send_static(self, _i537_mil_root() / 'svg' / name, 'image/svg+xml; charset=utf-8', 'public, max-age=604800, immutable'):
                    return
        if path in ('/api/tak-map/cot', '/api/tak-map/euds'):
            if not self._tak_map_auth_ok():
                return self._require_tak_map_login()
            sess = self._tak_map_session() or {}
            _I537_REQUEST_CONTEXT.identity_key = _i537_text(sess.get('username') or (sess.get('profile') or {}).get('username'))
            try:
                if path == '/api/tak-map/cot':
                    return self._send_json(tak_map_cot_markers())
                query = parse_qs(parsed.query or '')
                online_only = _i537_text((query.get('online') or query.get('send') or query.get('fresh') or ['0'])[0]).lower() in ('1', 'true', 'yes', 'on')
                data = tak_map_euds()
                if online_only:
                    data['euds'] = [e for e in (data.get('euds') or []) if _is_online_send_eud(e)]
                    data['online_only'] = True
                return self._send_json(data)
            finally:
                _I537_REQUEST_CONTEXT.identity_key = ''
        return _i537_get_before(self)
