    def _i543_event_epoch(row):
        if not isinstance(row, dict):
            return None
        values = []
        for key in ('updated','timestamp','time','start','event_time','eventTime','stale','submission_time','created_at'):
            value = row.get(key)
            if value not in (None, ''):
                values.append(value)
        props = row.get('properties')
        if isinstance(props, dict):
            for key in ('updated','timestamp','time','start','event_time','eventTime','stale'):
                value = props.get(key)
                if value not in (None, ''):
                    values.append(value)
        try:
            parsed = _parse_cot_text_fields(row)
        except Exception:
            parsed = {}
        if isinstance(parsed, dict):
            for key in ('updated','timestamp','time','start','event_time','eventTime','stale'):
                value = parsed.get(key)
                if value not in (None, ''):
                    values.append(value)
        for value in values:
            try:
                if isinstance(value, (int, float)) and math.isfinite(float(value)):
                    number = float(value)
                    return number / 1000.0 if number > 100000000000.0 else number
            except Exception:
                pass
            try:
                parsed_epoch = _parse_ts_epoch(value)
                if parsed_epoch is not None:
                    return float(parsed_epoch)
            except Exception:
                pass
        return None

    def _i543_orphan_rows(payload, allowed_missions=None):
        if not isinstance(payload, dict):
            return []
        candidate = dict(payload)
        if allowed_missions is not None:
            candidate = _i539_scope_raw_rows(candidate, allowed_missions)
        candidate = _tak_enrich_data_sync_result(candidate)
        uid_missions, _, _ = _tak_data_sync_ownership(candidate)
        normalized = {
            _i539_text(uid).casefold(): {_i539_text(name).casefold() for name in names if _i539_text(name)}
            for uid, names in uid_missions.items()
        }
        rows = []
        for row in list(candidate.get('objects') or []):
            if not isinstance(row, dict):
                continue
            uid = _i537_object_uid(row) if '_i537_object_uid' in globals() else _i539_text(row.get('uid')).casefold()
            if not uid:
                continue
            source = _i539_text(row.get('source') or row.get('source_table')).casefold()
            point_like = _i537_point_like(row) if '_i537_point_like' in globals() else bool(row.get('lat') is not None and row.get('lon') is not None)
            explicit = _i539_text(row.get('mission_name') or row.get('mission')).casefold()
            if point_like and ('mission_uids' in source or 'mission uid' in source or _i539_text(row.get('source_table')).casefold() == 'mission_uids') and not normalized.get(uid) and not explicit:
                rows.append(row)
        return rows

    def _i543_active_point_uids(payload):
        result = set()
        if not isinstance(payload, dict):
            return result
        for row in list(payload.get('objects') or []):
            if not isinstance(row, dict):
                continue
            if '_i537_point_like' in globals() and not _i537_point_like(row):
                continue
            uid = _i537_object_uid(row) if '_i537_object_uid' in globals() else _i539_text(row.get('uid')).casefold()
            if uid:
                result.add(uid)
        return result

    def _i543_update_tombstones(source_payload, filtered_payload, allowed_missions=None):
        key = _i543_identity_key()
        if not key or not isinstance(filtered_payload, dict):
            return []
        now = time.time()
        orphan_rows = _i543_orphan_rows(source_payload, allowed_missions)
        active = _i543_active_point_uids(filtered_payload)
        with _I543_TOMBSTONE_LOCK:
            bucket = dict(_I543_TOMBSTONES.get(key) or {})
            for uid in active:
                bucket.pop(uid, None)
            for row in orphan_rows:
                uid = _i537_object_uid(row) if '_i537_object_uid' in globals() else _i539_text(row.get('uid')).casefold()
                if not uid or uid in active:
                    continue
                event_epoch = _i543_event_epoch(row)
                old = dict(bucket.get(uid) or {})
                observed = float(old.get('observed_at_epoch') or now)
                cutoff = float(event_epoch if event_epoch is not None else old.get('cutoff_epoch') or observed)
                bucket[uid] = {
                    'uid': uid,
                    'name': _i539_text(row.get('callsign') or row.get('name') or row.get('title')),
                    'observed_at_epoch': observed,
                    'cutoff_epoch': cutoff,
                    'source_event_epoch': float(event_epoch) if event_epoch is not None else None,
                    'reason': 'Mission association removed; suppress retained Live TAK/EUD copies until a newer CoT event is observed.',
                }
            if len(bucket) > _I543_TOMBSTONE_LIMIT:
                ordered = sorted(bucket.items(), key=lambda item: float((item[1] or {}).get('observed_at_epoch') or 0), reverse=True)
                bucket = dict(ordered[:_I543_TOMBSTONE_LIMIT])
            _I543_TOMBSTONES[key] = bucket
            return [dict(row) for row in bucket.values()]

    def _i543_tombstones(identity_key=''):
        key = _i537_text(identity_key or _i543_identity_key()).casefold()
        if not key:
            return []
        with _I543_TOMBSTONE_LOCK:
            return [dict(row) for row in (_I543_TOMBSTONES.get(key) or {}).values()]

