            if not uid or not point_like:
                out.append(row); continue
            if uid not in by_uid:
                by_uid[uid] = len(out); out.append(row); continue
            index = by_uid[uid]; current = out[index]
            current_epoch = _i545_row_epoch(current); row_epoch = _i545_row_epoch(row)
            current_rank = (float(current_epoch) if current_epoch is not None else float('-inf'), _i546_row_detail_score(current))
            row_rank = (float(row_epoch) if row_epoch is not None else float('-inf'), _i546_row_detail_score(row))
            winner, loser = (row, current) if row_rank > current_rank else (current, row)
            merged = dict(winner)
