    def _i547_result_status(result):
        if not isinstance(result, dict):
            return 0
        try:
            direct = int(result.get('status') or 0)
            if direct:
                return direct
        except Exception:
            pass
        attempts = list(result.get('attempts') or [])
        for attempt in reversed(attempts):
            try:
                status = int((attempt or {}).get('status') or 0)
                if status:
                    return status
            except Exception:
                continue
        return 0

