    def _i547_do_get(self):
        parsed = urlparse(self.path)
        runtime = _I547_RUNTIME_FILES.get(parsed.path)
        if runtime:
            return _i541_send_file(self, runtime[0], runtime[1], 'i547-live-mission-cot-refresh')
        if parsed.path == '/api/tak-map/data-sync':
            query = parse_qs(parsed.query or '')
            force = _i547_text((query.get('force') or ['0'])[0]).casefold() in ('1', 'true', 'yes', 'on')
            reason = _i547_text((query.get('reason') or [''])[0])
            _I547_REQUEST_CONTEXT.force = force
            _I547_REQUEST_CONTEXT.reason = reason
            try:
                return _i547_get_before(self)
            finally:
                _I547_REQUEST_CONTEXT.force = False
                _I547_REQUEST_CONTEXT.reason = ''
        return _i547_get_before(self)
