    def _i545_fetch_mission_events(mission):
        mission_name = _i547_text(mission)
        mission_q = quote(mission_name, safe='')
        base_path = '/Marti/api/missions/' + mission_q + '/cot'
        attempts = []

        primary = _ots_mission_api_request(base_path, method='GET', timeout=8)
        attempts.append({
            'strategy': 'authenticated-user-scope-no-creatorUid',
            'path': base_path,
            'ok': bool(isinstance(primary, dict) and primary.get('ok')),
            'status': _i547_result_status(primary),
            'error': _i547_text((primary or {}).get('error')) if isinstance(primary, dict) else 'request-failed',
        })
        selected = primary
        selected_path = base_path
        strategy = 'authenticated-user-scope-no-creatorUid'
        fallback_used = False

        if not (isinstance(primary, dict) and primary.get('ok')):
            credential = _i529_current_user_credential() if '_i529_current_user_credential' in globals() else {}
            creator_uid = _i547_text((credential or {}).get('client_uid'))
            if creator_uid:
                fallback_path = base_path + '?creatorUid=' + quote(creator_uid, safe='')
                fallback = _ots_mission_api_request(fallback_path, method='GET', timeout=8)
                attempts.append({
                    'strategy': 'compatibility-creatorUid-fallback',
                    'path': fallback_path,
                    'ok': bool(isinstance(fallback, dict) and fallback.get('ok')),
                    'status': _i547_result_status(fallback),
                    'error': _i547_text((fallback or {}).get('error')) if isinstance(fallback, dict) else 'request-failed',
                })
                if isinstance(fallback, dict) and fallback.get('ok'):
                    selected = fallback
                    selected_path = fallback_path
                    strategy = 'compatibility-creatorUid-fallback'
                    fallback_used = True

        events = _i545_extract_events(
            selected.get('json') if isinstance(selected, dict) else None,
            selected.get('body') if isinstance(selected, dict) else '',
        )
        return {
            'mission': mission_name,
            'path': selected_path,
            'ok': bool(isinstance(selected, dict) and selected.get('ok')),
            'status': _i547_result_status(selected),
            'error': _i547_text((selected or {}).get('error')) if isinstance(selected, dict) else 'request-failed',
            'events': events,
            'event_count': len(events),
            'query_strategy': strategy,
            'creator_uid_filter_primary': False,
            'creator_uid_fallback_used': fallback_used,
            'request_attempts_i547': attempts,
        }
