    def _i547_refresh_enrichment_now(cfg, sess, missions, reason='forced-data-sync-refresh'):
        names = [_i547_text(name) for name in missions if _i547_text(name)][:_I545_MAX_MISSIONS]
        if not names:
            return {'ok': True, 'refreshed': False, 'reason': 'no-missions', 'events': 0, 'missions': []}
        key = _i545_cache_key(cfg or {}, sess or {})
        requested = tuple(sorted({name.casefold() for name in names}))
        rows = []
        combined = {}
        started = time.time()
        with _I547_REFRESH_LOCK:
            for mission in names:
                row = _i545_fetch_mission_events(mission)
                rows.append({k: v for k, v in row.items() if k != 'events'})
                for uid, event in dict(row.get('events') or {}).items():
                    event = dict(event)
                    event['mission_name'] = mission
                    current = combined.get(uid)
                    if current is None or _i547_event_rank(event) > _i547_event_rank(current):
                        combined[uid] = event
            ok = any(row.get('ok') for row in rows)
            record = {
                'ok': ok,
                'time': time.time(),
                'requested': requested,
                'events': combined,
                'missions': rows,
                'event_count': len(combined),
                'error': '' if ok else '; '.join(filter(None, (_i547_text(row.get('error')) for row in rows)))[:1000],
                'refresh_mode_i547': 'synchronous-forced-refresh',
                'refresh_reason_i547': _i547_text(reason),
                'duration_seconds_i547': max(0.0, time.time() - started),
            }
            with _I545_ENRICH_LOCK:
                _I545_ENRICH_CACHE[key] = record
        return {
            'ok': ok,
            'refreshed': True,
            'reason': _i547_text(reason),
            'events': len(combined),
            'missions': rows,
            'duration_seconds': max(0.0, time.time() - started),
            'cache_key': key,
        }

