    def _i553_promote_symbol_fields(row):
        if not isinstance(row, dict):
            return row
        out = dict(row)
        props = dict(out.get('properties') or {}) if isinstance(out.get('properties'), dict) else {}
        pairs = (
            ('data_sync_symbol_decision_i552', 'data_sync_symbol_decision_i553'),
            ('data_sync_icon_authority_i552', 'data_sync_icon_authority_i553'),
            ('symbol_resolution_i552', 'symbol_resolution_i553'),
            ('mission_cot_raw_sidc_i552', 'mission_cot_raw_sidc_i553'),
            ('data_sync_current_sidc_i552', 'data_sync_current_sidc_i553'),
            ('mission_cot_raw_type_i552', 'mission_cot_raw_type_i553'),
            ('data_sync_current_cot_type_i552', 'data_sync_current_cot_type_i553'),
            ('mission_cot_raw_iconset_path_i552', 'mission_cot_raw_iconset_path_i553'),
            ('data_sync_current_iconset_path_i552', 'data_sync_current_iconset_path_i553'),
            ('current_iconset_path_i552', 'current_iconset_path_i553'),
            ('data_sync_symbol_fingerprint_i552', 'data_sync_symbol_fingerprint_i553'),
            ('data_sync_symbol_changed_i552', 'data_sync_symbol_changed_i553'),
            ('data_sync_upgrade_normalized_i552', 'data_sync_upgrade_normalized_i553'),
            ('data_sync_live_event_i552', 'data_sync_live_event_i553'),
        )
        for old, new in pairs:
            value = out.get(old)
            if value is None and old in props:
                value = props.get(old)
            if value is None:
                continue
            if isinstance(value, dict):
                value = dict(value)
                value['version'] = 'i553'
                if isinstance(value.get('source'), str):
                    value['source'] = value['source'].replace('i552', 'i553')
            out[new] = value
            props[new] = dict(value) if isinstance(value, dict) else value
        out['properties'] = props
        return out

