        html = re.sub(r'<script[^>]*id=["\']takMapPopupLocalDataI56[01]["\'][^>]*></script>\s*', '', html, flags=re.I)
        html = re.sub(r'<script[^>]*id=["\']takMapContextSidebarI56[01]["\'][^>]*></script>\s*', '', html, flags=re.I)
