    def _i567_finalize_payload(payload):
        """Apply icon authority once to cloned visible objects only."""
        if not isinstance(payload, dict):
            return payload
        out = dict(payload)
        raw_rows = payload.get('mission_uids')
        raw_by_uid = {}
        if isinstance(raw_rows, list):
            for raw in raw_rows:
                if not isinstance(raw, dict):
                    continue
                custom = _i566_authoritative_custom_path(raw)
                uid = _i566_object_uid(raw)
                if custom and uid:
                    raw_by_uid[uid] = custom
        original_rows = payload.get('objects')
        recovered = 0
        finalized = []
        if isinstance(original_rows, list):
            for original in original_rows:
                if not isinstance(original, dict):
                    finalized.append(_i567_clone_json_value(original))
                    continue
                row = _i567_clone_json_value(original)
                if not isinstance(row, dict):
                    row = dict(original)
                _i567_flatten_properties(row)
                if not _i565_delete_event(row):
                    xml_path, complete_xml = _i566_xml_icon_authority(row)
                    custom = xml_path if complete_xml else _i566_authoritative_custom_path(row)
                    if not custom and not complete_xml:
                        custom = raw_by_uid.get(_i566_object_uid(row), '')
                        recovered += int(bool(custom))
                    if custom:
                        _i567_apply_custom_path(row, custom)
                    else:
                        _i567_apply_sof_alias(row)
                finalized.append(row)
            out['objects'] = finalized
        out['custom_icon_resolution_i567'] = {
            'version':'i567','single_final_response_pass':True,
            'pre_augmentation_mutation':False,'raw_mission_uids_read_only':True,
            'visible_rows_cloned':True,'object_count_preserved':len(finalized) == len(original_rows or []),
            'raw_mission_uid_join':True,'objects_recovered_from_raw_uid':recovered,
            'generic_mil_fallback_suppressed':True,
        }
        return out

    def _i512_augment_data_sync(base, cfg, sess):
        # Legacy normalization mutates dictionaries in place. Isolate it from the
        # acquisition/cache payload and restore pristine raw MissionUID rows before
        # the single final response pass.
        working = _i567_clone_json_value(base) if isinstance(base, dict) else base
        pristine_raw = _i567_clone_json_value(base.get('mission_uids')) if isinstance(base, dict) else None
        augmented = _i567_augment_base(working, cfg, sess)
        if isinstance(augmented, dict) and isinstance(pristine_raw, list):
            augmented = dict(augmented)
            augmented['mission_uids'] = pristine_raw
        return _i567_finalize_payload(augmented)
