    def _i568_call(cfg, sess, url, label, timeout):
        started = time.monotonic()
        result = _i568_request_json_before(cfg, sess, url, timeout=max(1, int(timeout)))
        duration = round(time.monotonic() - started, 4)
        return url, result, {
            'endpoint': label,
            'url_path': urlparse(url).path,
            'ok': bool(isinstance(result, dict) and result.get('ok')),
            'status': int((result or {}).get('status') or 0) if isinstance(result, dict) else 0,
            'duration_seconds': duration,
            'error': _i568_text((result or {}).get('error'))[:300] if isinstance(result, dict) else 'invalid-result',
        }

    def _i568_run_parallel(tasks, cfg, sess, deadline, max_workers):
        responses = {}
        timings = []
        if not tasks:
            return responses, timings
        executor = ThreadPoolExecutor(max_workers=max(1, min(int(max_workers), len(tasks))))
        future_map = {}
        try:
            for task in tasks:
                url, label, timeout = task
                future_map[executor.submit(_i568_call, cfg, sess, url, label, timeout)] = task
            remaining = max(0.0, deadline - time.monotonic())
            done, pending = _i568_wait(list(future_map), timeout=remaining)
            for future in done:
                task = future_map[future]
                try:
                    url, result, timing = future.result()
                except Exception as exc:
                    url = task[0]
                    result = {'ok': False, 'status': 0, 'body': None, 'error': _i568_text(exc)}
                    timing = {'endpoint': task[1], 'url_path': urlparse(url).path, 'ok': False, 'status': 0, 'duration_seconds': None, 'error': _i568_text(exc)[:300]}
                responses[url] = result
                timings.append(timing)
            for future in pending:
                url, label, _timeout = future_map[future]
                future.cancel()
                responses[url] = {'ok': False, 'status': 0, 'body': None, 'error': 'Overall i568 refresh deadline reached before this endpoint completed.'}
                timings.append({'endpoint': label, 'url_path': urlparse(url).path, 'ok': False, 'status': 0, 'duration_seconds': None, 'error': 'overall-refresh-deadline'})
        finally:
            executor.shutdown(wait=False, cancel_futures=True)
        return responses, timings

    def _i568_parallel_acquisition(cfg, sess):
        started = time.monotonic()
        deadline = started + _I568_OVERALL_REFRESH_DEADLINE_SECONDS
        api = _i568_text((cfg or {}).get('api_url') or (cfg or {}).get('base_url')).rstrip('/')
        marti = _i568_text((cfg or {}).get('marti_url')).rstrip('/')
        discovery_tasks = []
        if api:
            discovery_tasks.append((api + '/api/missions', 'discovery:ots-api', _I568_DISCOVERY_TIMEOUT_SECONDS))
        if marti:
            discovery_tasks.append((marti + '/Marti/api/missions', 'discovery:marti', _I568_DISCOVERY_TIMEOUT_SECONDS))
        responses, timings = _i568_run_parallel(discovery_tasks, cfg, sess, deadline, 2)
        mission_names = []
        for url, _label, _timeout in discovery_tasks:
            result = responses.get(url) or {}
            if result.get('ok'):
                for name in _i512_mission_names(result.get('body')):
                    if name not in mission_names:
                        mission_names.append(name)
        mission_names = mission_names[:20]
        mission_tasks = []
        for mission in mission_names:
            q = quote(mission, safe='')
            for suffix, kind in (('', 'detail'), ('/contents', 'contents'), ('/cot', 'cot')):
                if marti:
                    mission_tasks.append((marti + '/Marti/api/missions/' + q + suffix, 'mission:' + mission + ':' + kind, _I568_ENDPOINT_TIMEOUT_SECONDS))
        mission_responses, mission_timings = _i568_run_parallel(mission_tasks, cfg, sess, deadline, _I568_MAX_WORKERS)
        responses.update(mission_responses)
        timings.extend(mission_timings)
        discovery_ok = any(bool((responses.get(url) or {}).get('ok')) for url, _label, _timeout in discovery_tasks)
        completed = sum(1 for row in timings if row.get('ok'))
        return {
            'responses': responses,
            'mission_names': mission_names,
            'timings': sorted(timings, key=lambda row: (str(row.get('endpoint') or ''))),
            'summary': {
                'version': 'i568',
                'discovery_ok': discovery_ok,
                'discovery_endpoint_count': len(discovery_tasks),
                'mission_count': len(mission_names),
                'mission_endpoint_count': len(mission_tasks),
                'successful_endpoint_count': completed,
                'failed_endpoint_count': max(0, len(timings) - completed),
                'max_workers': _I568_MAX_WORKERS,
                'per_endpoint_timeout_seconds': _I568_ENDPOINT_TIMEOUT_SECONDS,
                'overall_deadline_seconds': _I568_OVERALL_REFRESH_DEADLINE_SECONDS,
                'duration_seconds': round(time.monotonic() - started, 4),
            },
        }

    def _i568_result_body(result):
        if not isinstance(result, dict):
            return None
        return result.get('body')

    def _i568_walk_dicts(value, limit=20000):
        rows = []
        stack = [value]
        seen = set()
        while stack and len(rows) < int(limit):
            current = stack.pop()
            if isinstance(current, dict):
                ident = id(current)
                if ident in seen:
                    continue
                seen.add(ident)
                rows.append(current)
                for nested in current.values():
                    if isinstance(nested, (dict, list, tuple)):
                        stack.append(nested)
            elif isinstance(current, (list, tuple)):
                stack.extend(current)
        return rows

    def _i568_row_uid(row):
        if not isinstance(row, dict):
            return ''
        for source in (row, row.get('properties'), row.get('details')):
            if not isinstance(source, dict):
                continue
            for key in ('event_uid', 'cot_uid', 'cotUid', 'uid', 'data', 'data_uid', 'id'):
                value = _i568_text(source.get(key))
                if value:
                    return value
        return ''

    def _i568_seed_scope_cache(cfg, sess, acquired):
        if not bool((acquired.get('summary') or {}).get('discovery_ok')):
            return False
        if '_I539_SCOPE_CACHE' not in globals() or '_I539_SCOPE_LOCK' not in globals() or '_i539_identity_key' not in globals():
            return False
        mission_names = list(acquired.get('mission_names') or [])
        status = 0
        errors = []
        for row in list(acquired.get('timings') or []):
            if str(row.get('endpoint') or '').startswith('discovery:'):
                status = max(status, int(row.get('status') or 0))
                if row.get('error'):
                    errors.append(_i568_text(row.get('error')))
        profile = (sess or {}).get('profile') if isinstance((sess or {}).get('profile'), dict) else {}
        record = {
            'ok': True,
            'state': 'ok',
            'missions': list(dict.fromkeys(_i568_text(name) for name in mission_names if _i568_text(name))),
            'cached': False,
            'status': status or 200,
            'error': '',
            'duration_ms': int(float((acquired.get('summary') or {}).get('duration_seconds') or 0) * 1000),
            'identity_mode': 'per-user-background-mission-worker-i568',
            'certificate_cn': _i568_text((sess or {}).get('certificate_cn') or profile.get('certificate_cn')),
            'client_uid': _i568_text((sess or {}).get('tak_uid') or profile.get('tak_uid')),
            'time': time.time(),
            'source': 'i568-bounded-parallel-discovery',
        }
        key = _i539_identity_key(sess or {}, cfg or {})
        with _I539_SCOPE_LOCK:
            _I539_SCOPE_CACHE[key] = dict(record)
        return True

    def _i568_seed_enrichment_cache(cfg, sess, acquired):
        if '_I545_ENRICH_CACHE' not in globals() or '_I545_ENRICH_LOCK' not in globals() or '_i545_cache_key' not in globals() or '_i545_extract_events' not in globals():
            return False
        marti = _i568_text((cfg or {}).get('marti_url')).rstrip('/')
        names = list(acquired.get('mission_names') or [])
        responses = acquired.get('responses') if isinstance(acquired.get('responses'), dict) else {}
        combined = {}
        rows = []
        any_ok = False
        for mission in names:
            path = '/Marti/api/missions/' + quote(_i568_text(mission), safe='') + '/cot'
            url = marti + path if marti else ''
            result = responses.get(url) if url else None
            ok = bool(isinstance(result, dict) and result.get('ok'))
            any_ok = any_ok or ok
            body = _i568_result_body(result)
            events = _i545_extract_events(body if not isinstance(body, str) else None, body if isinstance(body, str) else '') if ok else {}
            rows.append({
                'mission': _i568_text(mission),
                'path': path,
                'ok': ok,
                'status': int((result or {}).get('status') or 0) if isinstance(result, dict) else 0,
                'error': _i568_text((result or {}).get('error')) if isinstance(result, dict) else 'request-missing',
                'event_count': len(events),
                'query_strategy': 'i568-bounded-parallel-user-scope',
            })
            for uid, event in dict(events or {}).items():
                candidate = dict(event or {})
                candidate['mission_name'] = _i568_text(mission)
                current = combined.get(uid)
                replace = current is None
                if not replace and '_i547_event_rank' in globals():
                    try:
                        replace = _i547_event_rank(candidate) > _i547_event_rank(current)
                    except Exception:
                        replace = False
                if replace:
                    combined[uid] = candidate
        requested = tuple(sorted({_i568_text(name).casefold() for name in names if _i568_text(name)}))
        record = {
            'ok': any_ok,
            'time': time.time(),
            'requested': requested,
            'events': combined,
            'missions': rows,
            'event_count': len(combined),
            'error': '' if any_ok else '; '.join(_i568_text(row.get('error')) for row in rows if row.get('error'))[:1000],
            'refresh_mode_i568': 'bounded-parallel-background-worker',
        }
        key = _i545_cache_key(cfg or {}, sess or {})
        with _I545_ENRICH_LOCK:
            _I545_ENRICH_CACHE[key] = record
        return True

    def _i568_seed_remote_mission_data(base, cfg, acquired):
        out = _i568_clone(base) if isinstance(base, dict) else {}
        if not isinstance(out, dict):
            out = {}
        names = list(acquired.get('mission_names') or [])
        responses = acquired.get('responses') if isinstance(acquired.get('responses'), dict) else {}
        marti = _i568_text((cfg or {}).get('marti_url')).rstrip('/')

        missions = list(out.get('missions') or [])
        known_missions = set()
        for row in missions:
            if isinstance(row, dict):
                name = _i568_text(row.get('name') or row.get('mission_name') or row.get('missionName'))
            else:
                name = _i568_text(row)
            if name:
                known_missions.add(name.casefold())
        for name in names:
            if _i568_text(name).casefold() not in known_missions:
                missions.append({'name': _i568_text(name), 'source': 'Mission API i568 background worker'})
                known_missions.add(_i568_text(name).casefold())
        out['missions'] = missions

        objects = list(out.get('objects') or [])
        object_keys = set()
        for row in objects:
            uid = _i568_row_uid(row)
            mission = _i568_text((row or {}).get('mission') or (row or {}).get('mission_name')) if isinstance(row, dict) else ''
            if uid:
                object_keys.add((mission.casefold(), uid.casefold()))

        raw_rows = list(out.get('mission_uids') or [])
        raw_keys = set()
        for row in raw_rows:
            uid = _i568_row_uid(row)
            mission = _i568_text((row or {}).get('mission') or (row or {}).get('mission_name')) if isinstance(row, dict) else ''
            if uid:
                raw_keys.add((mission.casefold(), uid.casefold()))

        content_rows = list(out.get('mission_content') or [])
        content_keys = set()
        for row in content_rows:
            if not isinstance(row, dict):
                continue
            mission = _i568_text(row.get('mission') or row.get('mission_name'))
            ident = _i568_text(row.get('hash') or row.get('data') or row.get('uid') or row.get('filename') or row.get('name'))
            if ident:
                content_keys.add((mission.casefold(), ident.casefold()))

        for mission in names:
            q = quote(_i568_text(mission), safe='')
            for suffix in ('', '/contents', '/cot'):
                url = marti + '/Marti/api/missions/' + q + suffix if marti else ''
                result = responses.get(url) if url else None
                if not (isinstance(result, dict) and result.get('ok')):
                    continue
                body = _i568_result_body(result)
                try:
                    projected = _i512_mission_api_objects(body, _i568_text(mission))
                except Exception:
                    projected = []
                for row in projected:
                    if not isinstance(row, dict):
                        continue
                    candidate = _i568_clone(row)
                    candidate['mission'] = _i568_text(mission)
                    candidate['mission_name'] = _i568_text(mission)
                    candidate['source'] = 'Mission API i568 background worker'
                    uid = _i568_row_uid(candidate)
                    key = (_i568_text(mission).casefold(), uid.casefold()) if uid else None
                    if key and key in object_keys:
                        continue
                    if key:
                        object_keys.add(key)
                    objects.append(candidate)
                for nested in _i568_walk_dicts(body):
                    candidate = _i568_clone(nested)
                    if not isinstance(candidate, dict):
                        continue
                    candidate.setdefault('mission', _i568_text(mission))
                    candidate.setdefault('mission_name', _i568_text(mission))
                    candidate.setdefault('source', 'Mission API i568 background worker')
                    uid = _i568_row_uid(candidate)
                    if uid:
                        key = (_i568_text(mission).casefold(), uid.casefold())
                        if key not in raw_keys:
                            raw_keys.add(key)
                            raw_rows.append(candidate)
                    if suffix == '/contents':
                        ident = _i568_text(candidate.get('hash') or candidate.get('data') or candidate.get('uid') or candidate.get('filename') or candidate.get('name'))
                        key = (_i568_text(mission).casefold(), ident.casefold()) if ident else None
                        if key and key not in content_keys:
                            content_keys.add(key)
                            content_rows.append(candidate)

        out['objects'] = objects
        out['mission_uids'] = raw_rows
        out['mission_content'] = content_rows
        out['data_sync_remote_seed_i568'] = {
            'version': 'i568',
            'mission_count': len(names),
            'objects_after_seed': len(objects),
            'mission_uids_after_seed': len(raw_rows),
            'mission_content_after_seed': len(content_rows),
            'per_user_authenticated_source': True,
        }
        return out

    def _i512_request_json(cfg, sess, url, timeout=10):
        responses = getattr(_I568_REQUEST_CONTEXT, 'responses', None)
        if isinstance(responses, dict) and url in responses:
            return _i568_clone(responses[url])
        # The old implementation could block each serial endpoint for ten
        # seconds. Any residual caller receives the i568 short deadline.
        return _i568_request_json_before(cfg, sess, url, timeout=min(max(1, int(timeout or 1)), _I568_ENDPOINT_TIMEOUT_SECONDS))
    globals()['_i512_request_json'] = _i512_request_json

    def _i568_build_snapshot(cfg, sess, token, reason):
        acquired = _i568_parallel_acquisition(cfg, sess)
        if not acquired['summary'].get('discovery_ok'):
            errors = [row.get('error') for row in acquired.get('timings') or [] if row.get('error')]
            raise RuntimeError('OpenTAKServer Mission discovery did not complete successfully. ' + '; '.join(errors[:4]))
        # Feed the bounded, per-user acquisition into the existing scope and CoT
        # enrichment caches so older layers never launch their own serial probes.
        _i568_seed_scope_cache(cfg, sess, acquired)
        _i568_seed_enrichment_cache(cfg, sess, acquired)
        _I568_REQUEST_CONTEXT.responses = acquired.get('responses') or {}
        base = _i568_seed_remote_mission_data(tak_map_data_sync(), cfg, acquired)
        result = _i568_augment_before(base, cfg, sess)
        if not isinstance(result, dict):
            raise RuntimeError('Data Sync augmentation returned an invalid response.')
        result = _i568_clone(result)
        result['ok'] = bool(result.get('ok', True))
        result['version'] = 'i568'
        result['data_sync_background_worker_i568'] = {
            'version': 'i568',
            'acquisition': dict(acquired.get('summary') or {}),
            'endpoint_timings': list(acquired.get('timings') or [])[:120],
            'serial_browser_route_acquisition': False,
            'last_known_good_preserved': True,
        }
        return result, acquired

    def _i568_refresh_worker(key, cfg, sess, token, reason, generation):
        started_epoch = time.time()
        started_mono = time.monotonic()
        _i568_set_context(token, sess)
        try:
            result, acquired = _i568_build_snapshot(cfg, sess, token, reason)
            completed_epoch = time.time()
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                # A newer generation may have been scheduled while this one was
                # running. Never let an older result overwrite it.
                if int(state.get('generation') or 0) == int(generation):
                    state['snapshot'] = result
                    state['last_success_epoch'] = completed_epoch
                    state['last_attempt_completed_epoch'] = completed_epoch
                    state['last_attempt_duration_seconds'] = round(time.monotonic() - started_mono, 4)
                    state['last_error'] = ''
                    state['endpoint_timings'] = list(acquired.get('timings') or [])[:120]
                    state['acquisition_summary'] = dict(acquired.get('summary') or {})
                    _i568_persist_success(state)
        except Exception as exc:
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['last_attempt_completed_epoch'] = time.time()
                    state['last_attempt_duration_seconds'] = round(time.monotonic() - started_mono, 4)
                    state['last_error'] = _i568_text(exc)[:1200]
        finally:
            _i568_clear_context()
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['in_flight'] = False
                    state['last_attempt_completed_epoch'] = state.get('last_attempt_completed_epoch') or time.time()
                    state['last_attempt_duration_seconds'] = state.get('last_attempt_duration_seconds') or round(time.monotonic() - started_mono, 4)

    def _i568_schedule_refresh(key, cfg, sess, token, reason, force=False):
        now = time.time()
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            if state.get('in_flight'):
                return False, 'already-running'
            last_attempt = float(state.get('last_attempt_started_epoch') or 0)
            if not force and last_attempt and now - last_attempt < _I568_RETRY_COOLDOWN_SECONDS and not state.get('snapshot'):
                return False, 'retry-cooldown'
            state['generation'] = int(state.get('generation') or 0) + 1
            generation = state['generation']
            state['in_flight'] = True
            state['last_attempt_started_epoch'] = now
            state['last_reason'] = _i568_text(reason) or ('manual' if force else 'automatic')
        thread = threading.Thread(
            target=_i568_refresh_worker,
            args=(key, _i568_clone(cfg), _i568_clone(sess), _i568_text(token), _i568_text(reason), generation),
            name='tak-map-i568-data-sync-' + key[:8],
            daemon=True,
        )
        thread.start()
        return True, 'scheduled'

    def _i568_response_payload(state):
        now = time.time()
        with _I568_STATE_LOCK:
            snapshot = _i568_clone(state.get('snapshot')) if isinstance(state.get('snapshot'), dict) else None
            last_success = float(state.get('last_success_epoch') or 0)
            in_flight = bool(state.get('in_flight'))
            last_error = _i568_text(state.get('last_error'))
            diag = {
                'version': 'i568',
                'snapshot_available': bool(snapshot),
                'refreshing': in_flight,
                'last_success_at': _i568_iso(last_success),
                'last_success_age_seconds': round(max(0.0, now - last_success), 3) if last_success else None,
                'last_attempt_started_at': _i568_iso(state.get('last_attempt_started_epoch') or 0),
                'last_attempt_completed_at': _i568_iso(state.get('last_attempt_completed_epoch') or 0),
                'last_attempt_duration_seconds': state.get('last_attempt_duration_seconds') or 0,
                'last_error': last_error,
                'last_reason': state.get('last_reason') or '',
                'generation': int(state.get('generation') or 0),
                'automatic_poll_seconds': _I568_SNAPSHOT_MAX_AGE_SECONDS,
                'parallel_max_workers': _I568_MAX_WORKERS,
                'per_endpoint_timeout_seconds': _I568_ENDPOINT_TIMEOUT_SECONDS,
                'overall_refresh_deadline_seconds': _I568_OVERALL_REFRESH_DEADLINE_SECONDS,
                'acquisition_summary': dict(state.get('acquisition_summary') or {}),
                'endpoint_timings': list(state.get('endpoint_timings') or [])[:120],
                'last_known_good_preserved': True,
                'browser_route_blocks_on_ots': False,
            }
        if snapshot:
            payload = snapshot
            if in_flight:
                diag['state'] = 'refreshing-last-known-good'
                diag['message'] = 'Refreshing OTS missions in the background. Showing the last successful snapshot.'
            elif last_error:
                diag['state'] = 'stale-last-known-good'
                diag['message'] = 'Showing the last successful Data Sync snapshot. The latest OTS refresh failed.'
            else:
                diag['state'] = 'ready'
                diag['message'] = 'Data Sync snapshot ready.'
            payload['data_sync_background_i568'] = diag
            payload['refreshing'] = in_flight
            payload['stale'] = bool(last_error)
            payload['version'] = 'i568'
            return payload
        message = 'Initial OTS refresh in progress'
        if last_error and not in_flight:
            message = 'Initial OTS refresh is retrying after a temporary OpenTAKServer error'
        diag['state'] = 'initial-refresh-in-progress'
        diag['message'] = message
        return {
            'ok': True,
            'version': 'i568',
            'objects': [],
            'missions': [],
            'mission_content': [],
            'mission_uids': [],
            'refreshing': True,
            'initial_ots_refresh_in_progress': True,
            'message': message,
            'data_sync_background_i568': diag,
        }

    _i568_get_before = Handler.do_GET
    def _i568_do_get(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path == '/mil2525/atak-compatibility-aliases-i553.json':
            shared = _I568_SHARED_MIL_ROOT / 'atak-compatibility-aliases-i553.json'
            packaged = _I568_ROOT / 'assets' / 'mil2525' / 'atak-compatibility-aliases-i553.json'
            selected = shared if shared.is_file() else packaged
            return _i541_send_file(self, selected, 'application/json; charset=utf-8', 'i568-active-atak-alias-catalog')
        runtime = {
            '/assets/runtime/tak-map-icon-registry-i568.js': (_I568_ROOT / 'assets' / 'tak-map-icon-registry-i568.js', 'application/javascript; charset=utf-8'),
            '/assets/runtime/tak-map-popup-localdata-i568.js': (_I568_ROOT / 'assets' / 'tak-map-popup-localdata-i568.js', 'application/javascript; charset=utf-8'),
            '/assets/runtime/tak-map-context-sidebar-i568.js': (_I568_ROOT / 'assets' / 'tak-map-context-sidebar-i568.js', 'application/javascript; charset=utf-8'),
        }.get(path)
        if runtime:
            return _i541_send_file(self, runtime[0], runtime[1], 'i568-background-data-sync')
        if path == '/api/tak-map/data-sync':
            if not self._tak_map_auth_ok():
                return self._require_tak_map_login()
            sess = self._tak_map_session()
            if '_i512_forced_change' in globals() and _i512_forced_change(sess):
                return self._send_json({'ok': False, 'password_change_required': True, 'error': 'Change the default local administrator password first.'}, 428)
            cfg = _i509_load_ots_config() if '_i509_load_ots_config' in globals() else {}
            auth_mode = _i568_text((sess or {}).get('auth_mode'))
            if not auth_mode.startswith('ots-'):
                try:
                    token = self._tak_map_token() if callable(getattr(self, '_tak_map_token', None)) else ''
                    _i568_set_context(token, sess or {})
                    payload = _i568_augment_before(tak_map_data_sync(), cfg or {}, sess or {})
                    payload = _i568_clone(payload) if isinstance(payload, dict) else {'ok': True, 'objects': [], 'missions': []}
                    payload['version'] = 'i568'
                    payload['data_sync_background_i568'] = {'version': 'i568', 'state': 'not-applicable-local-session', 'snapshot_available': True, 'refreshing': False, 'browser_route_blocks_on_ots': False}
                    return self._send_json(payload)
                finally:
                    _i568_clear_context()
            query = parse_qs(parsed.query or '')
            force = _i568_text((query.get('force') or ['0'])[0]).casefold() in ('1', 'true', 'yes', 'on')
            reason = _i568_text((query.get('reason') or [''])[0]) or ('manual' if force else 'poll')
            token = self._tak_map_token() if callable(getattr(self, '_tak_map_token', None)) else ''
            key = _i568_state_key(cfg or {}, sess or {})
            state = _i568_state(key)
            with _I568_STATE_LOCK:
                last_success = float(state.get('last_success_epoch') or 0)
                stale = not last_success or (time.time() - last_success >= _I568_SNAPSHOT_MAX_AGE_SECONDS)
            if force or stale:
                _i568_schedule_refresh(key, cfg or {}, sess or {}, token, reason, force=force)
            return self._send_json(_i568_response_payload(state))
        return _i568_get_before(self)
    Handler.do_GET = _i568_do_get

