    def _i568_patch_html(html):
        if not isinstance(html, str):
            return html
        html = re.sub(r'1\.3\.0-i567', '1.3.0-i568', html)
        html = re.sub(r'TAKDashboard/i567', 'TAKDashboard/i568', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i567', 'TAK-Map/1.3.0 i568', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i568\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i568\2', html)
        html = re.sub(r'tak-map-icon-registry-i\d+\.js', 'tak-map-icon-registry-i568.js', html)
        html = re.sub(r'tak-map-popup-localdata-i\d+\.js', 'tak-map-popup-localdata-i568.js', html)
        html = re.sub(r'tak-map-context-sidebar-i\d+\.js', 'tak-map-context-sidebar-i568.js', html)
        html = re.sub(r'v=1\.3\.0-i567', 'v=1.3.0-i568', html)
        html = html.replace('takMapIconRegistryI567', 'takMapIconRegistryI568')
        html = html.replace('takMapPopupLocalDataI567', 'takMapPopupLocalDataI568')
        html = html.replace('takMapContextSidebarI567', 'takMapContextSidebarI568')
        return html
