    def _i572_subscribe_with_password(mission, creator_uid, password, server_host=''):
        mission = _i568_text(mission)
        creator_uid = _i568_text(creator_uid)
        password = str(password or '')
        if not mission or not creator_uid:
            return {'ok': False, 'status': 400, 'error': 'Mission name and authenticated ATAK client UID are required.'}
        query = 'uid=' + quote(creator_uid, safe='')
        if password:
            query += '&password=' + quote(password, safe='')
        path = '/Marti/api/missions/' + quote(mission, safe='') + '/subscription?' + query
        # Use the raw request adapter so the password is sent only to OTS and is
        # never copied into browser-visible responses or TAK Map diagnostics.
        response = _i564_mission_request_raw(
            path, method='PUT', body=b'',
            headers={'User-Agent': _I564_ATAK_USER_AGENT, 'Content-Length': '0', 'Accept': 'application/json,*/*'},
            public_host=server_host, timeout=15)
        token = _i564_extract_subscription_token((response or {}).get('json') or {})
        status = _i564_response_status(response)
        if isinstance(response, dict) and response.get('ok') and token:
            _i564_cache_mission_token(mission, creator_uid, token, 'protected-mission-unlock-i572')
            return {'ok': True, 'status': status or 200, 'token': token, 'source': 'protected-mission-unlock-i572'}
        reason = _i564_response_reason(response, 'OpenTAKServer did not accept the Mission unlock.')
        invalid = status == 401 or 'invalid password' in reason.casefold()
        return {
            'ok': False, 'status': 401 if invalid else (status or 502),
            'invalid_password': bool(invalid),
            'mission_password_required': bool(invalid),
            'error': 'Invalid Mission password.' if invalid else reason,
        }

    _i572_mission_token_before = _i564_mission_token
    def _i564_mission_token(mission, creator_uid, server_host='', force=False):
        mission = _i568_text(mission)
        creator_uid = _i568_text(creator_uid)
        if not mission or not creator_uid:
            return {'ok': False, 'status': 400, 'error': 'Mission name and authenticated ATAK client UID are required.'}
        if not force:
            token = _i572_cached_token(mission, creator_uid)
            if token:
                return {'ok': True, 'token': token, 'source': 'cache', 'status': 200}
        status = _i572_protected_status(mission)
        protected = bool(status.get('protected'))
        stored = _i572_load_password(mission)
        if protected and not stored.get('ok'):
            return {
                'ok': False, 'status': 428, 'mission_password_required': True,
                'error': 'This OpenTAKServer Mission is password protected. Unlock it before continuing.'
            }
        if stored.get('ok'):
            result = _i572_subscribe_with_password(mission, creator_uid, stored.get('password'), server_host)
            if not result.get('ok') and result.get('invalid_password'):
                _i572_remove_password(mission)
                _i564_invalidate_mission_token(mission, creator_uid)
            return result
        return _i572_mission_token_before(mission, creator_uid, server_host, force)
    globals()['_i564_mission_token'] = _i564_mission_token

    def _i572_public_status(mission):
        mission = _i568_text(mission)
        state = _i572_protected_status(mission)
        protected = bool(state.get('protected'))
        return {
            'ok': True, 'version': 'i572', 'mission': mission,
            'protected': protected, 'known': bool(state.get('known', True) if state else False),
            'unlocked': (not protected) or _i572_unlocked(mission),
            'password_stored_server_side': protected and bool(_i572_load_password(mission).get('ok')),
        }

    def _i572_unlock_action(payload):
        payload = payload if isinstance(payload, dict) else {}
        action = _i568_text(payload.get('action') or 'unlock').lower()
        mission = _i568_text(payload.get('mission') or payload.get('mission_name'))[:180]
        if not mission:
            return {'ok': False, 'version': 'i572', 'error': 'Mission name is required.'}, 400
        creator_uid = _i572_creator_uid()
        if not creator_uid:
            return {'ok': False, 'version': 'i572', 'error': 'The authenticated per-user TAK identity is unavailable.'}, 428
        if action == 'lock':
            _i572_remove_password(mission)
            _i564_invalidate_mission_token(mission, creator_uid)
            out = _i572_public_status(mission)
            out.update({'unlocked': False, 'message': 'Mission locked for this TAK Map user.'})
            return out, 200
        password = str(payload.get('password') or '')
        if not password:
            return {'ok': False, 'version': 'i572', 'mission': mission, 'error': 'Enter the Mission password.'}, 400
        if len(password) > 512:
            return {'ok': False, 'version': 'i572', 'mission': mission, 'error': 'Mission password is too long.'}, 400
        result = _i572_subscribe_with_password(mission, creator_uid, password)
        if not result.get('ok'):
            return {
                'ok': False, 'version': 'i572', 'mission': mission,
                'invalid_password': bool(result.get('invalid_password')),
                'mission_password_required': True,
                'error': _i568_text(result.get('error')) or 'Mission unlock failed.',
            }, int(result.get('status') or 401)
        saved = _i572_store_password(mission, password)
        password = ''
        if not saved.get('ok'):
            _i564_invalidate_mission_token(mission, creator_uid)
            return {'ok': False, 'version': 'i572', 'mission': mission, 'error': 'Mission unlocked, but secure server-side storage failed.'}, 500
        _i572_set_protected(mission, True)
        try:
            cfg = _i509_load_ots_config() if '_i509_load_ots_config' in globals() else {}
            sess = _i572_session()
            key = _i570_context_state_key(cfg, sess)
            _i568_schedule_refresh(key, cfg or {}, sess or {}, sess.get('_i570_token') or '', 'i572-protected-mission-unlocked', force=True)
        except Exception:
            pass
        out = _i572_public_status(mission)
        out.update({'unlocked': True, 'message': 'Mission unlocked for this TAK Map user.'})
        return out, 200

    # Stop immediately on protected-Mission authorization failure. Repeating the
    # same unauthorized /cot request cannot make a password appear.
    def _i528_confirm_readback(mission, uid, creator_uid, server_host=''):
        mission_q = quote(_i568_text(mission), safe='')
        event_uid = _i568_text(uid)
        primary_path = f'/Marti/api/missions/{mission_q}/cot'
        fallback_path = primary_path + '?creatorUid=' + quote(_i568_text(creator_uid), safe='') if _i568_text(creator_uid) else ''
        history = []
        deadline = time.monotonic() + _I570_READBACK_DEADLINE_SECONDS
        fallback_used = False
        for attempt in range(1, _I570_READBACK_ATTEMPTS + 1):
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            timeout = max(1, min(3, int(remaining + 0.999)))
            result = _ots_mission_api_request(primary_path, method='GET', public_host=server_host, timeout=timeout)
            row = _i570_readback_row(result, mission, event_uid)
            status = _i564_response_status(result)
            reason = _i564_response_reason(result, '')
            history.append({'attempt': attempt, 'path': primary_path, 'strategy': 'authenticated-mission-token-no-creatorUid',
                'status': status, 'ok': bool(isinstance(result, dict) and result.get('ok')), 'exact_uid_present': bool(row),
                'error': reason[:300]})
            if row:
                _i570_cache_confirmed_row(mission, event_uid, row)
                return {'ok': True, 'source': 'mission-api-get-cot-exact-uid-i572', 'event_uid': event_uid,
                    'path': primary_path, 'attempts': history, 'readback_row_cached': True,
                    'creator_uid_filter_primary': False, 'creator_uid_fallback_used': False,
                    'mission_uid_row_alone_counts_as_readback': False}
            if status == 401 or 'invalid password' in reason.casefold():
                _i564_invalidate_mission_token(mission, creator_uid)
                return {'ok': False, 'source': 'mission-api-get-cot-exact-uid-i572', 'event_uid': event_uid,
                    'path': primary_path, 'attempts': history, 'mission_password_required': True,
                    'creator_uid_filter_primary': False, 'creator_uid_fallback_used': False,
                    'mission_uid_row_alone_counts_as_readback': False,
                    'error': 'The protected Mission must be unlocked with the correct password before read-back.'}
            if attempt == 1 and fallback_path and not bool((result or {}).get('ok')) and status in (400, 404, 405, 406, 415, 422):
                remaining = deadline - time.monotonic()
                if remaining > 0:
                    fallback_used = True
                    fallback = _ots_mission_api_request(fallback_path, method='GET', public_host=server_host,
                                                        timeout=max(1, min(3, int(remaining + 0.999))))
                    fallback_row = _i570_readback_row(fallback, mission, event_uid)
                    fallback_status = _i564_response_status(fallback)
                    fallback_reason = _i564_response_reason(fallback, '')
                    history.append({'attempt': attempt, 'path': fallback_path, 'strategy': 'compatibility-creatorUid-fallback',
                        'status': fallback_status, 'ok': bool(isinstance(fallback, dict) and fallback.get('ok')),
                        'exact_uid_present': bool(fallback_row), 'error': fallback_reason[:300]})
                    if fallback_row:
                        _i570_cache_confirmed_row(mission, event_uid, fallback_row)
                        return {'ok': True, 'source': 'mission-api-get-cot-exact-uid-i572', 'event_uid': event_uid,
                            'path': fallback_path, 'attempts': history, 'readback_row_cached': True,
                            'creator_uid_filter_primary': False, 'creator_uid_fallback_used': True,
                            'mission_uid_row_alone_counts_as_readback': False}
                    if fallback_status == 401 or 'invalid password' in fallback_reason.casefold():
                        _i564_invalidate_mission_token(mission, creator_uid)
                        return {'ok': False, 'source': 'mission-api-get-cot-exact-uid-i572', 'event_uid': event_uid,
                            'path': fallback_path, 'attempts': history, 'mission_password_required': True,
                            'creator_uid_filter_primary': False, 'creator_uid_fallback_used': True,
                            'mission_uid_row_alone_counts_as_readback': False,
                            'error': 'The protected Mission must be unlocked with the correct password before read-back.'}
            if attempt < _I570_READBACK_ATTEMPTS and deadline - time.monotonic() > 0.35:
                time.sleep(0.35)
        return {'ok': False, 'source': 'mission-api-get-cot-exact-uid-i572', 'event_uid': event_uid,
            'path': primary_path, 'attempts': history, 'creator_uid_filter_primary': False,
            'creator_uid_fallback_used': fallback_used, 'mission_uid_row_alone_counts_as_readback': False,
            'error': 'The exact point UID was not returned by Mission read-back within the bounded confirmation window. Local Data was retained.'}
    globals()['_i528_confirm_readback'] = _i528_confirm_readback

    def _i572_preflight_mission(mission):
        status = _i572_protected_status(mission)
        if not status.get('protected'):
            return {'ok': True, 'protected': False}
        creator_uid = _i572_creator_uid()
        if not creator_uid:
            return {'ok': False, 'status': 428, 'error': 'The authenticated per-user TAK identity is unavailable.'}
        token = _i564_mission_token(mission, creator_uid, force=False)
        if token.get('ok'):
            return {'ok': True, 'protected': True, 'unlocked': True}
        return {'ok': False, 'status': int(token.get('status') or 428),
            'mission_password_required': True,
            'error': _i568_text(token.get('error')) or 'Unlock the protected Mission before saving.'}

    def _i572_ingest_confirmed(publish):
        points = list((publish or {}).get('points') or []) if isinstance(publish, dict) else []
        if not points:
            return False
        for point in points:
            if not isinstance(point, dict):
                return False
            ingest = point.get('per_user_cot_ingest') if isinstance(point.get('per_user_cot_ingest'), dict) else point.get('native_mission_cot')
            if not isinstance(ingest, dict) or not bool(ingest.get('ingest_confirmed')):
                return False
        return True

    def _i572_auth_only_readback_failure(publish):
        points = list((publish or {}).get('points') or []) if isinstance(publish, dict) else []
        seen = False
        for point in points:
            readback = point.get('mission_readback') if isinstance(point, dict) and isinstance(point.get('mission_readback'), dict) else {}
            attempts = list(readback.get('attempts') or [])
            statuses = [int((row or {}).get('status') or 0) for row in attempts if isinstance(row, dict)]
            if not statuses or any(status != 401 for status in statuses):
                return False
            seen = True
        return seen

