    def _i572_patch_html(html):
        html = str(html or '')
        html = re.sub(r'1\.3\.0-i\d+', '1.3.0-i572', html)
        html = re.sub(r'TAKDashboard/i\d+', 'TAKDashboard/i572', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i\d+', 'TAK-Map/1.3.0 i572', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i572\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i572\2', html)
