    def _i583hf5_correct_optimistic_record(optimistic, row):
        if not isinstance(optimistic, dict):
            return
        key = _i583hf5_text(optimistic.get('key'))
        shadow_key = _i583hf5_text(optimistic.get('shadow_key'))
        if not key or not shadow_key:
            return
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            shadows = dict(state.get('i583_optimistic_rows') or {})
            record = dict(shadows.get(shadow_key) or {})
            current = record.get('row') if isinstance(record.get('row'), dict) else {}
            merged = _i570_merge_dict_nonempty(current, row) if '_i570_merge_dict_nonempty' in globals() else dict(current, **row)
            if '_i583hf_verified_row' in globals():
                merged = _i583hf_verified_row(merged, row.get('uid'), row.get('mission_name'))
            merged.update({
                'data_sync_confirmation_state_i583_hf5': 'published-associated-awaiting-mission-index',
                'data_sync_status_label_i583_hf5': 'Published · awaiting Mission index',
                'marker_api_publication_confirmed_i583_hf5': True,
                'mission_uid_association_confirmed_i583_hf5': True,
                'mission_cot_readback_deferred_i583_hf5': True,
                'delete_supported': True,
                'delete_unavailable_reason': '',
            })
            record['row'] = merged
            # Mission association is confirmed, but discovery has not yet observed the
            # UID. Keep membership_seen false so a temporarily stale Mission index can
            # never be interpreted as an authoritative deletion of this new point.
            record['membership_seen'] = False
            record['membership_seen_epoch'] = 0
            record['source_identity_verified_i583_hf1'] = True
            record['source_identity_verified_i583_hf5'] = True
            record['marker_api_publication_confirmed_i583_hf5'] = True
            record['mission_uid_association_confirmed_i583_hf5'] = True
            record['mission_cot_readback_deferred_i583_hf5'] = True
            record['published_epoch_i583_hf5'] = time.time()
            shadows[shadow_key] = record
            state['i583_optimistic_rows'] = shadows
            state['snapshot'] = _i583_merge_optimistic(
                state.get('snapshot') if isinstance(state.get('snapshot'), dict) else {
                    'ok': True, 'objects': [], 'mission_uids': [], 'missions': []
                },
                state, 'i583-hf5-r2-published-associated-awaiting-index',
                state.get('i581_membership_map') or {}, allow_retire=False)
            state['last_success_epoch'] = max(float(state.get('last_success_epoch') or 0), time.time())
            state['acquisition_summary'] = dict(state.get('acquisition_summary') or {})
            state['acquisition_summary']['phase'] = 'published-associated-awaiting-mission-index'
            state['i583_hf5_last_delayed_handoff'] = {
                'uid': row.get('uid'),
                'mission': row.get('mission_name'),
                'published': True,
                'mission_uid_associated': True,
                'mission_cot_readback_deferred': True,
                'delete_available': True,
                'single_visible_optimistic_marker': True,
                'updated_epoch': time.time(),
            }
            _i568_persist_success(state)

    _i583hf5_save_before = _i555_save_point
    def _i555_save_point(payload):
        payload = payload if isinstance(payload, dict) else {}
        reply, status = _i583hf5_save_before(payload)
        # Only reinterpret a new marker-API point whose remote marker write and
        # Mission UID association both succeeded. Every earlier failure remains fatal.
        if _i583hf5_text(payload.get('uid')):
            return reply, status
        if int(status or 0) != 502 or not isinstance(reply, dict):
            return reply, status
        publish = reply.get('publish') if isinstance(reply.get('publish'), dict) else {}
        delayed = _i583hf5_delayed_publication(publish)
        if not delayed:
            return reply, status

        row = _i583hf5_row(payload, publish, delayed)
        point = _i583hf5_public_point(row)
        publish_success = _i583hf5_clone(publish)
        publish_success['ok'] = True
        publish_success['publish_succeeded'] = True
        publish_success['readback_confirmed'] = False
        publish_success['mission_readback_deferred'] = True
        publish_success['publication_complete_without_mission_cot_readback_i583_hf5'] = True
        publish_success['close_publish_modal_after_success'] = True
        publish_success['disable_publish_after_success'] = True
        publish_success['data_sync_refresh_recommended'] = True
        publish_success['error'] = ''
        publish_success['message'] = 'Point published and associated with the Data Sync Mission; Mission indexing is continuing in the background.'

        success = {
            'ok': True,
            'version': _I583_HF5_VERSION,
            'message': 'Point published to OpenTAKServer and associated with the Data Sync Mission.',
            'status_label': 'Published · awaiting Mission index',
            'point': point,
            'publish': publish_success,
            'redraw_allowed': True,
            'server_marker_published': True,
            'marker_api_publication_confirmed': True,
            'mission_uid_associated': True,
            'mission_readback_deferred': True,
            'awaiting_mission_index': True,
            'publication_complete': True,
            'delete_supported': True,
            'mission_delete_target': 'uid',
            'mission_delete_value': row.get('uid'),
            'local_data_retained': False,
            'local_data_reconcile_required': False,
            'placement_preview_must_close': True,
            'single_visible_marker_handoff_i583_hf5': True,
            'point_not_eud_i583_hf5': True,
            'exact_location_preserved_i583_hf5': True,
        }

        try:
            optimistic = _i583_store_optimistic(payload, success)
            if optimistic:
                _i583hf5_correct_optimistic_record(optimistic, row)
                success['optimistic_data_sync_handoff_i583'] = {
                    'active': True,
                    'uid': optimistic.get('uid') or row.get('uid'),
                    'mission': optimistic.get('mission') or row.get('mission_name'),
                    'persisted_per_user': True,
                    'older_snapshot_cannot_remove': True,
                    'delete_available_immediately': True,
                    'mission_readback_deferred': True,
                }
                cfg = _i509_load_ots_config() if '_i509_load_ots_config' in globals() else {}
                sess = _i570_context_session() if '_i570_context_session' in globals() else {}
                token = _i583hf5_text((sess or {}).get('_i570_token'))
                _i568_schedule_refresh(
                    optimistic.get('key'), cfg or {}, sess or {}, token,
                    'i583-hf5-r2-post-save-membership-fastpath', force=False)
            else:
                success['optimistic_handoff_warning_i583_hf5'] = 'Publication succeeded, but the immediate optimistic Data Sync row could not be persisted.'
        except Exception as exc:
            # Remote publication and Mission association are already complete; do not
            # mislabel them as failed because local optimistic reconciliation warned.
            success['optimistic_handoff_warning_i583_hf5'] = _i583hf5_text(exc)[:1000]
        return success, 200
    globals()['_i555_save_point'] = _i555_save_point

