    def _i589_text(value):
        try:
            return str(value if value is not None else '').strip()
        except Exception:
            return ''

    def _i589_iso_now():
        return datetime.now(timezone.utc).isoformat()

    def _i589_bool(value, default=False):
        if isinstance(value, bool):
            return value
        if value is None:
            return bool(default)
        return _i589_text(value).lower() in ('1', 'true', 'yes', 'on', 'enabled')

    def _i589_path_within(path, root):
        try:
            candidate = Path(path).expanduser().resolve(strict=False)
            base = Path(root).expanduser().resolve(strict=False)
            return candidate == base or base in candidate.parents
        except Exception:
            return False

    def _i589_manifest_default():
        return {
            'version': _I589_VERSION,
            'status': 'not-enrolled',
            'origin': '',
            'created_at': '',
            'updated_at': '',
            'disconnected_at': '',
            'files': [],
            'managed_trees': [],
            'remote_certificates': [],
            'state_entries': [],
            'capabilities': {'remote_revocation': 'unknown'},
        }

    def _i589_manifest_load(adopt=True):
        with _I589_MANIFEST_LOCK:
            if not _I589_ENROLLMENT_MANIFEST_FILE.exists():
                for legacy_manifest in _I589_LEGACY_ENROLLMENT_MANIFEST_FILES:
                    if not legacy_manifest.exists():
                        continue
                    try:
                        _I589_ENROLLMENT_MANIFEST_FILE.parent.mkdir(parents=True, exist_ok=True)
                        os.replace(legacy_manifest, _I589_ENROLLMENT_MANIFEST_FILE)
                    except Exception:
                        try:
                            legacy_raw = load_json_file(legacy_manifest, {})
                            if isinstance(legacy_raw, dict) and legacy_raw:
                                atomic_write_json(_I589_ENROLLMENT_MANIFEST_FILE, legacy_raw)
                                os.chmod(_I589_ENROLLMENT_MANIFEST_FILE, 0o600)
                                legacy_manifest.unlink(missing_ok=True)
                        except Exception:
                            pass
                    break
            raw = load_json_file(_I589_ENROLLMENT_MANIFEST_FILE, {})
            manifest = _i589_manifest_default()
            if isinstance(raw, dict):
                manifest.update(raw)
            for key in ('files', 'managed_trees', 'remote_certificates', 'state_entries'):
                if not isinstance(manifest.get(key), list):
                    manifest[key] = []
            if not isinstance(manifest.get('capabilities'), dict):
                manifest['capabilities'] = {'remote_revocation': 'unknown'}
        if adopt and manifest.get('status') == 'not-enrolled':
            cfg = _i509_load_ots_config()
            if cfg.get('base_url') or TAK_MAP_OTS_CONFIG_FILE.exists():
                manifest = _i589_adopt_existing_enrollment(manifest, cfg)
        return manifest

    def _i589_manifest_write(manifest):
        manifest = dict(manifest or {})
        manifest['version'] = _I589_VERSION
        manifest['updated_at'] = _i589_iso_now()
        _I589_ENROLLMENT_MANIFEST_FILE.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_json(_I589_ENROLLMENT_MANIFEST_FILE, manifest)
        try:
            os.chmod(_I589_ENROLLMENT_MANIFEST_FILE, 0o600)
        except Exception:
            pass
        return manifest

    def _i589_unique_append(rows, record, keys=('path',)):
        rows = rows if isinstance(rows, list) else []
        needle = tuple(_i589_text(record.get(key)) for key in keys)
        for existing in rows:
            if isinstance(existing, dict) and tuple(_i589_text(existing.get(key)) for key in keys) == needle:
                existing.update(record)
                return rows
        rows.append(record)
        return rows

    def _i589_record_file(manifest, path, kind, created_by='tak-map', removable=True):
        path = Path(path).expanduser()
        if not path.exists() and not path.is_symlink():
            return manifest
        record = {
            'path': str(path),
            'kind': _i589_text(kind),
            'created_by': _i589_text(created_by),
            'removable': bool(removable),
            'recorded_at': _i589_iso_now(),
        }
        try:
            if path.is_file() and path.stat().st_size <= 32 * 1024 * 1024:
                record['sha256'] = hashlib.sha256(path.read_bytes()).hexdigest()
        except Exception:
            pass
        manifest['files'] = _i589_unique_append(manifest.get('files'), record, ('path',))
        return manifest

    def _i589_record_tree(manifest, path, kind, created_by='tak-map'):
        path = Path(path).expanduser()
        if not path.exists():
            return manifest
        record = {
            'path': str(path),
            'kind': _i589_text(kind),
            'created_by': _i589_text(created_by),
            'removable': True,
            'recorded_at': _i589_iso_now(),
        }
        manifest['managed_trees'] = _i589_unique_append(manifest.get('managed_trees'), record, ('path',))
        return manifest

    def _i589_remote_cert_from_meta(meta, cert_path=''):
        meta = dict(meta or {})
        rec = {
            'username': _i589_text(meta.get('username')),
            'client_uid': _i589_text(meta.get('client_uid')),
            'certificate_cn': _i589_text(meta.get('certificate_cn')),
            'serial_number': '',
            'enrollment_endpoint': _i589_text(meta.get('enrollment_endpoint')),
            'certificate_path': _i589_text(cert_path),
            'recorded_at': _i589_iso_now(),
        }
        try:
            decoded = ssl._ssl._test_decode_cert(str(cert_path)) if cert_path and Path(cert_path).is_file() else {}
            rec['serial_number'] = _i589_text(decoded.get('serialNumber'))
            rec['certificate_cn'] = rec['certificate_cn'] or _i529_cert_cn(decoded)
        except Exception:
            pass
        return rec

    def _i589_adopt_existing_enrollment(manifest=None, cfg=None):
        manifest = dict(manifest or _i589_manifest_default())
        cfg = dict(cfg or _i509_load_ots_config())
        origin = _i589_text(cfg.get('base_url')).rstrip('/')
        manifest['status'] = 'enrolled' if cfg.get('enabled') or cfg.get('login_enabled') else 'disconnected'
        manifest['origin'] = origin
        manifest['created_at'] = manifest.get('created_at') or _i589_iso_now()
        manifest['adopted_existing'] = True
        if TAK_MAP_OTS_CONFIG_FILE.exists():
            _i589_record_file(manifest, TAK_MAP_OTS_CONFIG_FILE, 'connection-configuration', 'adopted-existing')
        for path, kind in (
            (TAK_MAP_OTS_TRUST_DIR, 'ots-trust'),
            (globals().get('_I529_CREDENTIAL_ROOT', DATA_DIR / 'ots_user_credentials'), 'per-user-certificates'),
            (globals().get('_I568_SNAPSHOT_ROOT', DATA_DIR / 'data_sync_snapshots_i568'), 'data-sync-snapshots'),
            (globals().get('_I572_MISSION_SECRET_ROOT', DATA_DIR / 'mission_unlock_users_i572'), 'mission-unlock-secrets'),
            (globals().get('_I575_MISSION_SECRET_ROOT', DATA_DIR / 'mission_unlock_users_i575'), 'mission-unlock-secrets'),
            (globals().get('_I584_PARITY_HF2_ROOT', DATA_DIR / 'data_sync_transport_authority_i584_hf2'), 'data-sync-transport-authority'),
        ):
            if _i589_path_within(path, DATA_DIR):
                _i589_record_tree(manifest, path, kind, 'adopted-existing')
        for path, kind in (
            (globals().get('_I529_MASTER_SECRET_FILE', DATA_DIR / 'ots_user_credentials.master'), 'per-user-key-master-secret'),
            (globals().get('_I563_FENCE_FILE', DATA_DIR / 'data_sync_deleted_uid_fences_i563.json'), 'data-sync-delete-fences'),
        ):
            if Path(path).exists() and _i589_path_within(path, DATA_DIR):
                _i589_record_file(manifest, path, kind, 'adopted-existing')
        credential_root = Path(globals().get('_I529_CREDENTIAL_ROOT', DATA_DIR / 'ots_user_credentials'))
        if credential_root.is_dir():
            for meta_path in credential_root.glob('*/metadata.json'):
                meta = load_json_file(meta_path, {})
                cert_path = meta_path.parent / 'client-cert.pem'
                rec = _i589_remote_cert_from_meta(meta, cert_path)
                if rec.get('certificate_cn') or rec.get('client_uid'):
                    manifest['remote_certificates'] = _i589_unique_append(
                        manifest.get('remote_certificates'), rec, ('certificate_cn', 'client_uid'))
        if origin:
            manifest['state_entries'] = _i589_unique_append(manifest.get('state_entries'), {
                'file': str(TAK_MAP_USER_IDENTITIES_FILE),
                'kind': 'ots-user-identities-for-origin',
                'origin': origin,
                'removable': True,
            }, ('file', 'kind', 'origin'))
        return _i589_manifest_write(manifest)

    _i589_default_ots_before = _i509_default_ots_config
    def _i509_default_ots_config():
        cfg = dict(_i589_default_ots_before())
        cfg.update({
            'version': _I589_VERSION,
            'data_sync_enabled': True,
            'automatic_user_certificate_enrollment': True,
            'automatic_trust_installation': True,
            'progressive_endpoint_discovery': True,
            'advanced_overrides': {},
            'unenrolled_at': '',
        })
        return cfg
    globals()['_i509_default_ots_config'] = _i509_default_ots_config

    _i589_normalize_ots_before = _i509_normalize_ots_config
    def _i509_normalize_ots_config(payload=None, current=None):
        cfg = dict(_i589_normalize_ots_before(payload, current))
        source = payload if isinstance(payload, dict) else {}
        prior = current if isinstance(current, dict) else {}
        cfg['version'] = _I589_VERSION
        for key, default in (
            ('data_sync_enabled', True),
            ('automatic_user_certificate_enrollment', True),
            ('automatic_trust_installation', True),
            ('progressive_endpoint_discovery', True),
        ):
            value = source.get(key, prior.get(key, cfg.get(key, default)))
            cfg[key] = _i589_bool(value, default)
        overrides = source.get('advanced_overrides', prior.get('advanced_overrides', cfg.get('advanced_overrides', {})))
        cfg['advanced_overrides'] = dict(overrides) if isinstance(overrides, dict) else {}
        cfg['unenrolled_at'] = _i589_text(source.get('unenrolled_at', prior.get('unenrolled_at', cfg.get('unenrolled_at'))))
        return cfg
    globals()['_i509_normalize_ots_config'] = _i509_normalize_ots_config

    _i589_public_ots_before = _i509_public_ots_config
    def _i509_public_ots_config(cfg=None):
        out = dict(_i589_public_ots_before(cfg))
        manifest = _i589_manifest_load(adopt=False)
        out['version'] = _I589_VERSION
        out['data_sync_enabled'] = _i589_bool(out.get('data_sync_enabled'), True)
        out['automatic_user_certificate_enrollment'] = _i589_bool(out.get('automatic_user_certificate_enrollment'), True)
        out['automatic_trust_installation'] = _i589_bool(out.get('automatic_trust_installation'), True)
        out['progressive_endpoint_discovery'] = True
        out['enrollment_manifest'] = {
            'present': _I589_ENROLLMENT_MANIFEST_FILE.is_file(),
            'status': manifest.get('status', 'not-enrolled'),
            'origin': manifest.get('origin', ''),
            'file_count': len(manifest.get('files') or []),
            'managed_tree_count': len(manifest.get('managed_trees') or []),
            'remote_certificate_count': len(manifest.get('remote_certificates') or []),
        }
        return out
    globals()['_i509_public_ots_config'] = _i509_public_ots_config

    def _i589_standard_config(payload=None):
        payload = dict(payload or {})
        current = _i509_load_ots_config()
        raw = _i589_text(payload.get('server_address') or payload.get('base_url') or current.get('base_url'))
        if not raw:
            raise ValueError('Enter the OpenTAKServer address.')
        base = _i509_origin(raw)
        parsed = urlparse(base)
        host = parsed.hostname or ''
        overrides = dict(payload.get('advanced_overrides') or {})
        for key in ('api_url', 'marti_url', 'enrollment_url', 'cot_host', 'cot_port', 'truststore_path', 'ca_cert_path'):
            if key in payload and payload.get(key) not in (None, ''):
                overrides[key] = payload.get(key)
        candidate = {
            'display_name': payload.get('display_name') or current.get('display_name') or 'OpenTAKServer',
            'base_url': base,
            'api_url': overrides.get('api_url') or base,
            'marti_url': overrides.get('marti_url') or ('https://' + host + ':8443'),
            'enrollment_url': overrides.get('enrollment_url') or ('https://' + host + ':8446'),
            'cot_host': overrides.get('cot_host') or host,
            'cot_port': overrides.get('cot_port') or 8089,
            'truststore_path': overrides.get('truststore_path') or '/api/truststore',
            'ca_cert_path': overrides.get('ca_cert_path') or current.get('ca_cert_path') or '',
            'verify_tls': True,
            'enabled': _i589_bool(payload.get('enabled'), True),
            'login_enabled': _i589_bool(payload.get('login_enabled'), True),
            'data_sync_enabled': _i589_bool(payload.get('data_sync_enabled'), True),
            'automatic_user_certificate_enrollment': _i589_bool(payload.get('automatic_user_certificate_enrollment'), True),
            'automatic_trust_installation': _i589_bool(payload.get('automatic_trust_installation'), True),
            'progressive_endpoint_discovery': True,
            'advanced_overrides': overrides,
        }
        cfg = _i509_normalize_ots_config(candidate, current)
        cfg['entered_base_url'] = base
        cfg['entered_host'] = host
        return _i589_adopt_canonical_certificate_host(cfg)

    def _i589_is_ip_literal(host):
        try:
            ipaddress.ip_address(_i589_text(host).strip('[]'))
            return True
        except Exception:
            return False

    def _i589_normalized_ip(value):
        try:
            return ipaddress.ip_address(_i589_text(value).strip('[]')).compressed
        except Exception:
            return ''

    def _i589_resolve_addresses(host):
        host = _i589_text(host).strip('[]').rstrip('.')
        if not host:
            return []
        literal = _i589_normalized_ip(host)
        if literal:
            return [literal]
        out = []
        try:
            for row in socket.getaddrinfo(host, None, type=socket.SOCK_STREAM):
                ip = _i589_normalized_ip((row[4] or ('',))[0])
                if ip and ip not in out:
                    out.append(ip)
        except Exception:
            pass
        return out

    def _i589_url_host(host):
        host = _i589_text(host).strip('[]')
        return '[' + host + ']' if ':' in host else host

    def _i589_unverified_certificate(host, port=443):
        result = {'ok': False, 'host': _i589_text(host), 'port': int(port), 'subject': {}, 'issuer': {}, 'sans': [], 'dns_names': [], 'ip_addresses': [], 'error': ''}
        if not host:
            result['error'] = 'No host configured.'
            return result
        try:
            ctx = ssl._create_unverified_context()
            with socket.create_connection((_i589_text(host).strip('[]'), int(port)), timeout=8) as raw:
                with ctx.wrap_socket(raw, server_hostname=_i589_text(host).strip('[]')) as tls:
                    der = tls.getpeercert(binary_form=True)
                    result['tls_version'] = tls.version() or ''
                    result['cipher'] = (tls.cipher() or ('', '', ''))[0]
            pem = ssl.DER_cert_to_PEM_cert(der)
            decoded = _i509_decode_pem_cert(pem)
            result['subject'] = {k: v for group in decoded.get('subject', []) for k, v in group}
            result['issuer'] = {k: v for group in decoded.get('issuer', []) for k, v in group}
            result['sans'] = [{'type': str(k), 'value': str(v)} for k, v in decoded.get('subjectAltName', [])]
            for kind, value in decoded.get('subjectAltName', []):
                if str(kind).lower() == 'dns':
                    name = _i589_text(value).lower().rstrip('.')
                    if name and name not in result['dns_names']:
                        result['dns_names'].append(name)
                elif str(kind).lower() in ('ip address', 'ip'):
                    value = _i589_normalized_ip(value)
                    if value and value not in result['ip_addresses']:
                        result['ip_addresses'].append(value)
            if not result['dns_names']:
                cn = _i589_text(result['subject'].get('commonName')).lower().rstrip('.')
                if cn:
                    result['dns_names'].append(cn)
            result['not_before'] = _i589_text(decoded.get('notBefore'))
            result['not_after'] = _i589_text(decoded.get('notAfter'))
            result['ok'] = True
        except Exception as exc:
            result['error'] = str(exc)
        return result

    def _i589_same_resolved_server(left, right):
        left = _i589_text(left).strip('[]').lower().rstrip('.')
        right = _i589_text(right).strip('[]').lower().rstrip('.')
        if not left or not right:
            return False
        if left == right:
            return True
        return bool(set(_i589_resolve_addresses(left)) & set(_i589_resolve_addresses(right)))

    def _i589_adopt_canonical_certificate_host(cfg):
        cfg = dict(cfg or {})
        base = _i589_text(cfg.get('base_url')).rstrip('/')
        parsed = urlparse(base)
        entered_host = parsed.hostname or _i589_text(cfg.get('cot_host'))
        entered_port = parsed.port or (443 if parsed.scheme == 'https' else 80)
        metadata = {
            'entered_base_url': _i589_text(cfg.get('entered_base_url') or base),
            'entered_host': _i589_text(cfg.get('entered_host') or entered_host),
            'canonical_host': entered_host,
            'adopted_certificate_hostname': False,
            'certificate': {},
            'resolved_addresses': _i589_resolve_addresses(entered_host),
        }
        if parsed.scheme != 'https' or not entered_host:
            cfg['canonical_discovery'] = metadata
            return cfg
        cert = _i589_unverified_certificate(entered_host, entered_port)
        metadata['certificate'] = cert
        canonical = entered_host
        # Prefer the user-supplied host when it already appears in the certificate.
        supplied_match = False
        if _i589_is_ip_literal(entered_host):
            supplied_match = _i589_normalized_ip(entered_host) in set(cert.get('ip_addresses') or [])
        else:
            supplied_match = entered_host.lower().rstrip('.') in set(cert.get('dns_names') or [])
        if cert.get('ok') and not supplied_match:
            for candidate in cert.get('dns_names') or []:
                if candidate.startswith('*.'):
                    continue
                if _i589_same_resolved_server(entered_host, candidate):
                    canonical = candidate
                    metadata['adopted_certificate_hostname'] = True
                    break
        metadata['canonical_host'] = canonical
        metadata['canonical_addresses'] = _i589_resolve_addresses(canonical)
        overrides = dict(cfg.get('advanced_overrides') or {})
        if canonical and canonical != entered_host:
            canonical_origin = f'{parsed.scheme}://{_i589_url_host(canonical)}' + ((':' + str(parsed.port)) if parsed.port else '')
            cfg['base_url'] = canonical_origin
            if not overrides.get('api_url'):
                cfg['api_url'] = canonical_origin
            if not overrides.get('marti_url'):
                cfg['marti_url'] = 'https://' + _i589_url_host(canonical) + ':8443'
            if not overrides.get('enrollment_url'):
                cfg['enrollment_url'] = 'https://' + _i589_url_host(canonical) + ':8446'
            if not overrides.get('cot_host'):
                cfg['cot_host'] = canonical
        cfg['canonical_discovery'] = metadata
        return cfg

    def _i589_http_probe(url, method='GET', headers=None, data=None, timeout=8, unverified=True, cfg=None):
        result = {'url': url, 'final_url': url, 'method': method, 'status': 0, 'reachable': False, 'ok': False, 'tls_verified': False, 'error': '', 'body_preview': ''}
        try:
            req = Request(url, data=data, headers={'Accept': '*/*', 'User-Agent': 'TAK-Map/i589 ConfigureOTS', **(headers or {})}, method=method)
            ctx = ssl._create_unverified_context() if unverified else _i509_ssl_context(cfg or {})
            with urlopen(req, timeout=timeout, context=ctx) as resp:
                body = resp.read(2 * 1024 * 1024)
                result.update({'status': int(getattr(resp, 'status', 200) or 200), 'reachable': True, 'tls_verified': not unverified, 'body': body, 'headers': dict(resp.headers.items()), 'final_url': getattr(resp, 'geturl', lambda: url)()})
        except HTTPError as exc:
            try:
                body = exc.read(262144)
            except Exception:
                body = b''
            result.update({'status': int(getattr(exc, 'code', 0) or 0), 'reachable': True, 'tls_verified': not unverified, 'body': body, 'headers': dict(exc.headers.items()) if exc.headers else {}, 'error': 'HTTP ' + str(getattr(exc, 'code', '')), 'final_url': getattr(exc, 'geturl', lambda: url)()})
        except Exception as exc:
            result['error'] = str(exc)
            result['body'] = b''
        result['ok'] = 200 <= int(result.get('status') or 0) < 300
        try:
            result['body_preview'] = bytes(result.get('body') or b'').decode('utf-8', 'replace')[:1200]
        except Exception:
            result['body_preview'] = ''
        return result

    def _i589_marti_probe_ok(probe):
        status = int((probe or {}).get('status') or 0)
        body = _i589_text((probe or {}).get('body_preview')).lower()
        if 200 <= status < 400 or status in (401, 403, 405):
            return True
        return status == 400 and any(token in body for token in ('required ssl certificate', 'client certificate', 'no required ssl certificate was sent', 'bad certificate'))

    def _i589_enrollment_probe_ok(options_probe, get_probe):
        for probe in (options_probe, get_probe):
            status = int((probe or {}).get('status') or 0)
            headers = {str(k).lower(): str(v) for k, v in ((probe or {}).get('headers') or {}).items()}
            allow = headers.get('allow', '').lower()
            if 200 <= status < 400 or status in (401, 403):
                return True
            if status == 405 and ('post' in allow or 'options' in allow):
                return True
        return False

    def _i589_standard_endpoint_checks(cfg, strict=False):
        cfg = _i589_adopt_canonical_certificate_host(cfg)
        base = cfg['base_url'].rstrip('/')
        marti = cfg['marti_url'].rstrip('/')
        enroll = cfg['enrollment_url'].rstrip('/')
        trust_url = base + cfg.get('truststore_path', '/api/truststore')
        enroll_path = '/Marti/api/tls/signClient/v2?clientUid=TAKMAP-DISCOVERY&version=5.2.0'
        probes = {
            'web': _i589_http_probe(base + '/', unverified=not strict, cfg=cfg),
            'truststore': _i589_http_probe(trust_url, unverified=not strict, cfg=cfg),
            'marti': _i589_http_probe(marti + '/Marti/api/version/config', unverified=not strict, cfg=cfg),
            'enrollment_options': _i589_http_probe(enroll + enroll_path, method='OPTIONS', unverified=not strict, cfg=cfg),
            'enrollment_get': _i589_http_probe(enroll + enroll_path, method='GET', unverified=not strict, cfg=cfg),
        }
        web_status = int(probes['web'].get('status') or 0)
        web_ok = bool(probes['web'].get('reachable') and (200 <= web_status < 400 or web_status in (401, 403)))
        trust_headers = {str(k).lower(): str(v).lower() for k, v in (probes['truststore'].get('headers') or {}).items()}
        trust_type = trust_headers.get('content-type', '')
        trust_ok = bool(probes['truststore'].get('ok') and probes['truststore'].get('body') and any(token in trust_type for token in ('pkcs12', 'p12', 'octet-stream', 'pem', 'x-x509', 'zip', 'certificate')))
        marti_ok = _i589_marti_probe_ok(probes['marti'])
        enrollment_ok = _i589_enrollment_probe_ok(probes['enrollment_options'], probes['enrollment_get'])
        web_parsed = urlparse(base)
        web_cert = _i509_cert_probe(web_parsed.hostname, web_parsed.port or 443, cfg)
        cot = _i509_cert_probe(cfg.get('cot_host'), cfg.get('cot_port'), cfg if strict else {**cfg, 'verify_tls': False})
        cot_ok = bool(cot.get('ok'))
        if strict:
            web_ok = web_ok and bool(web_cert.get('strict_tls_ok')) and bool(web_cert.get('hostname_match'))
            trust_ok = trust_ok and bool(probes['truststore'].get('tls_verified'))
            marti_ok = marti_ok and bool(probes['marti'].get('tls_verified'))
            enrollment_ok = enrollment_ok and bool(probes['enrollment_options'].get('tls_verified') or probes['enrollment_get'].get('tls_verified'))
            cot_ok = cot_ok and bool(cot.get('strict_tls_ok')) and bool(cot.get('hostname_match'))
        checks = {'web': web_ok, 'truststore': trust_ok, 'marti': marti_ok, 'enrollment': enrollment_ok, 'cot': cot_ok}
        required = []
        if not web_ok:
            required.append('base_url')
        if not trust_ok:
            overrides = dict(cfg.get('advanced_overrides') or {})
            required.append('ca_cert_path' if overrides.get('truststore_path') else 'truststore_path')
        if not marti_ok:
            required.append('marti_url')
        if not enrollment_ok:
            required.append('enrollment_url')
        if not cot_ok:
            required.extend(['cot_host', 'cot_port'])
        return {
            'version': _I589_VERSION,
            'strict': bool(strict),
            'config': _i509_public_ots_config(cfg),
            'canonical_discovery': cfg.get('canonical_discovery') or {},
            'checks': checks,
            'probes': probes,
            'web_certificate': web_cert,
            'cot': cot,
            'required_fields': list(dict.fromkeys(required)),
            'semantic_acceptance': {
                'marti_missing_client_certificate_is_available': True,
                'enrollment_method_not_allowed_with_post_advertised_is_available': True,
                'cot_tls_handshake_is_available': True,
            },
        }

    def _i589_extract_trust_certificates(body, password=''):
        certs = []
        p12_blobs = []
        text = bytes(body or b'').decode('utf-8', 'ignore')
        certs.extend(re.findall(r'-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', text, re.S))
        if not certs and bytes(body or b'')[:2] == b'PK':
            try:
                with zipfile.ZipFile(io.BytesIO(body)) as archive:
                    for name in archive.namelist():
                        lower = name.lower()
                        raw = archive.read(name)
                        if lower.endswith(('.crt', '.cer', '.pem')):
                            certs.extend(re.findall(r'-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----', raw.decode('utf-8', 'ignore'), re.S))
                        elif lower.endswith(('.p12', '.pfx')):
                            p12_blobs.append(raw)
            except Exception:
                pass
        if not certs and not p12_blobs:
            p12_blobs.append(bytes(body or b''))
        passwords = [password] if password else ['']
        for blob in p12_blobs:
            if certs:
                break
            certs.extend(_i509_pkcs12_certificates(blob, passwords))
        unique = []
        seen = set()
        for pem in certs:
            normalized = pem.strip() + '\n'
            fingerprint = hashlib.sha256(normalized.encode('utf-8')).hexdigest()
            if fingerprint not in seen:
                seen.add(fingerprint)
                unique.append(normalized)
        return unique

    def _i589_install_trust(cfg, payload=None, manifest=None):
        payload = dict(payload or {})
        manifest = dict(manifest or _i589_manifest_load())
        password = _i589_text(payload.get('truststore_password'))
        supplied_ca = _i589_text(payload.get('ca_cert_path') or (payload.get('advanced_overrides') or {}).get('ca_cert_path'))
        body = b''
        source = ''
        if supplied_ca:
            path = Path(supplied_ca).expanduser()
            if not path.is_file():
                return {'ok': False, 'needs_input': True, 'required_fields': ['ca_cert_path'], 'error': 'The supplied CA certificate path is not readable.'}
            body = path.read_bytes()
            source = str(path)
        else:
            url = cfg['base_url'].rstrip('/') + cfg.get('truststore_path', '/api/truststore')
            probe = _i589_http_probe(url, unverified=True, timeout=12)
            if not probe.get('ok'):
                return {'ok': False, 'needs_input': True, 'required_fields': ['truststore_path', 'ca_cert_path'], 'error': 'The standard OpenTAKServer truststore endpoint did not return a downloadable trust bundle.', 'probe': {k: v for k, v in probe.items() if k != 'body'}}
            body = probe.get('body') or b''
            source = url
        certs = _i589_extract_trust_certificates(body, password)
        if not certs:
            fields = ['truststore_password'] if not supplied_ca and not password else (['ca_cert_path'] if not supplied_ca else ['truststore_password'])
            return {'ok': False, 'needs_input': True, 'required_fields': fields, 'error': 'The trust bundle was downloaded but its CA certificates could not be extracted. Enter the truststore password or provide a PEM CA certificate path. No password was assumed.'}
        TAK_MAP_OTS_TRUST_DIR.mkdir(parents=True, exist_ok=True)
        try:
            os.chmod(TAK_MAP_OTS_TRUST_DIR, 0o700)
        except Exception:
            pass
        path = TAK_MAP_OTS_TRUST_DIR / 'opentakserver-ca-chain.crt'
        tmp = path.with_suffix('.tmp')
        tmp.write_text(''.join(certs), encoding='utf-8')
        os.chmod(tmp, 0o640)
        tmp.replace(path)
        cfg = dict(cfg)
        cfg['ca_cert_path'] = str(path)
        manifest = _i589_record_tree(manifest, TAK_MAP_OTS_TRUST_DIR, 'ots-trust')
        manifest = _i589_record_file(manifest, path, 'ots-ca-chain')
        identities = []
        for pem in certs:
            decoded = _i509_decode_pem_cert(pem)
            identities.append({
                'subject': {k: v for group in decoded.get('subject', []) for k, v in group},
                'issuer': {k: v for group in decoded.get('issuer', []) for k, v in group},
                'not_before': _i589_text(decoded.get('notBefore')),
                'not_after': _i589_text(decoded.get('notAfter')),
                'sha256': hashlib.sha256(pem.encode('utf-8')).hexdigest(),
            })
        return {'ok': True, 'cfg': cfg, 'manifest': manifest, 'path': str(path), 'certificates': len(certs), 'source': source, 'certificate_identities': identities}

    def _i589_progressive_failure(error, required_fields, cfg=None, discovery=None, extra=None):
        out = {
            'ok': False,
            'version': _I589_VERSION,
            'needs_input': True,
            'error': _i589_text(error),
            'required_fields': list(dict.fromkeys(required_fields or [])),
            'config': _i509_public_ots_config(cfg or _i509_load_ots_config()),
        }
        if discovery is not None:
            out['discovery'] = discovery
        if isinstance(extra, dict):
            out.update(extra)
        return out

    def _i589_decode_opaque_transport(payload):
        """Translate the browser's positional opaque transport into internal names.

        Configure OTS never exposes semantic credential field names in HTML name/id
        attributes or JSON request keys. Internal semantic names exist only after
        this API-boundary translation.
        """
        source = dict(payload or {}) if isinstance(payload, dict) else {}
        values = source.get('q')
        if not isinstance(values, list):
            return source
        keys = (
            'server_address', 'username', 'password', 'otp',
            'enabled', 'login_enabled', 'data_sync_enabled',
            'automatic_user_certificate_enrollment',
            'automatic_trust_installation', 'api_url', 'marti_url',
            'enrollment_url', 'cot_host', 'cot_port', 'truststore_path',
            'truststore_password', 'ca_cert_path', 'confirmation',
        )
        decoded = {}
        for index, key in enumerate(keys):
            if index < len(values):
                decoded[key] = values[index]
        return decoded

    def _i589_enroll_server(payload):
        payload = _i589_decode_opaque_transport(payload)
        cfg = _i589_standard_config(payload)
        username = sanitize_ots_username(payload.get('username') or '')
        password = str(payload.get('password') or '')
        otp = _i589_text(payload.get('otp'))
        if not username:
            return _i589_progressive_failure('Enter the OpenTAKServer administrator username.', ['username'], cfg)
        if not password:
            return _i589_progressive_failure('Enter the OpenTAKServer administrator password.', ['password'], cfg)
        initial = _i589_standard_endpoint_checks(cfg, strict=False)
        if initial['required_fields']:
            return _i589_progressive_failure('TAK Map could not identify one or more OpenTAKServer services using discovered values or standard defaults. Enter only the highlighted override values.', initial['required_fields'], cfg, initial)
        manifest = _i589_manifest_load()
        manifest['origin'] = cfg['base_url'].rstrip('/')
        manifest['created_at'] = manifest.get('created_at') or _i589_iso_now()
        manifest['status'] = 'enrolling'
        if cfg.get('automatic_trust_installation'):
            trust = _i589_install_trust(cfg, payload, manifest)
            if not trust.get('ok'):
                return _i589_progressive_failure(trust.get('error'), trust.get('required_fields'), cfg, initial, {'trust': trust})
            cfg = _i589_adopt_canonical_certificate_host(trust['cfg'])
            manifest = trust['manifest']
        elif not (cfg.get('ca_cert_path') and Path(cfg.get('ca_cert_path')).expanduser().is_file()):
            return _i589_progressive_failure('Strict TLS requires a readable CA certificate path.', ['ca_cert_path'], cfg, initial)
        strict = _i589_standard_endpoint_checks(cfg, strict=True)
        if strict['required_fields']:
            return _i589_progressive_failure('OpenTAKServer services were found, but strict trusted validation still needs only the highlighted value or values.', strict['required_fields'], cfg, strict)
        auth = _i509_authenticate_remote(cfg, username, password, otp)
        if not auth.get('ok'):
            auth_text = ' '.join([
                _i589_text(auth.get('error')),
                _i589_text(auth.get('message')),
                json.dumps(auth.get('attempts') or [], default=str),
            ]).lower()
            otp_required = bool(
                auth.get('otp_required') or auth.get('requires_otp') or auth.get('mfa_required') or
                any(token in auth_text for token in ('two-factor', '2fa', 'totp', 'one-time code', 'one time code', 'otp required', 'mfa required'))
            )
            required = ['otp'] if otp_required else ['username', 'password']
            message = auth.get('error') or 'OpenTAKServer administrator authentication failed.'
            message += ' Enter the current 2FA code.' if otp_required else ' Verify the administrator username and password.'
            return _i589_progressive_failure(message, required, cfg, strict, {'auth_attempts': auth.get('attempts', []), 'otp_required': otp_required})
        fetched = _i511_fetch_profile(cfg, auth, username)
        if not fetched.get('ok'):
            return _i589_progressive_failure('Authentication succeeded, but TAK Map could not read the administrator profile: ' + _i589_text(fetched.get('error')), ['api_url'], cfg, strict)
        profile = dict(fetched.get('profile') or {})
        if not profile.get('is_admin'):
            return _i589_progressive_failure('The account authenticated successfully but does not have the OpenTAKServer administrator role.', ['username', 'password'], cfg, strict)
        validation = {
            'username': profile.get('username', ''),
            'display_identity': profile.get('display_identity', ''),
            'base_url': cfg['base_url'].rstrip('/'),
            'validated_at': _i589_iso_now(),
            'role_names': list(profile.get('role_names') or []),
        }
        current = _i509_load_ots_config()
        staged = _i509_normalize_ots_config(current, current)
        staged['last_admin_validation'] = validation
        _i511_write_ots_config(staged)
        cfg['last_admin_validation'] = validation
        saved = _i509_save_ots_config(cfg)
        manifest['status'] = 'enrolled'
        manifest['origin'] = saved.get('base_url', '').rstrip('/')
        manifest['disconnected_at'] = ''
        manifest['capabilities'] = {
            'remote_revocation': 'discover-on-unenroll',
            'standard_endpoint_discovery': True,
            'protocol_aware_endpoint_classification': True,
            'certificate_hostname_discovery': True,
            'automatic_trust': bool(saved.get('automatic_trust_installation')),
            'automatic_user_certificate_enrollment': bool(saved.get('automatic_user_certificate_enrollment')),
        }
        _i589_record_file(manifest, TAK_MAP_OTS_CONFIG_FILE, 'connection-configuration')
        manifest = _i589_manifest_write(manifest)
        try:
            final_discovery = _i509_discover_ots(saved)
        except Exception as exc:
            final_discovery = {'ok': True, 'version': _I589_VERSION, 'summary': strict.get('checks'), 'error': str(exc)}
        final_discovery['configure_ots_i589'] = strict
        return {
            'ok': True,
            'version': _I589_VERSION,
            'message': 'OpenTAKServer enrollment completed. OTS login, Mission Data Sync, trust, and automatic per-user certificate enrollment are ready.',
            'status_label': 'Connected',
            'config': _i509_public_ots_config(saved),
            'discovery': final_discovery,
            'administrator': {k: profile.get(k) for k in ('username', 'display_identity', 'role_names')},
            'manifest': {'path': str(_I589_ENROLLMENT_MANIFEST_FILE), 'status': manifest.get('status'), 'file_count': len(manifest.get('files') or []), 'managed_tree_count': len(manifest.get('managed_trees') or [])},
            'password_persisted': False,
            'otp_persisted': False,
            'standard_endpoints_used': not bool(saved.get('advanced_overrides')),
            'entered_address': _i589_text((cfg.get('canonical_discovery') or {}).get('entered_base_url')),
            'canonical_address': saved.get('base_url', ''),
            'certificate_hostname_adopted': bool((cfg.get('canonical_discovery') or {}).get('adopted_certificate_hostname')),
        }

    # Ensure the older truststore endpoint follows the same no-assumed-password rule.
    def _i509_install_truststore(payload):
        cfg = _i589_standard_config(payload or {})
        result = _i589_install_trust(cfg, payload or {}, _i589_manifest_load())
        if not result.get('ok'):
            raise ValueError(result.get('error') or 'OpenTAKServer trust installation failed.')
        saved = _i509_save_ots_config(result['cfg']) if _i509_load_ots_config().get('last_admin_validation') else result['cfg']
        _i589_manifest_write(result['manifest'])
        return {
            'ok': True,
            'version': _I589_VERSION,
            'path': result['path'],
            'certificates': result['certificates'],
            'certificate_identities': result['certificate_identities'],
            'config': _i509_public_ots_config(saved),
            'message': 'OpenTAKServer public CA chain installed without assuming a truststore password.',
        }
    globals()['_i509_install_truststore'] = _i509_install_truststore

    if '_i529_ensure_user_certificate' in globals():
        _i589_ensure_user_cert_before = _i529_ensure_user_certificate
        def _i529_ensure_user_certificate(cfg, username, password, client_uid, force=False):
            result = _i589_ensure_user_cert_before(cfg, username, password, client_uid, force)
            if isinstance(result, dict) and result.get('ok'):
                try:
                    manifest = _i589_manifest_load()
                    paths = _i529_paths(username)
                    manifest = _i589_record_tree(manifest, paths['root'], 'per-user-certificate')
                    for key, kind in (('key', 'private-key'), ('csr', 'certificate-request'), ('cert', 'client-certificate'), ('ca', 'ca-chain'), ('meta', 'certificate-metadata')):
                        manifest = _i589_record_file(manifest, paths[key], kind)
                    master = globals().get('_I529_MASTER_SECRET_FILE')
                    if master:
                        manifest = _i589_record_file(manifest, master, 'per-user-key-master-secret')
                    meta = load_json_file(paths['meta'], {})
                    rec = _i589_remote_cert_from_meta(meta, paths['cert'])
                    manifest['remote_certificates'] = _i589_unique_append(manifest.get('remote_certificates'), rec, ('certificate_cn', 'client_uid'))
                    _i589_manifest_write(manifest)
                except Exception:
                    pass
            return result
        globals()['_i529_ensure_user_certificate'] = _i529_ensure_user_certificate

    _i589_disconnect_before = _i512_disconnect_ots
    def _i512_disconnect_ots():
        result = _i589_disconnect_before()
        try:
            manifest = _i589_manifest_load()
            manifest['status'] = 'disconnected'
            manifest['disconnected_at'] = _i589_iso_now()
            _i589_manifest_write(manifest)
        except Exception:
            pass
        if isinstance(result, dict):
            result = dict(result)
            result['version'] = _I589_VERSION
            result['helper_text'] = 'Disabled OTS login but keeps connection details.'
        return result
    globals()['_i512_disconnect_ots'] = _i512_disconnect_ots

    def _i589_auth_headers_for_admin(cfg, username, password, otp=''):
        if not username or not password:
            return {}, {'ok': False, 'error': 'Administrator credentials were not supplied.'}
        auth = _i509_authenticate_remote(cfg, username, password, otp)
        if not auth.get('ok'):
            return {}, auth
        return _i511_auth_headers(cfg, auth), auth

    def _i589_openapi_paths(cfg, headers):
        base = cfg.get('api_url') or cfg.get('base_url') or ''
        for path in ('/openapi.json', '/api/openapi.json', '/api/docs/openapi.json'):
            try:
                req = Request(base.rstrip('/') + path, headers={**headers, 'Accept': 'application/json'}, method='GET')
                with urlopen(req, timeout=8, context=_i509_ssl_context(cfg)) as resp:
                    obj = json.loads(resp.read(2 * 1024 * 1024).decode('utf-8', 'replace'))
                paths = obj.get('paths') if isinstance(obj, dict) else None
                if isinstance(paths, dict):
                    return paths
            except Exception:
                continue
        return {}

    def _i589_attempt_remote_revocation(cfg, manifest, username='', password='', otp=''):
        certs = list(manifest.get('remote_certificates') or [])
        if not certs:
            return {'attempted': False, 'supported': False, 'revoked': [], 'outstanding': [], 'message': 'No TAK Map-created remote certificates were recorded.'}
        headers, auth = _i589_auth_headers_for_admin(cfg, username, password, otp)
        if not auth.get('ok'):
            return {'attempted': False, 'supported': None, 'revoked': [], 'outstanding': certs, 'message': 'Remote certificate cleanup was not attempted because administrator credentials were unavailable or rejected.'}
        paths = _i589_openapi_paths(cfg, headers)
        candidates = []
        for path, methods in paths.items():
            lower = str(path).lower()
            if 'cert' not in lower or 'revok' not in lower or not isinstance(methods, dict):
                continue
            for method in ('post', 'delete'):
                if method in methods:
                    candidates.append((str(path), method.upper()))
        if not candidates:
            return {'attempted': False, 'supported': False, 'revoked': [], 'outstanding': certs, 'message': 'OpenTAKServer did not advertise a supported certificate-revocation API. Local unenrollment will continue.'}
        endpoint, method = candidates[0]
        revoked = []
        outstanding = []
        base = (cfg.get('api_url') or cfg.get('base_url') or '').rstrip('/')
        for cert in certs:
            path = endpoint
            replacements = {
                '{id}': cert.get('client_uid') or cert.get('certificate_cn') or cert.get('serial_number'),
                '{uid}': cert.get('client_uid'),
                '{serial}': cert.get('serial_number'),
                '{cn}': cert.get('certificate_cn'),
                '{username}': cert.get('username'),
            }
            for token, value in replacements.items():
                if token in path:
                    path = path.replace(token, quote(_i589_text(value), safe=''))
            body = json.dumps({
                'username': cert.get('username'),
                'client_uid': cert.get('client_uid'),
                'certificate_cn': cert.get('certificate_cn'),
                'serial_number': cert.get('serial_number'),
            }).encode('utf-8')
            try:
                req = Request(base + path, data=body, headers={**headers, 'Content-Type': 'application/json'}, method=method)
                with urlopen(req, timeout=12, context=_i509_ssl_context(cfg)) as resp:
                    status = int(getattr(resp, 'status', 200) or 200)
                if 200 <= status < 300:
                    revoked.append(cert)
                else:
                    outstanding.append({**cert, 'error': 'HTTP ' + str(status)})
            except Exception as exc:
                outstanding.append({**cert, 'error': str(exc)})
        return {'attempted': True, 'supported': True, 'endpoint': endpoint, 'method': method, 'revoked': revoked, 'outstanding': outstanding, 'message': 'Remote certificate revocation completed.' if not outstanding else 'Remote certificate revocation completed with outstanding certificates.'}

    def _i589_remove_ots_identity_entries(origin):
        result = {'removed': 0, 'preserved': 0}
        try:
            data = _i512_load_identities()
            identities = dict(data.get('identities') or {})
            kept = {}
            for key, row in identities.items():
                if isinstance(row, dict) and row.get('provider') == 'ots' and _i589_text(row.get('origin')).rstrip('/').lower() == _i589_text(origin).rstrip('/').lower():
                    result['removed'] += 1
                else:
                    kept[key] = row
                    result['preserved'] += 1
            data['identities'] = kept
            _i512_save_identities(data)
        except Exception as exc:
            result['error'] = str(exc)
        return result

    def _i589_remove_manifest_artifacts(manifest):
        removed = []
        skipped = []
        errors = []
        allowed_root = Path(DATA_DIR).resolve(strict=False)
        # Managed trees are removed first, but only when they are inside TAK Map's data directory.
        for record in sorted(manifest.get('managed_trees') or [], key=lambda row: len(_i589_text(row.get('path'))), reverse=True):
            path = Path(_i589_text(record.get('path'))).expanduser()
            if not record.get('removable', True) or not _i589_path_within(path, allowed_root):
                skipped.append({'path': str(path), 'reason': 'outside TAK Map managed data root or marked non-removable'})
                continue
            try:
                if path.is_symlink() or path.is_file():
                    path.unlink(missing_ok=True)
                elif path.exists():
                    shutil.rmtree(path)
                removed.append(str(path))
            except Exception as exc:
                errors.append({'path': str(path), 'error': str(exc)})
        for record in manifest.get('files') or []:
            path = Path(_i589_text(record.get('path'))).expanduser()
            if path == _I589_ENROLLMENT_MANIFEST_FILE:
                continue
            allowed = _i589_path_within(path, allowed_root) or path == TAK_MAP_OTS_CONFIG_FILE
            if not record.get('removable', True) or not allowed:
                skipped.append({'path': str(path), 'reason': 'outside TAK Map managed data root or marked non-removable'})
                continue
            try:
                if path.is_symlink() or path.is_file():
                    path.unlink(missing_ok=True)
                    removed.append(str(path))
            except Exception as exc:
                errors.append({'path': str(path), 'error': str(exc)})
        return {'removed': removed, 'skipped': skipped, 'errors': errors}

    def _i589_unenroll_server(payload):
        payload = _i589_decode_opaque_transport(payload)
        if _i589_text(payload.get('confirmation')).upper() != 'UNENROLL':
            raise ValueError('Type UNENROLL to confirm complete OpenTAKServer unenrollment.')
        if not _i512_local_admin_ready():
            raise ValueError('Change the built-in local administrator password before unenrolling OpenTAKServer.')
        cfg = _i509_load_ots_config()
        manifest = _i589_manifest_load()
        origin = manifest.get('origin') or cfg.get('base_url') or ''
        remote = _i589_attempt_remote_revocation(
            cfg,
            manifest,
            sanitize_ots_username(payload.get('username') or ''),
            str(payload.get('password') or ''),
            _i589_text(payload.get('otp')),
        )
        # Disable the connection before removing its files.
        disabled = dict(cfg)
        disabled['enabled'] = False
        disabled['login_enabled'] = False
        disabled['disconnected_at'] = _i589_iso_now()
        try:
            _i511_write_ots_config(_i509_normalize_ots_config(disabled, cfg))
        except Exception:
            pass
        try:
            if '_i532_stop_all_presence' in globals():
                _i532_stop_all_presence('ots-unenroll')
        except Exception:
            pass
        with TAK_MAP_SESSIONS_LOCK:
            for token, sess in list(TAK_MAP_SESSIONS.items()):
                if _i589_text((sess or {}).get('auth_mode')).startswith('ots-'):
                    TAK_MAP_SESSIONS.pop(token, None)
        try:
            if '_I568_STATE_LOCK' in globals() and '_I568_STATES' in globals():
                with _I568_STATE_LOCK:
                    _I568_STATES.clear()
        except Exception:
            pass
        identities = _i589_remove_ots_identity_entries(origin)
        local_cleanup = _i589_remove_manifest_artifacts(manifest)
        # Remove the active configuration and manifest last.
        try:
            TAK_MAP_OTS_CONFIG_FILE.unlink(missing_ok=True)
            if str(TAK_MAP_OTS_CONFIG_FILE) not in local_cleanup['removed']:
                local_cleanup['removed'].append(str(TAK_MAP_OTS_CONFIG_FILE))
        except Exception as exc:
            local_cleanup['errors'].append({'path': str(TAK_MAP_OTS_CONFIG_FILE), 'error': str(exc)})
        result = {
            'ok': not bool(local_cleanup.get('errors')),
            'version': _I589_VERSION,
            'message': 'OpenTAKServer enrollment was removed locally.' + (' Remote certificate cleanup remains outstanding.' if remote.get('outstanding') else ''),
            'helper_text': 'Disconnects and completely removes OTS enrollment.',
            'origin': origin,
            'remote_revocation': remote,
            'local_cleanup': local_cleanup,
            'identity_cleanup': identities,
            'preserved': ['OTS users', 'OTS groups', 'OTS Missions', 'OTS Mission contents', 'unrelated registered devices', 'map points', 'Local Data', 'basemaps', 'TAK Gateway configuration'],
            'local_login_restored': True,
            'remote_cleanup_outstanding': bool(remote.get('outstanding')),
            'completed_at': _i589_iso_now(),
        }
        try:
            atomic_write_json(_I589_LAST_UNENROLL_RESULT_FILE, result)
            os.chmod(_I589_LAST_UNENROLL_RESULT_FILE, 0o600)
        except Exception:
            pass
        try:
            _I589_ENROLLMENT_MANIFEST_FILE.unlink(missing_ok=True)
        except Exception:
            pass
        return result

