    def _i589_patch_html(html):
        html = str(html or '')
        html = re.sub(r'1\.3\.0-i\d+(?:-[A-Za-z0-9_-]+)?', '1.3.0-i589', html)
        html = re.sub(r'TAKDashboard/i\d+(?:-[A-Za-z0-9_-]+)?', 'TAKDashboard/i589', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i\d+', 'TAK-Map/1.3.0 i589', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i589\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i589\2', html)
        if 'id="takMapConfigureOtsI589"' not in html:
            html = html.replace('</body></html>', _I589_CONFIGURE_OTS_UI + '</body></html>')
        return html

