# --- TAK Map i598 Mission /cot XML response preservation and projection ---
try:
    _I598_VERSION = 'i598'
    _I598_PACKAGE_VERSION = '1.3.0-i598'

    def _i598_event_xml(value):
        if not isinstance(value, str):
            return False
        text = value.lstrip('\ufeff \t\r\n')
        return bool(text and re.search(r'<(?:[A-Za-z0-9_.-]+:)?events?\b', text, re.I))

    def _i598_empty_json(value):
        return value is None or value == {} or value == [] or value == ''

    # The Mission client can return a valid XML /cot body while also exposing an
    # empty parsed JSON object. Preserve the event-bearing body instead of
    # allowing that empty JSON value to replace it.
    _i598_parsed_result_before = _i569_parsed_result
    def _i569_parsed_result(result):
        raw_body = None
        if isinstance(result, dict):
            raw_body = result.get('raw_body') if _i598_event_xml(result.get('raw_body')) else result.get('body')
        out = _i598_parsed_result_before(result)
        parsed_json = out.get('json') if isinstance(out, dict) else None
        if _i598_event_xml(raw_body) and _i598_empty_json(parsed_json):
            out = dict(out or {})
            out['raw_body'] = raw_body
            out['body'] = raw_body
            out['cot_xml_body_i598'] = True
        return out
    globals()['_i569_parsed_result'] = _i569_parsed_result

    _i598_result_body_before = _i568_result_body
    def _i568_result_body(result):
        if isinstance(result, dict):
            parsed_json = result.get('json')
            for candidate in (result.get('raw_body'), result.get('body')):
                if _i598_event_xml(candidate) and _i598_empty_json(parsed_json):
                    return candidate
        return _i598_result_body_before(result)
    globals()['_i568_result_body'] = _i568_result_body

    # The legacy Mission projection helper walked JSON containers only. Add the
    # exact XML case returned by OTS for both a top-level <event> and an <events>
    # envelope, then pass each event through the normal marker normalizer.
    _i598_mission_objects_before = _i512_mission_api_objects
    def _i512_mission_api_objects(value, mission):
        rows = list(_i598_mission_objects_before(value, mission) or [])
        if not _i598_event_xml(value):
            return rows
        seen = set()
        for row in rows:
            if not isinstance(row, dict):
                continue
            uid = _i568_text(row.get('uid') or row.get('event_uid') or row.get('cot_uid')).casefold()
            if uid:
                seen.add(uid)
        try:
            events = _i545_extract_events(None, value)
        except Exception:
            events = {}
        for event in dict(events or {}).values():
            if not isinstance(event, dict):
                continue
            candidate = _i568_clone(event)
            candidate['mission'] = mission
            candidate['mission_name'] = mission
            candidate['source'] = 'OpenTAKServer Mission /cot XML i598'
            candidate['kind'] = 'datasync'
            try:
                marker = _normalize_tak_marker(candidate, 'mission_api', 'datasync')
            except Exception:
                marker = None
            if not isinstance(marker, dict):
                continue
            marker = _i568_clone(marker)
            marker.update({
                'mission': mission,
                'mission_name': mission,
                'source': 'OpenTAKServer Mission /cot XML i598',
                'kind': 'datasync',
                'is_mission_object': True,
                'cot_xml_projected_i598': True,
            })
            uid = _i568_text(marker.get('uid') or marker.get('event_uid') or marker.get('cot_uid')).casefold()
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            rows.append(marker)
        return rows
    globals()['_i512_mission_api_objects'] = _i512_mission_api_objects

    _i598_config_before = tak_map_config
    def tak_map_config():
        cfg = dict(_i598_config_before() or {})
        cfg['version'] = _I598_PACKAGE_VERSION
        cfg['tak_map_iteration'] = _I598_VERSION
        cfg['mission_cot_xml_i598'] = {
            'version': _I598_VERSION,
            'empty_json_does_not_hide_xml_body': True,
            'top_level_event_supported': True,
            'events_envelope_supported': True,
            'normal_mission_object_projection_used': True,
            'ui_unchanged': True,
        }
        startup = dict(cfg.get('startup_architecture_i597') or cfg.get('startup_architecture_i596') or {})
        startup.update({
            'package_version': _I598_VERSION,
            'startup_loader_cache_identity': _I598_PACKAGE_VERSION,
            'manifest_cache_identity': _I598_PACKAGE_VERSION,
            'data_sync_control_cache_identity': _I598_PACKAGE_VERSION,
        })
        cfg['startup_architecture_i598'] = startup
        return cfg
    globals()['tak_map_config'] = tak_map_config

    def _i598_patch_html(html):
        html = str(html or '')
        html = re.sub(r'1\.3\.0-i\d+(?:-[A-Za-z0-9_-]+)?', _I598_PACKAGE_VERSION, html)
        html = re.sub(r'TAKDashboard/i\d+(?:-[A-Za-z0-9_-]+)?', 'TAKDashboard/i598', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i\d+', 'TAK-Map/1.3.0 i598', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i598\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i598\2', html)
        return html

    TAK_MAP_HTML = _i598_patch_html(TAK_MAP_HTML)
    INDEX_HTML = TAK_MAP_HTML
    TAK_MAP_LOGIN_HTML = _i598_patch_html(TAK_MAP_LOGIN_HTML)
    LOGIN_HTML = TAK_MAP_LOGIN_HTML
    TAK_MAP_ITERATION = _I598_VERSION
except Exception as _i598_exc:
    try:
        print('TAK Map i598 Mission /cot XML projection patch failed:', _i598_exc)
    except Exception:
        pass
# --- end TAK Map i598 Mission /cot XML response preservation and projection ---

# --- TAK Map i599 authoritative per-Mission Data Sync acquisition and publication ---
try:
    _I599_VERSION = 'i599'
    _I599_PACKAGE_VERSION = '1.3.0-i599'
    _I599_COT_TIMEOUT_SECONDS = 10
    _I599_OVERALL_SECONDS = 32
    _I599_MAX_WORKERS = 6

    def _i599_text(value):
        try:
            return str(value if value is not None else '').strip()
        except Exception:
            return ''

    def _i599_mission_name(row):
        if isinstance(row, str):
            return _i599_text(row)
        if not isinstance(row, dict):
            return ''
        return _i599_text(row.get('mission') or row.get('mission_name') or row.get('missionName') or row.get('name'))

    def _i599_uid(row):
        if not isinstance(row, dict):
            return ''
        try:
            return _i568_text(_i555_object_uid(row) if '_i555_object_uid' in globals() else _i568_row_uid(row))
        except Exception:
            return _i599_text(row.get('event_uid') or row.get('cot_uid') or row.get('uid') or row.get('data_uid') or row.get('id'))

    def _i599_is_protected(row):
        return bool(isinstance(row, dict) and (
            row.get('passwordProtected') is True or row.get('password_protected') is True or
            row.get('protected') is True or row.get('locked_descriptor_i594') is True
        ))

    def _i599_descriptor(mission, protected=True, unlocked=False, content_state='locked', error='', sess=None):
        mission = _i599_text(mission)
        protected = bool(protected)
        unlocked = bool((not protected) or unlocked)
        state = _i599_text(content_state) or ('locked' if protected and not unlocked else 'ready')
        if state not in ('locked', 'loading', 'ready', 'error'):
            state = 'error' if error else ('locked' if protected and not unlocked else 'ready')
        resolved_sess = sess if isinstance(sess, dict) else _i572_session()
        stored = _i572_load_password(mission, resolved_sess) if mission and protected else {'ok': False}
        return {
            'ok': True,
            'version': _I599_VERSION,
            'mission': mission,
            'name': mission,
            'protected': protected,
            'password_protected': protected,
            'passwordProtected': protected,
            'locked': bool(protected and not unlocked),
            'unlocked': unlocked,
            'metadata_only': bool(protected and not unlocked),
            'locked_descriptor_i594': bool(protected and not unlocked),
            'credential_configured': bool(protected and stored.get('ok')),
            'password_stored_server_side': bool(protected and stored.get('ok')),
            'content_state_i599': state,
            'content_authoritative_i599': bool(state == 'ready'),
            'content_error_i599': _i599_text(error)[:500],
            'source': 'ots-per-mission-access-i599',
        }

    def _i599_current_access(state, sess=None):
        rows = list((state or {}).get('i599_mission_access') or []) if isinstance(state, dict) else []
        if rows:
            return _i568_clone(rows)
        snapshot = (state or {}).get('snapshot') if isinstance((state or {}).get('snapshot'), dict) else {}
        for key in ('mission_access_i599','mission_access_i596','mission_access_i594','mission_access_i591'):
            value = snapshot.get(key)
            if isinstance(value, list) and value:
                return _i568_clone(value)
        try:
            return [_i599_descriptor(
                row.get('mission'), bool(row.get('protected')), bool(row.get('unlocked')),
                'locked' if row.get('locked') else 'ready', row.get('content_error_i599') or ''
            ) for row in _i591_access_rows(state or {}, sess)]
        except Exception:
            return []

    def _i599_set_access(state, rows):
        normalized = []
        seen = set()
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            mission = _i599_mission_name(row)
            folded = mission.casefold()
            if not mission or folded in seen:
                continue
            seen.add(folded)
            item = _i568_clone(row)
            item['mission'] = mission
            item['name'] = mission
            item['version'] = _I599_VERSION
            normalized.append(item)
        normalized.sort(key=lambda item: _i599_text(item.get('mission')).casefold())
        state['i599_mission_access'] = normalized
        return normalized

    def _i599_access_map(rows):
        return {_i599_mission_name(row).casefold(): row for row in (rows or []) if isinstance(row, dict) and _i599_mission_name(row)}

    # i591's security view used to cancel the active worker by changing the
    # generation and clearing in_flight. Security filtering is now read-only with
    # respect to worker lifecycle. These helpers only record diagnostic flags.
    def _i591_mark_locked_state(state, locked_rows, sess=None):
        names = [_i599_text(row.get('mission')) for row in (locked_rows or []) if isinstance(row, dict) and _i599_text(row.get('mission'))]
        with _I568_STATE_LOCK:
            state['security_locked_i591'] = bool(names)
            state['security_locked_missions_i591'] = names
            state['security_locked_uids_i591'] = []
        return names, set()
    globals()['_i591_mark_locked_state'] = _i591_mark_locked_state

    def _i591_clear_locked_state(state):
        with _I568_STATE_LOCK:
            state['security_locked_i591'] = False
            state['security_locked_missions_i591'] = []
            state['security_locked_uids_i591'] = []
    globals()['_i591_clear_locked_state'] = _i591_clear_locked_state

    # Reuse a validated Mission subscription token. Password revalidation occurs
    # only in the background worker after TTL/token expiry, never in the browser
    # GET route and never once per poll.
    _i599_subscribe_before = _i572_subscribe_with_password
    def _i572_subscribe_with_password(mission, creator_uid, password, server_host=''):
        mission = _i599_text(mission)
        creator_uid = _i599_text(creator_uid)
        sess = _i572_session()
        cached = _i572_cached_token(mission, creator_uid)
        if cached and _i591_is_validated(mission, sess):
            return {'ok': True, 'status': 200, 'token': cached, 'source': 'validated-mission-token-cache-i599', 'reused': True}
        return _i599_subscribe_before(mission, creator_uid, password, server_host)
    globals()['_i572_subscribe_with_password'] = _i572_subscribe_with_password

    def _i599_result(payload, status=200, ok=True, error='', **extra):
        result = {
            'ok': bool(ok), 'status': int(status or 0),
            'body': _i568_clone(payload), 'json': _i568_clone(payload),
            'error': _i599_text(error),
            'identity_mode': 'per-user-enrolled-marti-certificate',
            'data_sync_worker_i599': True,
        }
        result.update(extra)
        return result

    def _i599_discovery_rows(payload):
        try:
            return list(_i569_mission_rows(payload) or [])
        except Exception:
            return []

    def _i599_cot_call(cfg, sess, user_token, mission, mission_token, protected, timeout):
        mission = _i599_text(mission)
        path = '/Marti/api/missions/' + quote(mission, safe='') + '/cot'
        started = time.monotonic()
        _i568_set_context(user_token, sess)
        try:
            if protected:
                result = dict(_i564_mission_request_raw(
                    path, method='GET', body=None,
                    headers={'User-Agent': _I564_ATAK_USER_AGENT, 'Accept': 'application/xml,application/json,*/*'},
                    token=_i599_text(mission_token), timeout=max(1, int(timeout)),
                ) or {})
            else:
                result = dict(_i569_mission_request(
                    path, method='GET', body=None,
                    headers={'Accept': 'application/xml,application/json,*/*'},
                    timeout=max(1, int(timeout)),
                ) or {})
            result = _i569_parsed_result(result)
        except Exception as exc:
            result = {'ok': False, 'status': 0, 'body': None, 'json': {}, 'error': _i599_text(exc)}
        finally:
            _i568_clear_context()
        timing = {
            'endpoint': 'mission:' + mission + ':cot-i599',
            'url_path': path,
            'ok': bool(result.get('ok')),
            'status': int(result.get('status') or 0),
            'duration_seconds': round(time.monotonic() - started, 4),
            'error': _i599_text(result.get('error'))[:300],
            'mission_token_used': bool(protected and mission_token),
            'protected': bool(protected),
        }
        return mission, result, timing

    # One coherent acquisition pass: two certificate-authenticated name-list
    # requests, then exactly one /cot request for each unlocked Mission. Locked
    # protected Missions are represented only by sanitized descriptors. No detail
    # or /contents request is needed, and no second generic enrichment pass exists.
    def _i568_parallel_acquisition(cfg, sess):
        started = time.monotonic()
        marti = _i599_text((cfg or {}).get('marti_url')).rstrip('/')
        api = _i599_text((cfg or {}).get('api_url') or (cfg or {}).get('base_url')).rstrip('/')
        user_token = _i599_text(getattr(_I529_REQUEST_CONTEXT, 'session_token', '')) if '_I529_REQUEST_CONTEXT' in globals() else ''
        if not marti:
            return {'responses': {}, 'mission_names': [], 'mission_rows': [], 'timings': [], 'mission_results_i599': {},
                    'summary': {'version': _I599_VERSION, 'discovery_ok': False, 'error': 'OpenTAKServer Marti URL is not configured.'}}

        protected_path = '/Marti/api/missions?passwordProtected=true'
        bare_path = '/Marti/api/missions'
        protected_url = marti + protected_path
        bare_url = marti + bare_path
        deadline = time.monotonic() + _I599_OVERALL_SECONDS
        responses, timings = _i569_run_parallel([
            (protected_url, protected_path, 'discovery:include-protected-i599', _I568_DISCOVERY_TIMEOUT_SECONDS),
            (bare_url, bare_path, 'discovery:bare-i599', _I568_DISCOVERY_TIMEOUT_SECONDS),
        ], cfg, sess, user_token, deadline, 2)
        protected_result = responses.get(protected_url) or {}
        bare_result = responses.get(bare_url) or {}
        full_rows = _i599_discovery_rows(_i568_result_body(protected_result)) if protected_result.get('ok') else []
        bare_rows = _i599_discovery_rows(_i568_result_body(bare_result)) if bare_result.get('ok') else []
        full_by_name = {_i599_mission_name(row).casefold(): row for row in full_rows if _i599_mission_name(row)}
        bare_by_name = {_i599_mission_name(row).casefold(): row for row in bare_rows if _i599_mission_name(row)}
        ordered, ordered_seen = [], set()
        for row in full_rows + bare_rows:
            name = _i599_mission_name(row)
            folded = name.casefold()
            if name and folded not in ordered_seen:
                ordered_seen.add(folded)
                ordered.append(name)
        # The include-protected discovery result is authoritative when available.
        # Fall back to the per-user discovery index only when that endpoint failed,
        # so deleted Missions do not remain as permanent ghost rows.
        if not protected_result.get('ok'):
            for item in _i591_load_index(sess).values():
                name = _i599_text(item.get('mission'))
                folded = name.casefold()
                if name and folded not in ordered_seen:
                    ordered_seen.add(folded)
                    ordered.append(name)

        mission_rows = []
        mission_results = {}
        cot_jobs = []
        creator_uid = _i572_creator_uid()
        locked_names = []
        authentication_failures = 0
        subscription_network_count = 0
        subscription_cache_count = 0

        for mission in ordered[:100]:
            folded = mission.casefold()
            raw_full = full_by_name.get(folded)
            raw_bare = bare_by_name.get(folded)
            protected = bool(_i599_is_protected(raw_full) or (raw_full is not None and raw_bare is None) or
                             (_i591_load_index(sess).get(folded) or {}).get('protected'))
            _i591_remember_mission(mission, protected, sess)
            if not protected:
                row = _i568_clone(raw_bare or raw_full or {'name': mission})
                row['name'] = mission
                row['passwordProtected'] = False
                mission_rows.append(row)
                mission_results[folded] = {'mission': mission, 'protected': False, 'unlocked': True, 'state': 'loading'}
                cot_jobs.append((mission, '', False))
                continue

            stored = _i572_load_password(mission, sess)
            if not (stored.get('ok') and creator_uid):
                descriptor = _i599_descriptor(mission, True, False, 'locked', sess=sess)
                mission_rows.append(descriptor)
                mission_results[folded] = {'mission': mission, 'protected': True, 'unlocked': False, 'state': 'locked'}
                locked_names.append(mission)
                _i591_invalidate_validation(mission, sess)
                continue

            subscription = _i572_subscribe_with_password(mission, creator_uid, stored.get('password'))
            if not subscription.get('ok'):
                authentication_failures += 1
                if subscription.get('invalid_password'):
                    _i572_remove_password(mission, sess)
                    _i564_invalidate_mission_token(mission, creator_uid)
                _i591_invalidate_validation(mission, sess)
                descriptor = _i599_descriptor(mission, True, False, 'locked', subscription.get('error') or '', sess=sess)
                mission_rows.append(descriptor)
                mission_results[folded] = {'mission': mission, 'protected': True, 'unlocked': False, 'state': 'locked',
                                           'error': _i599_text(subscription.get('error'))}
                locked_names.append(mission)
                continue
            if subscription.get('reused'):
                subscription_cache_count += 1
            else:
                subscription_network_count += 1
            _i591_mark_validated(mission, sess, subscription.get('token'), subscription.get('source') or 'i599-worker-validation')
            row = _i568_clone(raw_full or raw_bare or {'name': mission})
            row['name'] = mission
            row['passwordProtected'] = True
            row['authorized_i599'] = True
            mission_rows.append(row)
            mission_results[folded] = {'mission': mission, 'protected': True, 'unlocked': True, 'state': 'loading',
                                       'mission_token_source': _i599_text(subscription.get('source'))}
            cot_jobs.append((mission, subscription.get('token') or '', True))

        # Block the co-located PostgreSQL source from exposing any locked Mission.
        _I591_CONTEXT.locked_missions = list(locked_names)

        executor = ThreadPoolExecutor(max_workers=max(1, min(_I599_MAX_WORKERS, len(cot_jobs)))) if cot_jobs else None
        future_map = {}
        try:
            if executor:
                for mission, mission_token, protected in cot_jobs:
                    future = executor.submit(_i599_cot_call, cfg, sess, user_token, mission, mission_token, protected, _I599_COT_TIMEOUT_SECONDS)
                    future_map[future] = mission
                remaining = max(0.0, deadline - time.monotonic())
                done, pending = _i568_wait(list(future_map), timeout=remaining)
                for future in done:
                    mission = future_map[future]
                    try:
                        returned_mission, result, timing = future.result()
                    except Exception as exc:
                        returned_mission = mission
                        result = {'ok': False, 'status': 0, 'body': None, 'json': {}, 'error': _i599_text(exc)}
                        timing = {'endpoint': 'mission:' + mission + ':cot-i599', 'url_path': '', 'ok': False, 'status': 0,
                                  'duration_seconds': None, 'error': _i599_text(exc)[:300]}
                    q = quote(returned_mission, safe='')
                    cot_url = marti + '/Marti/api/missions/' + q + '/cot'
                    responses[cot_url] = result
                    timings.append(timing)
                    info = mission_results.get(returned_mission.casefold()) or {}
                    info['cot_ok'] = bool(result.get('ok'))
                    info['cot_status'] = int(result.get('status') or 0)
                    info['cot_error'] = _i599_text(result.get('error'))[:500]
                    if info.get('protected') and int(result.get('status') or 0) in (401, 403):
                        # A server-side Mission-token expiry is a hard security
                        # boundary. Relock immediately and remove the stale token;
                        # the next worker may revalidate the stored password.
                        info['unlocked'] = False
                        info['state'] = 'locked'
                        info['authorization_expired_i599'] = True
                        _i591_invalidate_validation(returned_mission, sess)
                        _i564_invalidate_mission_token(returned_mission, creator_uid)
                    else:
                        info['state'] = 'ready' if result.get('ok') else 'error'
                    mission_results[returned_mission.casefold()] = info
                for future in pending:
                    mission = future_map[future]
                    future.cancel()
                    q = quote(mission, safe='')
                    cot_url = marti + '/Marti/api/missions/' + q + '/cot'
                    error = 'Data Sync Mission /cot deadline reached.'
                    responses[cot_url] = {'ok': False, 'status': 0, 'body': None, 'json': {}, 'error': error}
                    timings.append({'endpoint': 'mission:' + mission + ':cot-i599', 'url_path': '/Marti/api/missions/' + q + '/cot',
                                    'ok': False, 'status': 0, 'duration_seconds': None, 'error': error})
                    info = mission_results.get(mission.casefold()) or {}
                    info.update({'cot_ok': False, 'cot_status': 0, 'cot_error': error, 'state': 'error'})
                    mission_results[mission.casefold()] = info
        finally:
            if executor:
                executor.shutdown(wait=False, cancel_futures=True)

        # Existing projection code receives only the sanitized/authorized aggregate.
        aggregate = {'version': 3, 'type': 'Mission', 'data': _i568_clone(mission_rows)}
        safe_discovery = _i599_result(aggregate, source='i599-sanitized-authoritative-discovery', network_request=True)
        responses[protected_url] = _i568_clone(safe_discovery)
        responses[bare_url] = _i568_clone(safe_discovery)
        if api:
            responses[api + '/api/missions'] = _i568_clone(safe_discovery)
        for row in mission_rows:
            mission = _i599_mission_name(row)
            if not mission:
                continue
            q = quote(mission, safe='')
            detail_url = marti + '/Marti/api/missions/' + q
            responses[detail_url] = _i599_result(_i569_mission_payload(row), source='i599-discovery-row-alias', network_request=False)
            contents = row.get('contents') if isinstance(row, dict) and isinstance(row.get('contents'), list) and not row.get('locked') else []
            responses[detail_url + '/contents'] = _i599_result({'version': 3, 'type': 'MissionContent', 'data': _i568_clone(contents)},
                                                              source='i599-discovery-contents-alias', network_request=False)

        discovery_ok = bool(protected_result.get('ok') or bare_result.get('ok'))
        successful_cot = sum(1 for info in mission_results.values() if info.get('state') == 'ready')
        failed_cot = sum(1 for info in mission_results.values() if info.get('state') == 'error')
        return {
            'responses': responses,
            'mission_names': [_i599_mission_name(row) for row in mission_rows if _i599_mission_name(row)],
            'mission_rows': mission_rows,
            'mission_results_i599': mission_results,
            'timings': sorted(timings, key=lambda row: _i599_text(row.get('endpoint'))),
            'summary': {
                'version': _I599_VERSION,
                'phase': 'per-mission-authoritative-acquisition',
                'discovery_ok': discovery_ok,
                'mission_count': len(mission_rows),
                'locked_protected_mission_count': len(locked_names),
                'unlocked_mission_count': len(cot_jobs),
                'cot_request_count': len(cot_jobs),
                'cot_success_count': successful_cot,
                'cot_failure_count': failed_cot,
                'authentication_failure_count': authentication_failures,
                'subscription_network_count': subscription_network_count,
                'subscription_cache_reuse_count': subscription_cache_count,
                'network_get_contents_calls': 0,
                'network_mission_detail_calls': 0,
                'exactly_one_cot_request_per_unlocked_mission': True,
                'protected_cot_uses_explicit_validated_token': True,
                'duration_seconds': round(time.monotonic() - started, 4),
            },
        }
    globals()['_i568_parallel_acquisition'] = _i568_parallel_acquisition

    def _i599_build_raw_snapshot(cfg, sess, token, reason):
        acquired = _i568_parallel_acquisition(cfg, sess)
        summary = dict((acquired or {}).get('summary') or {})
        if not summary.get('discovery_ok'):
            errors = [_i599_text(row.get('error')) for row in list((acquired or {}).get('timings') or [])
                      if isinstance(row, dict) and _i599_text(row.get('error'))]
            raise RuntimeError('OpenTAKServer Mission discovery did not complete successfully. ' + '; '.join(errors[:4]))
        # Use the mature local/PostgreSQL and normalization path, but bypass every
        # later versioned Mission worker/reconciler. All Mission network responses
        # were already acquired above, so this pass cannot issue a second /cot.
        _i568_seed_scope_cache(cfg, sess, acquired)
        _i568_seed_enrichment_cache(cfg, sess, acquired)
        _I568_REQUEST_CONTEXT.responses = acquired.get('responses') or {}
        base = _i568_seed_remote_mission_data(tak_map_data_sync(), cfg, acquired)
        result = _i568_augment_before(base, cfg, sess)
        if not isinstance(result, dict):
            raise RuntimeError('Data Sync augmentation returned an invalid response.')
        result = _i568_clone(result)
        result['ok'] = bool(result.get('ok', True))
        result['version'] = _I599_VERSION
        if '_i590_normalize_remote_payload' in globals():
            try:
                result = _i590_normalize_remote_payload(result, acquired)
            except Exception:
                pass
        result['data_sync_background_worker_i599'] = {
            'version': _I599_VERSION,
            'phase': 'single-authoritative-acquisition',
            'acquisition': summary,
            'endpoint_timings': list((acquired or {}).get('timings') or [])[:240],
            'legacy_worker_chain_bypassed': True,
            'second_generic_cot_request': False,
        }
        return result, acquired

    def _i599_rows_for_mission(snapshot, collection, mission):
        wanted = _i599_text(mission).casefold()
        return [_i568_clone(row) for row in list((snapshot or {}).get(collection) or [])
                if isinstance(row, dict) and _i599_mission_name(row).casefold() == wanted]

    def _i599_other_rows(snapshot, collection, mission_names):
        wanted = {name.casefold() for name in mission_names if _i599_text(name)}
        out = []
        for row in list((snapshot or {}).get(collection) or []):
            if not isinstance(row, dict):
                out.append(_i568_clone(row)); continue
            mission = _i599_mission_name(row).casefold()
            if mission and mission in wanted:
                continue
            out.append(_i568_clone(row))
        return out

    def _i599_dedupe(rows, collection):
        out = []
        seen = set()
        for row in rows or []:
            if not isinstance(row, dict):
                out.append(row); continue
            mission = _i599_mission_name(row).casefold()
            if collection == 'missions':
                ident = mission or _i599_text(row.get('guid') or row.get('id')).casefold()
            elif collection in ('mission_content', 'packages'):
                nested = row.get('data') if isinstance(row.get('data'), dict) else {}
                ident = _i599_text(row.get('hash') or nested.get('hash') or row.get('filename') or nested.get('name') or _i599_uid(row)).casefold()
            else:
                ident = _i599_uid(row).casefold()
            key = (mission, ident, collection)
            if ident and key in seen:
                continue
            if ident:
                seen.add(key)
            out.append(row)
        return out

    def _i599_project_cot(acquired, cfg, mission):
        marti = _i599_text((cfg or {}).get('marti_url')).rstrip('/')
        url = marti + '/Marti/api/missions/' + quote(_i599_text(mission), safe='') + '/cot'
        result = ((acquired or {}).get('responses') or {}).get(url)
        if not isinstance(result, dict):
            return None, []
        if not result.get('ok'):
            return result, []
        body = _i568_result_body(result)
        try:
            rows = list(_i512_mission_api_objects(body, mission) or [])
        except Exception:
            rows = []
        cleaned = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            item = _i568_clone(row)
            item['mission'] = mission
            item['mission_name'] = mission
            item['kind'] = item.get('kind') or 'datasync'
            item['is_mission_object'] = True
            cleaned.append(item)
        return result, _i599_dedupe(cleaned, 'objects')

    def _i599_reconcile(result, acquired, previous, cfg, sess):
        current = _i568_clone(result) if isinstance(result, dict) else {'ok': True, 'missions': [], 'objects': []}
        previous = _i568_clone(previous) if isinstance(previous, dict) else {}
        mission_rows = list((acquired or {}).get('mission_rows') or [])
        mission_results = dict((acquired or {}).get('mission_results_i599') or {})
        mission_names = [_i599_mission_name(row) for row in mission_rows if _i599_mission_name(row)]
        access = []

        # Ensure /cot events are the authoritative CoT membership source even when
        # discovery/detail omit uids. A successful empty /cot authoritatively clears
        # that Mission; a failed /cot retains only that Mission's last-known-good rows.
        collections = ('missions','objects','mission_uids','mission_content','packages','mission_logs','mission_roles')
        assembled = {name: _i599_other_rows(current, name, mission_names) for name in collections}
        per_mission = {}
        for row in mission_rows:
            mission = _i599_mission_name(row)
            if not mission:
                continue
            folded = mission.casefold()
            info = dict(mission_results.get(folded) or {})
            protected = bool(info.get('protected') or _i599_is_protected(row))
            unlocked = bool(info.get('unlocked')) if protected else True
            state_name = _i599_text(info.get('state')) or ('locked' if protected and not unlocked else 'error')
            error = _i599_text(info.get('cot_error') or info.get('error'))
            cot_result, projected = _i599_project_cot(acquired, cfg, mission)

            if protected and not unlocked:
                descriptor = _i599_descriptor(mission, True, False, 'locked', error, sess=sess)
                assembled['missions'].append(descriptor)
                access.append(descriptor)
                per_mission[mission] = {'state': 'locked', 'authoritative': False, 'object_count': 0, 'error': error}
                continue

            if isinstance(cot_result, dict) and cot_result.get('ok'):
                state_name = 'ready'
                # Current non-CoT metadata/content remains available only for this
                # unlocked Mission. CoT objects and mission_uids come from /cot.
                mission_current = _i599_rows_for_mission(current, 'missions', mission)
                assembled['missions'].extend(mission_current or [_i568_clone(row)])
                assembled['objects'].extend(projected)
                for obj in projected:
                    uid_row = _i568_clone(obj)
                    uid_row['mission'] = mission
                    uid_row['mission_name'] = mission
                    uid_row['source'] = 'OpenTAKServer Mission /cot authoritative membership i599'
                    assembled['mission_uids'].append(uid_row)
                assembled['mission_content'].extend(_i599_rows_for_mission(current, 'mission_content', mission))
                assembled['packages'].extend(_i599_rows_for_mission(current, 'packages', mission))
                assembled['mission_logs'].extend(_i599_rows_for_mission(current, 'mission_logs', mission))
                assembled['mission_roles'].extend(_i599_rows_for_mission(current, 'mission_roles', mission))
                descriptor = _i599_descriptor(mission, protected, True, 'ready', sess=sess)
                access.append(descriptor)
                per_mission[mission] = {'state': 'ready', 'authoritative': True, 'object_count': len(projected), 'error': ''}
                continue

            # Failed/missing /cot: preserve only this Mission's prior successful data.
            state_name = 'error'
            mission_previous = _i599_rows_for_mission(previous, 'missions', mission)
            assembled['missions'].extend(mission_previous or [_i568_clone(row)])
            for collection in ('objects','mission_uids','mission_content','packages','mission_logs','mission_roles'):
                assembled[collection].extend(_i599_rows_for_mission(previous, collection, mission))
            descriptor = _i599_descriptor(mission, protected, True, 'error', error or 'Mission /cot refresh failed.', sess=sess)
            access.append(descriptor)
            per_mission[mission] = {
                'state': 'error', 'authoritative': False,
                'object_count': len(_i599_rows_for_mission(previous, 'objects', mission)),
                'last_known_good_preserved': True,
                'error': descriptor.get('content_error_i599') or '',
            }

        for collection in collections:
            current[collection] = _i599_dedupe(assembled[collection], collection)
        access = sorted(access, key=lambda item: _i599_text(item.get('mission')).casefold())
        current['mission_access_i599'] = _i568_clone(access)
        # Compatibility arrays are generated from one canonical state so no
        # version-precedence race can hide a Mission.
        for key in ('mission_access_i596','mission_access_i595','mission_access_i594','mission_access_i591','mission_access_i576'):
            current[key] = _i568_clone(access)
        any_locked = any(bool(row.get('locked')) for row in access)
        any_unlocked = any(bool(row.get('unlocked')) for row in access)
        current['locked'] = bool(any_locked and not any_unlocked)
        current['partially_locked_i599'] = bool(any_locked and any_unlocked)
        current['requires_mission_password'] = bool(any_locked)
        current['mission_password_required'] = bool(any_locked)
        current['ok'] = True
        current['version'] = _I599_VERSION
        failed = [name for name, info in per_mission.items() if info.get('state') == 'error']
        if failed:
            current['partial'] = True
            warnings = list(current.get('warnings') or []) if isinstance(current.get('warnings'), list) else []
            warning = 'Mission content refresh failed for: ' + ', '.join(failed[:12]) + '. Last-known-good data was preserved.'
            if warning not in warnings:
                warnings.append(warning)
            current['warnings'] = warnings
        current['data_sync_reconciliation_i599'] = {
            'version': _I599_VERSION,
            'per_mission': per_mission,
            'cot_events_are_authoritative_membership': True,
            'discovery_uids_optional': True,
            'successful_empty_cot_clears_only_that_mission': True,
            'failed_cot_preserves_only_that_mission_lkg': True,
            'locked_mission_contents_removed': True,
            'second_generic_cot_request': False,
        }
        return current, access

    def _i568_build_snapshot(cfg, sess, token, reason):
        raw, acquired = _i599_build_raw_snapshot(cfg, sess, token, reason)
        reconciled, _access = _i599_reconcile(raw, acquired, None, cfg, sess)
        return reconciled, acquired
    globals()['_i568_build_snapshot'] = _i568_build_snapshot

    def _i568_refresh_worker(key, cfg, sess, token, reason, generation):
        started = time.monotonic()
        _i568_set_context(token, sess)
        try:
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                previous = _i568_clone(state.get('snapshot')) if isinstance(state.get('snapshot'), dict) else None
            result, acquired = _i599_build_raw_snapshot(cfg, sess, token, reason)
            result, access = _i599_reconcile(result, acquired, previous, cfg, sess)
            completed = time.time()
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) != int(generation):
                    return False
                state['snapshot'] = result
                state['last_success_epoch'] = completed
                state['last_attempt_completed_epoch'] = completed
                state['last_attempt_duration_seconds'] = round(time.monotonic() - started, 4)
                state['last_error'] = ''
                state['endpoint_timings'] = list((acquired or {}).get('timings') or [])[:240]
                state['acquisition_summary'] = dict((acquired or {}).get('summary') or {})
                state['completed_generation_i599'] = int(generation)
                state['snapshot_generation_i599'] = int(generation)
                _i599_set_access(state, access)
                _i568_persist_success(state)
            return True
        except Exception as exc:
            error = _i599_text(exc)[:1200]
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['last_attempt_completed_epoch'] = time.time()
                    state['last_attempt_duration_seconds'] = round(time.monotonic() - started, 4)
                    state['last_error'] = error
                    rows = _i599_current_access(state, sess)
                    for row in rows:
                        if row.get('unlocked'):
                            row['content_state_i599'] = 'error'
                            row['content_authoritative_i599'] = False
                            row['content_error_i599'] = error
                    _i599_set_access(state, rows)
            return False
        finally:
            _i568_clear_context()
            try:
                _I591_CONTEXT.locked_missions = []
            except Exception:
                pass
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['i599_worker_running'] = False
                    state['in_flight'] = False
    globals()['_i568_refresh_worker'] = _i568_refresh_worker

    def _i568_schedule_refresh(key, cfg, sess, token, reason, force=False):
        now = time.time()
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            if state.get('i599_worker_running') or state.get('in_flight'):
                return False, 'already-running-singleflight-i599'
            last_attempt = float(state.get('last_attempt_started_epoch') or 0)
            if not force and last_attempt and now - last_attempt < 2.0:
                return False, 'minimum-worker-interval-i599'
            state['generation'] = int(state.get('generation') or 0) + 1
            generation = int(state['generation'])
            state['i599_worker_running'] = True
            state['in_flight'] = True
            state['last_attempt_started_epoch'] = now
            state['last_reason'] = _i599_text(reason) or ('manual' if force else 'automatic')
            rows = _i599_current_access(state, sess)
            for row in rows:
                if row.get('unlocked'):
                    row['content_state_i599'] = 'loading'
                    row['content_authoritative_i599'] = False
                    row['content_error_i599'] = ''
            _i599_set_access(state, rows)
        thread = threading.Thread(
            target=_i568_refresh_worker,
            args=(key, _i568_clone(cfg), _i568_clone(sess), _i599_text(token), _i599_text(reason), generation),
            name='tak-map-i599-data-sync-' + str(key)[:8], daemon=True,
        )
        thread.start()
        return True, 'scheduled-i599'
    globals()['_i568_schedule_refresh'] = _i568_schedule_refresh

    def _i599_apply_transport_authority(payload, state):
        # i599 replaces the historical response-wrapper chain, so preserve the
        # validated i584/i585 exact-UID transport authority explicitly. This is
        # a read-only response projection and cannot alter worker lifecycle.
        if not isinstance(payload, dict) or '_i584p2_load_store' not in globals():
            return payload
        state_key = _i599_text((state or {}).get('key')) or (_i584p2_current_state_key() if '_i584p2_current_state_key' in globals() else '')
        try:
            from contextlib import nullcontext
            lock = globals().get('_I584_PARITY_HF2_LOCK')
            context = lock if lock is not None else nullcontext()
            with context:
                authorities = _i584p2_load_store(state_key)
                rows = _i584p_payload_rows(payload) if '_i584p_payload_rows' in globals() else list(payload.get('objects') or [])
                replacements = 0
                for row in rows:
                    uid = _i584p2_uid(row)
                    if not uid or not _i584p2_strong_exact_row(row):
                        continue
                    authority = _i584p2_authority_from_row(row, 'strong-exact-uid-cot-record')
                    if authority:
                        prior = authorities.get(uid)
                        if not prior or any(_i599_text(prior.get(key)) != _i599_text(authority.get(key)) for key in ('sidc','cot_type','usericon','affiliation','concept')):
                            authority['uid'] = uid
                            authorities[uid] = authority
                            replacements += 1
                if replacements and '_i584p2_write_store' in globals():
                    _i584p2_write_store(state_key, authorities)
                promoted = 0
                for row in rows:
                    uid = _i584p2_uid(row)
                    authority = authorities.get(uid)
                    if not uid or not authority or _i584p2_strong_exact_row(row):
                        continue
                    _i584p2_apply_authority(row, authority)
                    promoted += 1
            payload['atak_icon_parity_i584_hf2'] = {
                'version': globals().get('_I584_PARITY_HF2_VERSION', 'i584-hf2'),
                'state_key': state_key,
                'persistent_authority_count': len(authorities),
                'generic_rows_promoted': promoted,
                'strong_exact_uid_replacements': replacements,
                'survives_data_sync_refresh': True,
                'survives_server_restart': True,
                'affiliation_preserved': True,
            }
            payload['data_sync_icon_parity_i585'] = {
                'exact_uid_transport_authority_persists': True,
                'generic_rows_cannot_downgrade': True,
                'civilian_canonical_artwork': 'pink',
                'utility_and_military_friendly_artwork': 'blue',
                'single_authoritative_catalog': True,
            }
        except Exception as exc:
            payload['atak_icon_parity_warning_i599'] = _i599_text(exc)[:500]
        return payload

    def _i568_response_payload(state):
        now = time.time()
        with _I568_STATE_LOCK:
            snapshot = _i568_clone(state.get('snapshot')) if isinstance(state.get('snapshot'), dict) else {
                'ok': True, 'version': _I599_VERSION, 'missions': [], 'objects': [], 'mission_uids': [],
                'mission_content': [], 'packages': [], 'sources': [],
            }
            access = _i599_current_access(state)
            running = bool(state.get('i599_worker_running') or state.get('in_flight'))
            generation = int(state.get('generation') or 0)
            completed_generation = int(state.get('completed_generation_i599') or 0)
            snapshot_generation = int(state.get('snapshot_generation_i599') or completed_generation)
            last_success = float(state.get('last_success_epoch') or 0)
            last_error = _i599_text(state.get('last_error'))
            diag = {
                'version': _I599_VERSION,
                'state': 'loading' if running else ('error' if last_error else ('ready' if last_success else 'initial')),
                'snapshot_available': bool(state.get('snapshot')),
                'worker_running': running,
                'refreshing': running,
                'generation': generation,
                'completed_generation': completed_generation,
                'snapshot_generation': snapshot_generation,
                'transitional_response': bool(running and snapshot_generation < generation),
                'last_success_at': _i568_iso(last_success),
                'last_success_age_seconds': round(max(0.0, now - last_success), 3) if last_success else None,
                'last_attempt_started_at': _i568_iso(state.get('last_attempt_started_epoch') or 0),
                'last_attempt_completed_at': _i568_iso(state.get('last_attempt_completed_epoch') or 0),
                'last_attempt_duration_seconds': state.get('last_attempt_duration_seconds') or 0,
                'last_error': last_error,
                'last_reason': _i599_text(state.get('last_reason')),
                'single_polling_owner': True,
                'security_filter_read_only': True,
                'last_known_good_preserved': True,
            }
        snapshot['version'] = _I599_VERSION
        snapshot['mission_access_i599'] = _i568_clone(access)
        for key in ('mission_access_i596','mission_access_i595','mission_access_i594','mission_access_i591','mission_access_i576'):
            snapshot[key] = _i568_clone(access)
        any_locked = any(bool(row.get('locked')) for row in access)
        any_unlocked = any(bool(row.get('unlocked')) for row in access)
        snapshot['locked'] = bool(any_locked and not any_unlocked)
        snapshot['partially_locked_i599'] = bool(any_locked and any_unlocked)
        snapshot['requires_mission_password'] = bool(any_locked)
        snapshot['mission_password_required'] = bool(any_locked)
        snapshot['refreshing'] = running
        snapshot['data_sync_background_i599'] = diag
        snapshot['data_sync_background_i583'] = dict(diag)
        if running and not state.get('snapshot'):
            snapshot['initial_ots_refresh_in_progress'] = True
            snapshot['message'] = 'Initial OTS refresh in progress.'
        elif last_error:
            snapshot['stale'] = bool(state.get('snapshot'))
            snapshot['partial'] = True
            warnings = list(snapshot.get('warnings') or []) if isinstance(snapshot.get('warnings'), list) else []
            warning = 'Latest Data Sync refresh warning: ' + last_error
            if warning not in warnings:
                warnings.append(warning)
            snapshot['warnings'] = warnings
        return _i599_apply_transport_authority(snapshot, state)
    globals()['_i568_response_payload'] = _i568_response_payload

    # Pure per-Mission security projection. It never mutates generation, worker
    # state, or the persisted snapshot. Mixed locked/unlocked Missions retain the
    # unlocked objects and expose only sanitized descriptors for locked Missions.
    def _i599_filter_security_view(payload, state, sess=None):
        if not isinstance(payload, dict):
            return payload, 200
        out = _i568_clone(payload)
        access = _i599_current_access(state, sess)
        if not access:
            access = list(out.get('mission_access_i599') or [])
        access_map = _i599_access_map(access)
        locked_names = {name for name, row in access_map.items() if row.get('locked')}
        if locked_names:
            for collection in ('objects','mission_uids','mission_content','packages','mission_logs','mission_roles'):
                kept = []
                for row in list(out.get(collection) or []):
                    if isinstance(row, dict) and _i599_mission_name(row).casefold() in locked_names:
                        continue
                    kept.append(row)
                out[collection] = kept
            missions = []
            seen = set()
            for row in list(out.get('missions') or []):
                mission = _i599_mission_name(row)
                folded = mission.casefold()
                if not mission or folded in seen or folded in locked_names:
                    continue
                seen.add(folded); missions.append(row)
            for folded in sorted(locked_names):
                row = access_map[folded]
                mission = _i599_mission_name(row)
                if mission and folded not in seen:
                    seen.add(folded); missions.append(_i599_descriptor(mission, True, False, 'locked', row.get('content_error_i599') or '', sess=sess))
            out['missions'] = missions
        for key in ('mission_access_i599','mission_access_i596','mission_access_i595','mission_access_i594','mission_access_i591','mission_access_i576'):
            out[key] = _i568_clone(access)
        any_locked = bool(locked_names)
        any_unlocked = any(bool(row.get('unlocked')) for row in access)
        out['locked'] = bool(any_locked and not any_unlocked)
        out['partially_locked_i599'] = bool(any_locked and any_unlocked)
        out['requires_mission_password'] = any_locked
        out['mission_password_required'] = any_locked
        out['ok'] = True
        out['version'] = _I599_VERSION
        out['data_sync_security_i599'] = {
            'version': _I599_VERSION,
            'backend_gate': True,
            'per_mission_filter': True,
            'security_filter_read_only': True,
            'locked_mission_count': len(locked_names),
            'mixed_locked_unlocked_supported': True,
            'locked_contents_withheld': True,
        }
        return out, 200

    _i594_filter_security_view = _i599_filter_security_view
    _i591_filter_security_view = _i599_filter_security_view
    globals()['_i594_filter_security_view'] = _i594_filter_security_view
    globals()['_i591_filter_security_view'] = _i591_filter_security_view

    # Mission password actions are authoritative and single-pass. The submitted
    # password is validated exactly once, its returned Mission token is marked as
    # validated before the worker starts, and the worker reuses that token instead
    # of issuing a second subscription request.
    def _i572_unlock_action(payload):
        payload = payload if isinstance(payload, dict) else {}
        action = _i599_text(payload.get('action') or 'unlock').casefold()
        mission = _i599_text(payload.get('mission') or payload.get('mission_name'))[:180]
        sess = _i572_session()
        if not mission:
            return {'ok': False, 'version': _I599_VERSION, 'error': 'Mission name is required.'}, 400
        creator_uid = _i572_creator_uid()
        if not creator_uid:
            return {'ok': False, 'version': _I599_VERSION, 'mission': mission,
                    'error': 'The authenticated per-user TAK identity is unavailable.'}, 428
        cfg = _i509_load_ots_config() if '_i509_load_ots_config' in globals() else {}
        key = _i568_state_key(cfg or {}, sess or {})

        if action in ('lock','clear','remove','delete'):
            _i572_remove_password(mission, sess)
            _i564_invalidate_mission_token(mission, creator_uid)
            _i591_invalidate_validation(mission, sess)
            descriptor = _i599_descriptor(mission, True, False, 'locked', sess=sess)
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                amap = _i599_access_map(_i599_current_access(state, sess))
                amap[mission.casefold()] = descriptor
                _i599_set_access(state, list(amap.values()))
                snap = _i568_clone(state.get('snapshot')) if isinstance(state.get('snapshot'), dict) else None
                if snap:
                    for collection in ('objects','mission_uids','mission_content','packages','mission_logs','mission_roles'):
                        snap[collection] = [row for row in list(snap.get(collection) or [])
                                            if not (isinstance(row, dict) and _i599_mission_name(row).casefold() == mission.casefold())]
                    snap['missions'] = [row for row in list(snap.get('missions') or [])
                                        if not (isinstance(row, dict) and _i599_mission_name(row).casefold() == mission.casefold())]
                    snap['missions'].append(_i568_clone(descriptor))
                    state['snapshot'] = snap
            reply = dict(descriptor)
            reply.update({'ok': True, 'version': _I599_VERSION, 'message': 'Mission locked for this TAK Map user.'})
            return reply, 200

        if action != 'unlock':
            return {'ok': False, 'version': _I599_VERSION, 'mission': mission, 'error': 'Unsupported Mission access action.'}, 400
        password = str(payload.get('password') or '')
        if not password:
            return {'ok': False, 'version': _I599_VERSION, 'mission': mission, 'error': 'Enter the Mission password.'}, 400
        if len(password) > 512:
            return {'ok': False, 'version': _I599_VERSION, 'mission': mission, 'error': 'Mission password is too long.'}, 400

        # Bypass the cache-reuse wrapper for user-entered passwords. A replacement
        # password must itself be validated and can never be accepted merely because
        # an older token remains cached.
        result = _i599_subscribe_before(mission, creator_uid, password, '')
        if not isinstance(result, dict) or not result.get('ok'):
            return {
                'ok': False, 'version': _I599_VERSION, 'mission': mission,
                'invalid_password': bool((result or {}).get('invalid_password')),
                'mission_password_required': True,
                'error': _i599_text((result or {}).get('error')) or 'Mission unlock failed.',
            }, int((result or {}).get('status') or 401)
        mission_token = _i599_text(result.get('token'))
        if not mission_token:
            return {'ok': False, 'version': _I599_VERSION, 'mission': mission,
                    'error': 'Mission unlock did not return a usable subscription token.'}, 502
        saved = _i572_store_password(mission, password, sess)
        password = ''
        if not saved.get('ok'):
            _i564_invalidate_mission_token(mission, creator_uid)
            _i591_invalidate_validation(mission, sess)
            return {'ok': False, 'version': _I599_VERSION, 'mission': mission,
                    'error': 'Mission unlocked, but secure server-side storage failed.'}, 500
        _i572_set_protected(mission, True)
        _i591_mark_validated(mission, sess, mission_token, result.get('source') or 'i599-password-action')
        descriptor = _i599_descriptor(mission, True, True, 'loading', sess=sess)
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            amap = _i599_access_map(_i599_current_access(state, sess))
            amap[mission.casefold()] = descriptor
            _i599_set_access(state, list(amap.values()))
        user_token = _i599_text(getattr(_I529_REQUEST_CONTEXT, 'session_token', '') if '_I529_REQUEST_CONTEXT' in globals() else '')
        if not user_token:
            user_token = _i599_text(sess.get('_i570_token') or sess.get('token'))
        _i568_schedule_refresh(key, cfg or {}, sess or {}, user_token, 'i599-protected-mission-unlocked', force=True)
        reply = dict(descriptor)
        reply.update({'ok': True, 'version': _I599_VERSION, 'message': 'Mission unlocked for this TAK Map user.'})
        return reply, 200
    globals()['_i572_unlock_action'] = _i572_unlock_action

    # Final OTS Data Sync route: return the current completed snapshot immediately,
    # schedule at most one background worker, and never perform password
    # revalidation or Mission acquisition in the request thread.
    _i599_get_before = Handler.do_GET
    def _i599_do_get(self):
        parsed = urlparse(self.path)
        if parsed.path != '/api/tak-map/data-sync':
            return _i599_get_before(self)
        if not self._tak_map_auth_ok():
            return self._require_tak_map_login()
        sess = self._tak_map_session()
        if not _i599_text((sess or {}).get('auth_mode')).startswith('ots-'):
            return _i599_get_before(self)
        _i555_set_request_context(self)
        try:
            cfg = _i509_load_ots_config() if '_i509_load_ots_config' in globals() else {}
            token = self._tak_map_token() if callable(getattr(self, '_tak_map_token', None)) else ''
            key = _i568_state_key(cfg or {}, sess or {})
            state = _i568_state(key)
            query = parse_qs(parsed.query or '')
            force = _i599_text((query.get('force') or ['0'])[0]).casefold() in ('1','true','yes','on')
            reason = _i599_text((query.get('reason') or [''])[0]) or ('manual' if force else 'poll')
            with _I568_STATE_LOCK:
                last_success = float(state.get('last_success_epoch') or 0)
                stale = not last_success or time.time() - last_success >= _I568_SNAPSHOT_MAX_AGE_SECONDS
            if force or stale:
                _i568_schedule_refresh(key, cfg or {}, sess or {}, token, reason, force=force)
            payload = _i568_response_payload(state)
            payload, status = _i599_filter_security_view(payload, state, sess)
            return self._send_json(payload, status)
        finally:
            _i555_clear_request_context()
    Handler.do_GET = _i599_do_get

    _i599_config_before = tak_map_config
    def tak_map_config():
        cfg = dict(_i599_config_before() or {})
        cfg['version'] = _I599_PACKAGE_VERSION
        cfg['tak_map_iteration'] = _I599_VERSION
        cfg['data_sync_authoritative_i599'] = {
            'version': _I599_VERSION,
            'single_authoritative_worker': True,
            'one_cot_request_per_unlocked_mission': True,
            'protected_cot_explicit_validated_token': True,
            'cot_events_authoritative_membership': True,
            'discovery_uids_optional': True,
            'per_mission_lkg_on_failure': True,
            'successful_empty_cot_authoritative': True,
            'security_filter_read_only': True,
            'single_polling_owner': True,
            'canonical_mission_access_array': 'mission_access_i599',
            'mixed_locked_unlocked_supported': True,
            'browser_get_never_revalidates_password': True,
        }
        startup = dict(cfg.get('startup_architecture_i598') or cfg.get('startup_architecture_i597') or {})
        startup.update({
            'package_version': _I599_VERSION,
            'startup_loader_cache_identity': _I599_PACKAGE_VERSION,
            'manifest_cache_identity': _I599_PACKAGE_VERSION,
            'data_sync_control_cache_identity': _I599_PACKAGE_VERSION,
        })
        cfg['startup_architecture_i599'] = startup
        return cfg
    globals()['tak_map_config'] = tak_map_config

    def _i599_patch_html(html):
        html = str(html or '')
        html = re.sub(r'1\.3\.0-i\d+(?:-[A-Za-z0-9_-]+)?', _I599_PACKAGE_VERSION, html)
        html = re.sub(r'TAKDashboard/i\d+(?:-[A-Za-z0-9_-]+)?', 'TAKDashboard/i599', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i\d+', 'TAK-Map/1.3.0 i599', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i599\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i599\2', html)
        return html

    TAK_MAP_HTML = _i599_patch_html(TAK_MAP_HTML)
    INDEX_HTML = TAK_MAP_HTML
    TAK_MAP_LOGIN_HTML = _i599_patch_html(TAK_MAP_LOGIN_HTML)
    LOGIN_HTML = TAK_MAP_LOGIN_HTML
    TAK_MAP_ITERATION = _I599_VERSION
except Exception as _i599_exc:
    try:
        print('TAK Map i599 authoritative Data Sync patch failed:', _i599_exc)
    except Exception:
        pass
# --- end TAK Map i599 authoritative per-Mission Data Sync acquisition and publication ---


# --- TAK Map i599 complete Data Sync cadence, reconciliation, and worker-state correction ---
try:
    # This final i599 owner preserves the established 10-second Mission
    # discovery/membership cadence and 20-second full CoT cadence. OpenTAKServer
    # 1.7.11 returns Mission files/packages in the include-protected discovery
    # row; GET /contents is not part of that read contract, so no synthetic or
    # redundant GET /contents request is introduced here.
    _I599_MEMBERSHIP_INTERVAL_SECONDS = 10
    _I599_COT_INTERVAL_SECONDS = 20

    def _i599_row_mission(row, collection=''):
        if not isinstance(row, dict):
            return ''
        nested = row.get('data') if isinstance(row.get('data'), dict) else {}
        value = (
            row.get('mission') or row.get('mission_name') or row.get('missionName') or
            nested.get('mission') or nested.get('mission_name') or nested.get('missionName')
        )
        if not value and collection == 'missions':
            value = row.get('name') or nested.get('name')
        return _i599_text(value)
    globals()['_i599_row_mission'] = _i599_row_mission

    def _i599_discovery_uid_set(row):
        out = set()
        if not isinstance(row, dict):
            return out
        values = row.get('uids') if isinstance(row.get('uids'), list) else []
        for value in values:
            if isinstance(value, str):
                uid = _i599_text(value)
            elif isinstance(value, dict):
                uid = _i599_uid(value)
            else:
                uid = ''
            if uid:
                out.add(uid)
        return out

    def _i599_snapshot_uid_map(snapshot):
        out = {}
        for collection in ('mission_uids', 'objects'):
            for row in list((snapshot or {}).get(collection) or []):
                if not isinstance(row, dict):
                    continue
                mission = _i599_row_mission(row, collection)
                uid = _i599_uid(row)
                if mission and uid:
                    out.setdefault(mission.casefold(), set()).add(uid)
        return {name: sorted(values) for name, values in out.items()}

    def _i599_cot_call(cfg, sess, user_token, mission, mission_token, protected, timeout):
        mission = _i599_text(mission)
        path = '/Marti/api/missions/' + quote(mission, safe='') + '/cot'
        started = time.monotonic()
        _i568_set_context(user_token, sess)
        try:
            if protected:
                result = dict(_i564_mission_request_raw(
                    path, method='GET', body=None,
                    headers={'User-Agent': _I564_ATAK_USER_AGENT, 'Accept': 'application/xml,application/json,*/*'},
                    token=_i599_text(mission_token), timeout=max(1, int(timeout)),
                ) or {})
            else:
                result = dict(_i569_mission_request(
                    path, method='GET', body=None,
                    headers={'Accept': 'application/xml,application/json,*/*'},
                    timeout=max(1, int(timeout)),
                ) or {})
            result = _i569_parsed_result(result)
        except Exception as exc:
            result = {'ok': False, 'status': 0, 'body': None, 'json': {}, 'error': _i599_text(exc)}
        finally:
            _i568_clear_context()
        timing = {
            'endpoint': 'mission:' + mission + ':cot-i599',
            'url_path': path,
            'ok': bool(result.get('ok')),
            'status': int(result.get('status') or 0),
            'duration_seconds': round(time.monotonic() - started, 4),
            'error': _i599_text(result.get('error'))[:300],
            'mission_token_used': bool(protected and mission_token),
            'protected': bool(protected),
        }
        return mission, result, timing
    globals()['_i599_cot_call'] = _i599_cot_call

    def _i568_parallel_acquisition(cfg, sess, refresh_policy=None):
        started = time.monotonic()
        policy = dict(refresh_policy or {})
        force_cot = bool(policy.get('force_cot') or policy.get('force_content'))
        last_cot_epoch = {
            _i599_text(name).casefold(): float(value or 0)
            for name, value in dict(policy.get('last_cot_epoch_by_mission') or policy.get('last_content_epoch_by_mission') or {}).items()
            if _i599_text(name)
        }
        previous_uid_map = {
            _i599_text(name).casefold(): set(_i599_text(uid) for uid in (values or []) if _i599_text(uid))
            for name, values in dict(policy.get('previous_uid_by_mission') or {}).items()
            if _i599_text(name)
        }
        now_epoch = time.time()
        marti = _i599_text((cfg or {}).get('marti_url')).rstrip('/')
        api = _i599_text((cfg or {}).get('api_url') or (cfg or {}).get('base_url')).rstrip('/')
        user_token = _i599_text(getattr(_I529_REQUEST_CONTEXT, 'session_token', '')) if '_I529_REQUEST_CONTEXT' in globals() else ''
        if not marti:
            return {
                'responses': {}, 'mission_names': [], 'mission_rows': [], 'timings': [], 'mission_results_i599': {},
                'summary': {'version': _I599_VERSION, 'discovery_ok': False, 'error': 'OpenTAKServer Marti URL is not configured.'},
            }

        protected_path = '/Marti/api/missions?passwordProtected=true'
        bare_path = '/Marti/api/missions'
        protected_url = marti + protected_path
        bare_url = marti + bare_path
        deadline = time.monotonic() + _I599_OVERALL_SECONDS
        responses, timings = _i569_run_parallel([
            (protected_url, protected_path, 'discovery:include-protected-i599', _I568_DISCOVERY_TIMEOUT_SECONDS),
            (bare_url, bare_path, 'discovery:bare-i599', _I568_DISCOVERY_TIMEOUT_SECONDS),
        ], cfg, sess, user_token, deadline, 2)
        protected_result = responses.get(protected_url) or {}
        bare_result = responses.get(bare_url) or {}
        full_rows = _i599_discovery_rows(_i568_result_body(protected_result)) if protected_result.get('ok') else []
        bare_rows = _i599_discovery_rows(_i568_result_body(bare_result)) if bare_result.get('ok') else []
        full_by_name = {_i599_mission_name(row).casefold(): row for row in full_rows if _i599_mission_name(row)}
        bare_by_name = {_i599_mission_name(row).casefold(): row for row in bare_rows if _i599_mission_name(row)}
        ordered, ordered_seen = [], set()
        for row in full_rows + bare_rows:
            name = _i599_mission_name(row)
            folded = name.casefold()
            if name and folded not in ordered_seen:
                ordered_seen.add(folded)
                ordered.append(name)
        # Only use the stored discovery index if the include-protected endpoint
        # itself failed. A successful current discovery is authoritative for
        # Mission deletion and prevents ghost Mission rows.
        if not protected_result.get('ok'):
            for item in _i591_load_index(sess).values():
                name = _i599_text(item.get('mission'))
                folded = name.casefold()
                if name and folded not in ordered_seen:
                    ordered_seen.add(folded)
                    ordered.append(name)

        mission_rows = []
        mission_results = {}
        cot_jobs = []
        creator_uid = _i572_creator_uid()
        locked_names = []
        authentication_failures = 0
        subscription_network_count = 0
        subscription_cache_count = 0
        cot_skipped_count = 0
        cot_due_new_uid_count = 0

        for mission in ordered[:100]:
            folded = mission.casefold()
            raw_full = full_by_name.get(folded)
            raw_bare = bare_by_name.get(folded)
            protected = bool(
                _i599_is_protected(raw_full) or
                (raw_full is not None and raw_bare is None) or
                (_i591_load_index(sess).get(folded) or {}).get('protected')
            )
            _i591_remember_mission(mission, protected, sess)
            discovered_uids = _i599_discovery_uid_set(raw_full or raw_bare or {})
            prior_uids = set(previous_uid_map.get(folded) or set())
            new_uid_detected = bool(discovered_uids and (discovered_uids - prior_uids))
            prior_cot = float(last_cot_epoch.get(folded) or 0)
            cot_due = bool(force_cot or not prior_cot or now_epoch - prior_cot >= _I599_COT_INTERVAL_SECONDS or new_uid_detected)
            if new_uid_detected and not force_cot and prior_cot and now_epoch - prior_cot < _I599_COT_INTERVAL_SECONDS:
                cot_due_new_uid_count += 1

            if not protected:
                row = _i568_clone(raw_bare or raw_full or {'name': mission})
                row['name'] = mission
                row['passwordProtected'] = False
                mission_rows.append(row)
                info = {
                    'mission': mission, 'protected': False, 'unlocked': True,
                    'state': 'loading' if cot_due else 'ready',
                    'cot_due_i599': cot_due, 'cot_skipped_i599': not cot_due,
                    'discovery_uids_i599': sorted(discovered_uids),
                    'discovery_uids_present_i599': isinstance((raw_full or raw_bare or {}).get('uids'), list),
                    'discovery_contents_present_i599': isinstance((raw_full or raw_bare or {}).get('contents'), list),
                    'new_uid_detected_i599': new_uid_detected,
                }
                mission_results[folded] = info
                if cot_due:
                    cot_jobs.append((mission, '', False))
                else:
                    cot_skipped_count += 1
                continue

            stored = _i572_load_password(mission, sess)
            if not (stored.get('ok') and creator_uid):
                descriptor = _i599_descriptor(mission, True, False, 'locked', sess=sess)
                mission_rows.append(descriptor)
                mission_results[folded] = {
                    'mission': mission, 'protected': True, 'unlocked': False, 'state': 'locked',
                    'discovery_uids_i599': [], 'discovery_uids_present_i599': False,
                    'discovery_contents_present_i599': False,
                }
                locked_names.append(mission)
                _i591_invalidate_validation(mission, sess)
                continue

            subscription = _i572_subscribe_with_password(mission, creator_uid, stored.get('password'))
            if not subscription.get('ok'):
                authentication_failures += 1
                if subscription.get('invalid_password'):
                    _i572_remove_password(mission, sess)
                    _i564_invalidate_mission_token(mission, creator_uid)
                _i591_invalidate_validation(mission, sess)
                descriptor = _i599_descriptor(mission, True, False, 'locked', subscription.get('error') or '', sess=sess)
                mission_rows.append(descriptor)
                mission_results[folded] = {
                    'mission': mission, 'protected': True, 'unlocked': False, 'state': 'locked',
                    'error': _i599_text(subscription.get('error')),
                    'discovery_uids_i599': [], 'discovery_uids_present_i599': False,
                    'discovery_contents_present_i599': False,
                }
                locked_names.append(mission)
                continue

            if subscription.get('reused'):
                subscription_cache_count += 1
            else:
                subscription_network_count += 1
            mission_token = _i599_text(subscription.get('token'))
            _i591_mark_validated(mission, sess, mission_token, subscription.get('source') or 'i599-worker-validation')
            row = _i568_clone(raw_full or raw_bare or {'name': mission})
            row['name'] = mission
            row['passwordProtected'] = True
            row['authorized_i599'] = True
            mission_rows.append(row)
            info = {
                'mission': mission, 'protected': True, 'unlocked': True,
                'state': 'loading' if cot_due else 'ready',
                'cot_due_i599': cot_due, 'cot_skipped_i599': not cot_due,
                'mission_token_source': _i599_text(subscription.get('source')),
                'discovery_uids_i599': sorted(discovered_uids),
                'discovery_uids_present_i599': isinstance((raw_full or raw_bare or {}).get('uids'), list),
                'discovery_contents_present_i599': isinstance((raw_full or raw_bare or {}).get('contents'), list),
                'new_uid_detected_i599': new_uid_detected,
            }
            mission_results[folded] = info
            if cot_due:
                cot_jobs.append((mission, mission_token, True))
            else:
                cot_skipped_count += 1

        # Local PostgreSQL projection is prohibited from exposing locked Missions.
        _I591_CONTEXT.locked_missions = list(locked_names)

        executor = ThreadPoolExecutor(max_workers=max(1, min(_I599_MAX_WORKERS, len(cot_jobs)))) if cot_jobs else None
        future_map = {}
        try:
            if executor:
                for mission, mission_token, protected in cot_jobs:
                    future = executor.submit(
                        _i599_cot_call, cfg, sess, user_token, mission, mission_token,
                        protected, _I599_COT_TIMEOUT_SECONDS,
                    )
                    future_map[future] = mission
                remaining = max(0.0, deadline - time.monotonic())
                done, pending = _i568_wait(list(future_map), timeout=remaining)
                for future in done:
                    mission = future_map[future]
                    try:
                        returned_mission, result, timing = future.result()
                    except Exception as exc:
                        returned_mission = mission
                        result = {'ok': False, 'status': 0, 'body': None, 'json': {}, 'error': _i599_text(exc)}
                        timing = {
                            'endpoint': 'mission:' + mission + ':cot-i599', 'url_path': '',
                            'ok': False, 'status': 0, 'duration_seconds': None, 'error': _i599_text(exc)[:300],
                        }
                    folded = returned_mission.casefold()
                    cot_url = marti + '/Marti/api/missions/' + quote(returned_mission, safe='') + '/cot'
                    responses[cot_url] = result
                    timings.append(timing)
                    info = dict(mission_results.get(folded) or {})
                    info['cot_ok'] = bool(result.get('ok'))
                    info['cot_status'] = int(result.get('status') or 0)
                    info['cot_error'] = _i599_text(result.get('error'))[:500]
                    if info.get('protected') and int(result.get('status') or 0) in (401, 403):
                        info['unlocked'] = False
                        info['state'] = 'locked'
                        info['authorization_expired_i599'] = True
                        _i591_invalidate_validation(returned_mission, sess)
                        _i564_invalidate_mission_token(returned_mission, creator_uid)
                    elif result.get('ok'):
                        info['state'] = 'ready'
                        info['cot_refresh_completed_i599'] = True
                    else:
                        info['state'] = 'error'
                    mission_results[folded] = info
                for future in pending:
                    mission = future_map[future]
                    future.cancel()
                    cot_url = marti + '/Marti/api/missions/' + quote(mission, safe='') + '/cot'
                    error = 'Data Sync Mission /cot deadline reached.'
                    responses[cot_url] = {'ok': False, 'status': 0, 'body': None, 'json': {}, 'error': error}
                    timings.append({
                        'endpoint': 'mission:' + mission + ':cot-i599',
                        'url_path': '/Marti/api/missions/' + quote(mission, safe='') + '/cot',
                        'ok': False, 'status': 0, 'duration_seconds': None, 'error': error,
                    })
                    info = dict(mission_results.get(mission.casefold()) or {})
                    info.update({'state': 'error', 'cot_ok': False, 'cot_status': 0, 'cot_error': error})
                    mission_results[mission.casefold()] = info
        finally:
            if executor:
                executor.shutdown(wait=False, cancel_futures=True)

        aggregate = {'version': 3, 'type': 'Mission', 'data': _i568_clone(mission_rows)}
        safe_discovery = _i599_result(aggregate, source='i599-sanitized-authoritative-discovery', network_request=True)
        responses[protected_url] = _i568_clone(safe_discovery)
        responses[bare_url] = _i568_clone(safe_discovery)
        if api:
            responses[api + '/api/missions'] = _i568_clone(safe_discovery)
        for row in mission_rows:
            mission = _i599_mission_name(row)
            if not mission:
                continue
            q = quote(mission, safe='')
            detail_url = marti + '/Marti/api/missions/' + q
            responses[detail_url] = _i599_result(
                _i569_mission_payload(row), source='i599-discovery-row-alias', network_request=False)
            contents = row.get('contents') if isinstance(row, dict) and isinstance(row.get('contents'), list) and not row.get('locked') else []
            responses[detail_url + '/contents'] = _i599_result(
                {'version': 3, 'type': 'MissionContent', 'data': _i568_clone(contents)},
                source='i599-discovery-contents-alias', network_request=False,
                endpoint_not_called=True,
            )
            info = mission_results.get(mission.casefold()) or {}
            cot_url = detail_url + '/cot'
            if cot_url not in responses:
                responses[cot_url] = {
                    'ok': False, 'status': 0, 'body': None, 'json': {},
                    'error': 'i599 membership-only cadence; prior completed CoT snapshot is retained.',
                    'skipped_i599': True, 'network_request': False,
                }

        discovery_ok = bool(protected_result.get('ok') or bare_result.get('ok'))
        successful_cot = sum(1 for info in mission_results.values() if info.get('cot_refresh_completed_i599'))
        failed_cot = sum(1 for info in mission_results.values() if info.get('state') == 'error')
        return {
            'responses': responses,
            'mission_names': [_i599_mission_name(row) for row in mission_rows if _i599_mission_name(row)],
            'mission_rows': mission_rows,
            'mission_results_i599': mission_results,
            'timings': sorted(timings, key=lambda row: _i599_text(row.get('endpoint'))),
            'summary': {
                'version': _I599_VERSION,
                'phase': 'per-mission-authoritative-acquisition',
                'discovery_ok': discovery_ok,
                'mission_count': len(mission_rows),
                'locked_protected_mission_count': len(locked_names),
                'unlocked_mission_count': sum(1 for info in mission_results.values() if info.get('unlocked')),
                'membership_refresh_interval_seconds': _I599_MEMBERSHIP_INTERVAL_SECONDS,
                'cot_refresh_interval_seconds': _I599_COT_INTERVAL_SECONDS,
                'cot_refresh_forced': force_cot,
                'cot_request_count': len(cot_jobs),
                'cot_refresh_skipped_mission_count': cot_skipped_count,
                'cot_due_to_new_uid_count': cot_due_new_uid_count,
                'cot_success_count': successful_cot,
                'cot_failure_count': failed_cot,
                'authentication_failure_count': authentication_failures,
                'subscription_network_count': subscription_network_count,
                'subscription_cache_reuse_count': subscription_cache_count,
                'network_get_contents_calls': 0,
                'network_mission_detail_calls': 0,
                'exactly_one_cot_request_per_due_unlocked_mission': True,
                'exactly_one_cot_request_per_unlocked_mission': True,
                'protected_cot_uses_explicit_validated_token': True,
                'discovery_contents_are_authoritative': True,
                'duration_seconds': round(time.monotonic() - started, 4),
            },
        }
    globals()['_i568_parallel_acquisition'] = _i568_parallel_acquisition

    def _i599_build_raw_snapshot(cfg, sess, token, reason, refresh_policy=None):
        acquired = _i568_parallel_acquisition(cfg, sess, refresh_policy)
        summary = dict((acquired or {}).get('summary') or {})
        if not summary.get('discovery_ok'):
            errors = [_i599_text(row.get('error')) for row in list((acquired or {}).get('timings') or [])
                      if isinstance(row, dict) and _i599_text(row.get('error'))]
            raise RuntimeError('OpenTAKServer Mission discovery did not complete successfully. ' + '; '.join(errors[:4]))
        _i568_seed_scope_cache(cfg, sess, acquired)
        _i568_seed_enrichment_cache(cfg, sess, acquired)
        _I568_REQUEST_CONTEXT.responses = acquired.get('responses') or {}
        base = _i568_seed_remote_mission_data(tak_map_data_sync(), cfg, acquired)
        result = _i568_augment_before(base, cfg, sess)
        if not isinstance(result, dict):
            raise RuntimeError('Data Sync augmentation returned an invalid response.')
        result = _i568_clone(result)
        result['ok'] = bool(result.get('ok', True))
        result['version'] = _I599_VERSION
        if '_i590_normalize_remote_payload' in globals():
            try:
                result = _i590_normalize_remote_payload(result, acquired)
            except Exception:
                pass
        result['data_sync_background_worker_i599'] = {
            'version': _I599_VERSION,
            'phase': 'single-authoritative-acquisition',
            'acquisition': summary,
            'endpoint_timings': list((acquired or {}).get('timings') or [])[:240],
            'legacy_worker_chain_bypassed': True,
            'second_generic_cot_request': False,
            'network_get_contents_calls': 0,
        }
        return result, acquired
    globals()['_i599_build_raw_snapshot'] = _i599_build_raw_snapshot

    def _i599_rows_for_mission(snapshot, collection, mission):
        wanted = _i599_text(mission).casefold()
        return [_i568_clone(row) for row in list((snapshot or {}).get(collection) or [])
                if isinstance(row, dict) and _i599_row_mission(row, collection).casefold() == wanted]

    def _i599_other_rows(snapshot, collection, mission_names):
        # Mission-scoped rows are rebuilt per currently discovered Mission below.
        # Keep only truly unscoped rows; this also prunes deleted Mission ghosts.
        out = []
        for row in list((snapshot or {}).get(collection) or []):
            if not isinstance(row, dict):
                out.append(_i568_clone(row))
                continue
            if _i599_row_mission(row, collection):
                continue
            out.append(_i568_clone(row))
        return out

    def _i599_dedupe(rows, collection):
        out, seen = [], set()
        for row in rows or []:
            if not isinstance(row, dict):
                out.append(row)
                continue
            mission = _i599_row_mission(row, collection).casefold()
            if collection == 'missions':
                ident = mission or _i599_text(row.get('guid') or row.get('id')).casefold()
            elif collection in ('mission_content', 'mission_content_mission', 'packages'):
                nested = row.get('data') if isinstance(row.get('data'), dict) else {}
                ident = _i599_text(
                    row.get('hash') or nested.get('hash') or row.get('filename') or
                    nested.get('filename') or row.get('uid') or nested.get('uid') or
                    row.get('name') or nested.get('name')
                ).casefold()
            else:
                ident = _i599_uid(row).casefold()
            key = (mission, ident, collection)
            if ident and key in seen:
                continue
            if ident:
                seen.add(key)
            out.append(row)
        return out

    def _i599_discovery_content_rows(row, mission):
        if not isinstance(row, dict) or not isinstance(row.get('contents'), list):
            return None
        out = []
        for value in row.get('contents') or []:
            if not isinstance(value, dict):
                continue
            item = _i568_clone(value)
            item['mission'] = mission
            item['mission_name'] = mission
            nested = item.get('data') if isinstance(item.get('data'), dict) else None
            if nested is not None:
                nested['mission'] = mission
                nested['mission_name'] = mission
            out.append(item)
        return out

    def _i599_project_cot(acquired, cfg, mission):
        marti = _i599_text((cfg or {}).get('marti_url')).rstrip('/')
        url = marti + '/Marti/api/missions/' + quote(_i599_text(mission), safe='') + '/cot'
        result = ((acquired or {}).get('responses') or {}).get(url)
        if not isinstance(result, dict):
            return None, []
        if result.get('skipped_i599'):
            return result, []
        if not result.get('ok'):
            return result, []
        body = _i568_result_body(result)
        try:
            rows = list(_i512_mission_api_objects(body, mission) or [])
        except Exception:
            rows = []
        cleaned = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            item = _i568_clone(row)
            item['mission'] = mission
            item['mission_name'] = mission
            item['kind'] = item.get('kind') or 'datasync'
            item['is_mission_object'] = True
            cleaned.append(item)
        return result, _i599_dedupe(cleaned, 'objects')

    def _i599_reconcile(result, acquired, previous, cfg, sess):
        current = _i568_clone(result) if isinstance(result, dict) else {'ok': True, 'missions': [], 'objects': []}
        previous = _i568_clone(previous) if isinstance(previous, dict) else {}
        mission_rows = list((acquired or {}).get('mission_rows') or [])
        mission_results = dict((acquired or {}).get('mission_results_i599') or {})
        mission_names = [_i599_mission_name(row) for row in mission_rows if _i599_mission_name(row)]
        access = []
        collections = (
            'missions', 'objects', 'mission_uids', 'mission_content',
            'mission_content_mission', 'packages', 'mission_logs', 'mission_roles'
        )
        assembled = {name: _i599_other_rows(current, name, mission_names) for name in collections}
        per_mission = {}

        for row in mission_rows:
            mission = _i599_mission_name(row)
            if not mission:
                continue
            folded = mission.casefold()
            info = dict(mission_results.get(folded) or {})
            protected = bool(info.get('protected') or _i599_is_protected(row))
            unlocked = bool(info.get('unlocked')) if protected else True
            error = _i599_text(info.get('cot_error') or info.get('error'))

            if protected and not unlocked:
                descriptor = _i599_descriptor(mission, True, False, 'locked', error, sess=sess)
                assembled['missions'].append(descriptor)
                access.append(descriptor)
                per_mission[mission] = {
                    'state': 'locked', 'authoritative': False, 'object_count': 0,
                    'content_count': 0, 'error': error,
                }
                continue

            current_mission = _i599_rows_for_mission(current, 'missions', mission)
            previous_mission = _i599_rows_for_mission(previous, 'missions', mission)
            assembled['missions'].extend(current_mission or previous_mission or [_i568_clone(row)])

            # Mission files/packages are delivered by the authoritative discovery
            # row. Presence of a list (including an empty list) is authoritative;
            # omission preserves the previous collection for this Mission.
            discovery_content = _i599_discovery_content_rows(row, mission)
            for collection in ('mission_content', 'mission_content_mission', 'packages'):
                fresh_rows = _i599_rows_for_mission(current, collection, mission)
                if discovery_content is not None:
                    if fresh_rows:
                        assembled[collection].extend(fresh_rows)
                    elif collection in ('mission_content', 'mission_content_mission'):
                        assembled[collection].extend(_i568_clone(discovery_content))
                    elif collection == 'packages':
                        package_rows = [item for item in discovery_content if _i599_text(
                            item.get('hash') or item.get('filename') or item.get('name') or
                            ((item.get('data') or {}).get('hash') if isinstance(item.get('data'), dict) else '')
                        )]
                        assembled[collection].extend(_i568_clone(package_rows))
                else:
                    assembled[collection].extend(_i599_rows_for_mission(previous, collection, mission))
            for collection in ('mission_logs', 'mission_roles'):
                fresh_rows = _i599_rows_for_mission(current, collection, mission)
                assembled[collection].extend(fresh_rows or _i599_rows_for_mission(previous, collection, mission))

            cot_result, projected = _i599_project_cot(acquired, cfg, mission)
            skipped = bool(info.get('cot_skipped_i599') or (isinstance(cot_result, dict) and cot_result.get('skipped_i599')))
            if skipped:
                prior_objects = _i599_rows_for_mission(previous, 'objects', mission)
                prior_uids = _i599_rows_for_mission(previous, 'mission_uids', mission)
                discovered_uids = set(info.get('discovery_uids_i599') or [])
                if info.get('discovery_uids_present_i599'):
                    # Membership-only cycles can prune removals immediately. New
                    # discovery UIDs force a CoT cycle, so retained objects are the
                    # exact still-present subset.
                    prior_objects = [item for item in prior_objects if _i599_uid(item) in discovered_uids]
                    prior_uids = [item for item in prior_uids if _i599_uid(item) in discovered_uids]
                assembled['objects'].extend(prior_objects)
                assembled['mission_uids'].extend(prior_uids)
                descriptor = _i599_descriptor(mission, protected, True, 'ready', sess=sess)
                access.append(descriptor)
                per_mission[mission] = {
                    'state': 'ready', 'authoritative': bool(previous),
                    'object_count': len(prior_objects),
                    'content_count': len(discovery_content or _i599_rows_for_mission(previous, 'mission_content', mission)),
                    'membership_refresh_only_i599': True,
                    'cot_refresh_completed_i599': False,
                    'error': '',
                }
                continue

            if isinstance(cot_result, dict) and cot_result.get('ok'):
                assembled['objects'].extend(projected)
                for obj in projected:
                    uid_row = _i568_clone(obj)
                    uid_row['mission'] = mission
                    uid_row['mission_name'] = mission
                    uid_row['source'] = 'OpenTAKServer Mission /cot authoritative membership i599'
                    assembled['mission_uids'].append(uid_row)
                descriptor = _i599_descriptor(mission, protected, True, 'ready', sess=sess)
                access.append(descriptor)
                per_mission[mission] = {
                    'state': 'ready', 'authoritative': True,
                    'object_count': len(projected),
                    'content_count': len(discovery_content or []),
                    'cot_refresh_completed_i599': True,
                    'successful_empty_cot_authoritative_i599': not projected,
                    'error': '',
                }
                continue

            # A failed CoT acquisition preserves only this Mission's last-known-
            # good CoT collections. Fresh discovery content above is retained.
            prior_objects = _i599_rows_for_mission(previous, 'objects', mission)
            prior_uids = _i599_rows_for_mission(previous, 'mission_uids', mission)
            assembled['objects'].extend(prior_objects)
            assembled['mission_uids'].extend(prior_uids)
            descriptor = _i599_descriptor(
                mission, protected, True, 'error', error or 'Mission /cot refresh failed.', sess=sess)
            access.append(descriptor)
            per_mission[mission] = {
                'state': 'error', 'authoritative': False,
                'object_count': len(prior_objects),
                'content_count': len(discovery_content or _i599_rows_for_mission(previous, 'mission_content', mission)),
                'last_known_good_preserved': True,
                'cot_refresh_completed_i599': False,
                'error': descriptor.get('content_error_i599') or '',
            }

        for collection in collections:
            current[collection] = _i599_dedupe(assembled[collection], collection)
        access = sorted(access, key=lambda item: _i599_text(item.get('mission')).casefold())
        current['mission_access_i599'] = _i568_clone(access)
        for key in ('mission_access_i596', 'mission_access_i595', 'mission_access_i594', 'mission_access_i591', 'mission_access_i576'):
            current[key] = _i568_clone(access)
        any_locked = any(bool(row.get('locked')) for row in access)
        any_unlocked = any(bool(row.get('unlocked')) for row in access)
        current['locked'] = bool(any_locked and not any_unlocked)
        current['partially_locked_i599'] = bool(any_locked and any_unlocked)
        current['requires_mission_password'] = bool(any_locked)
        current['mission_password_required'] = bool(any_locked)
        current['ok'] = True
        current['version'] = _I599_VERSION
        failed = [name for name, value in per_mission.items() if value.get('state') == 'error']
        if failed:
            current['partial'] = True
            warnings = list(current.get('warnings') or []) if isinstance(current.get('warnings'), list) else []
            warning = 'Mission CoT refresh failed for: ' + ', '.join(failed[:12]) + '. Last-known-good map objects were preserved.'
            if warning not in warnings:
                warnings.append(warning)
            current['warnings'] = warnings
        current['data_sync_reconciliation_i599'] = {
            'version': _I599_VERSION,
            'per_mission': per_mission,
            'membership_refresh_interval_seconds': _I599_MEMBERSHIP_INTERVAL_SECONDS,
            'cot_refresh_interval_seconds': _I599_COT_INTERVAL_SECONDS,
            'cot_events_are_authoritative_membership': True,
            'discovery_uids_optional': True,
            'discovery_contents_are_authoritative_when_present': True,
            'successful_empty_cot_clears_only_that_mission': True,
            'failed_cot_preserves_only_that_mission_lkg': True,
            'membership_only_cycle_preserves_completed_cot': True,
            'locked_mission_contents_removed': True,
            'deleted_mission_rows_pruned': True,
            'second_generic_cot_request': False,
            'network_get_contents_calls': 0,
        }
        return current, access
    globals()['_i599_reconcile'] = _i599_reconcile

    def _i568_build_snapshot(cfg, sess, token, reason):
        policy = {'force_cot': True, 'last_cot_epoch_by_mission': {}, 'previous_uid_by_mission': {}}
        raw, acquired = _i599_build_raw_snapshot(cfg, sess, token, reason, policy)
        reconciled, _access = _i599_reconcile(raw, acquired, None, cfg, sess)
        return reconciled, acquired
    globals()['_i568_build_snapshot'] = _i568_build_snapshot

    def _i568_refresh_worker(key, cfg, sess, token, reason, generation, force_cot=False):
        started = time.monotonic()
        _i568_set_context(token, sess)
        try:
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                previous = _i568_clone(state.get('snapshot')) if isinstance(state.get('snapshot'), dict) else None
                last_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
            policy = {
                'force_cot': bool(force_cot),
                'last_cot_epoch_by_mission': last_cot,
                'previous_uid_by_mission': _i599_snapshot_uid_map(previous),
            }
            result, acquired = _i599_build_raw_snapshot(cfg, sess, token, reason, policy)
            result, access = _i599_reconcile(result, acquired, previous, cfg, sess)
            completed = time.time()
            per_mission = dict((result.get('data_sync_reconciliation_i599') or {}).get('per_mission') or {})
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) != int(generation):
                    return False
                updated_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
                current_names = set()
                for mission, info in per_mission.items():
                    folded = _i599_text(mission).casefold()
                    if not folded:
                        continue
                    current_names.add(folded)
                    if info.get('cot_refresh_completed_i599'):
                        updated_cot[folded] = completed
                    if info.get('state') == 'locked':
                        updated_cot.pop(folded, None)
                updated_cot = {name: value for name, value in updated_cot.items() if name in current_names}
                state['i599_last_cot_epoch_by_mission'] = updated_cot
                state['snapshot'] = result
                state['last_success_epoch'] = completed
                state['last_attempt_completed_epoch'] = completed
                state['last_attempt_duration_seconds'] = round(time.monotonic() - started, 4)
                state['last_error'] = ''
                state['endpoint_timings'] = list((acquired or {}).get('timings') or [])[:240]
                state['acquisition_summary'] = dict((acquired or {}).get('summary') or {})
                state['completed_generation_i599'] = int(generation)
                state['snapshot_generation_i599'] = int(generation)
                _i599_set_access(state, access)
                _i568_persist_success(state)
            return True
        except Exception as exc:
            error = _i599_text(exc)[:1200]
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['last_attempt_completed_epoch'] = time.time()
                    state['last_attempt_duration_seconds'] = round(time.monotonic() - started, 4)
                    state['last_error'] = error
                    rows = _i599_current_access(state, sess)
                    for row in rows:
                        if row.get('unlocked') and row.get('content_state_i599') == 'loading':
                            row['content_state_i599'] = 'error'
                            row['content_authoritative_i599'] = False
                            row['content_error_i599'] = error
                    _i599_set_access(state, rows)
            return False
        finally:
            _i568_clear_context()
            try:
                _I591_CONTEXT.locked_missions = []
            except Exception:
                pass
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['i599_worker_running'] = False
                    state['in_flight'] = False
    globals()['_i568_refresh_worker'] = _i568_refresh_worker

    def _i568_schedule_refresh(key, cfg, sess, token, reason, force=False):
        now = time.time()
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            if state.get('i599_worker_running') or state.get('in_flight'):
                return False, 'already-running-singleflight-i599'
            last_attempt = float(state.get('last_attempt_started_epoch') or 0)
            if not force and last_attempt and now - last_attempt < 2.0:
                return False, 'minimum-worker-interval-i599'
            state['generation'] = int(state.get('generation') or 0) + 1
            generation = int(state['generation'])
            state['i599_worker_running'] = True
            state['in_flight'] = True
            state['last_attempt_started_epoch'] = now
            state['last_reason'] = _i599_text(reason) or ('manual' if force else 'automatic')
            last_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
            rows = _i599_current_access(state, sess)
            for row in rows:
                if not row.get('unlocked'):
                    continue
                folded = _i599_mission_name(row).casefold()
                prior = float(last_cot.get(folded) or 0)
                cot_due = bool(force or not prior or now - prior >= _I599_COT_INTERVAL_SECONDS)
                if cot_due:
                    row['content_state_i599'] = 'loading'
                    row['content_authoritative_i599'] = False
                    row['content_error_i599'] = ''
            _i599_set_access(state, rows)
        thread = threading.Thread(
            target=_i568_refresh_worker,
            args=(key, _i568_clone(cfg), _i568_clone(sess), _i599_text(token), _i599_text(reason), generation, bool(force)),
            name='tak-map-i599-data-sync-' + str(key)[:8], daemon=True,
        )
        thread.start()
        return True, 'scheduled-i599'
    globals()['_i568_schedule_refresh'] = _i568_schedule_refresh

    def _i599_filter_security_view(payload, state, sess=None):
        if not isinstance(payload, dict):
            return payload, 200
        out = _i568_clone(payload)
        access = _i599_current_access(state, sess)
        if not access:
            access = list(out.get('mission_access_i599') or [])
        access_map = _i599_access_map(access)
        locked_names = {name for name, row in access_map.items() if row.get('locked')}
        if locked_names:
            for collection in ('objects', 'mission_uids', 'mission_content', 'mission_content_mission', 'packages', 'mission_logs', 'mission_roles'):
                out[collection] = [
                    row for row in list(out.get(collection) or [])
                    if not (isinstance(row, dict) and _i599_row_mission(row, collection).casefold() in locked_names)
                ]
            missions, seen = [], set()
            for row in list(out.get('missions') or []):
                mission = _i599_row_mission(row, 'missions')
                folded = mission.casefold()
                if not mission or folded in seen or folded in locked_names:
                    continue
                seen.add(folded)
                missions.append(row)
            for folded in sorted(locked_names):
                row = access_map[folded]
                mission = _i599_mission_name(row)
                if mission and folded not in seen:
                    seen.add(folded)
                    missions.append(_i599_descriptor(
                        mission, True, False, 'locked', row.get('content_error_i599') or '', sess=sess))
            out['missions'] = missions
        for key in ('mission_access_i599', 'mission_access_i596', 'mission_access_i595', 'mission_access_i594', 'mission_access_i591', 'mission_access_i576'):
            out[key] = _i568_clone(access)
        any_locked = bool(locked_names)
        any_unlocked = any(bool(row.get('unlocked')) for row in access)
        out['locked'] = bool(any_locked and not any_unlocked)
        out['partially_locked_i599'] = bool(any_locked and any_unlocked)
        out['requires_mission_password'] = any_locked
        out['mission_password_required'] = any_locked
        out['ok'] = True
        out['version'] = _I599_VERSION
        out['data_sync_security_i599'] = {
            'version': _I599_VERSION,
            'backend_gate': True,
            'per_mission_filter': True,
            'security_filter_read_only': True,
            'locked_mission_count': len(locked_names),
            'mixed_locked_unlocked_supported': True,
            'locked_contents_withheld': True,
            'worker_generation_unchanged': True,
        }
        return out, 200
    _i594_filter_security_view = _i599_filter_security_view
    _i591_filter_security_view = _i599_filter_security_view
    globals()['_i599_filter_security_view'] = _i599_filter_security_view
    globals()['_i594_filter_security_view'] = _i594_filter_security_view
    globals()['_i591_filter_security_view'] = _i591_filter_security_view

    _i599_complete_config_before = tak_map_config
    def tak_map_config():
        cfg = dict(_i599_complete_config_before() or {})
        cfg['version'] = _I599_PACKAGE_VERSION
        cfg['tak_map_iteration'] = _I599_VERSION
        details = dict(cfg.get('data_sync_authoritative_i599') or {})
        details.update({
            'membership_refresh_interval_seconds': _I599_MEMBERSHIP_INTERVAL_SECONDS,
            'cot_refresh_interval_seconds': _I599_COT_INTERVAL_SECONDS,
            'new_membership_uid_triggers_immediate_cot': True,
            'one_cot_request_per_due_unlocked_mission': True,
            'network_get_contents_calls': 0,
            'discovery_contents_authoritative': True,
            'membership_only_cycle_preserves_completed_cot': True,
            'successful_empty_cot_authoritative': True,
            'per_mission_lkg_on_cot_failure': True,
            'deleted_mission_rows_pruned': True,
            'security_filter_read_only': True,
            'mixed_locked_unlocked_supported': True,
            'single_polling_owner': True,
        })
        cfg['data_sync_authoritative_i599'] = details
        return cfg
    globals()['tak_map_config'] = tak_map_config
except Exception as _i599_complete_exc:
    try:
        print('TAK Map i599 complete Data Sync correction failed:', _i599_complete_exc)
    except Exception:
        pass
# --- end TAK Map i599 complete Data Sync cadence, reconciliation, and worker-state correction ---


# --- TAK Map i600 Data Sync snapshot continuity and behavior-preserving fast path ---
try:
    _I600_VERSION = 'i600'
    _I600_PACKAGE_VERSION = '1.3.0-i600'
    _I600_SUPPLEMENT_INTERVAL_SECONDS = 300
    _I600_SUPPLEMENT_QUERY_TIMEOUT_SECONDS = 4
    _I600_REQUIRED_COLLECTIONS = (
        'missions', 'objects', 'mission_uids', 'mission_content',
        'mission_content_mission', 'packages', 'mission_logs', 'mission_roles',
    )

    def _i600_text(value):
        try:
            return str(value if value is not None else '').strip()
        except Exception:
            return ''

    def _i600_empty_snapshot_base():
        out = {'ok': True, 'error': '', 'sources': []}
        for name in _I600_REQUIRED_COLLECTIONS:
            out[name] = []
        return out

    def _i600_flatten_properties_dict(value):
        if not isinstance(value, dict):
            return value
        layers = []
        current = value
        seen = set()
        for _depth in range(64):
            if not isinstance(current, dict) or id(current) in seen:
                break
            seen.add(id(current))
            layers.append({key: item for key, item in current.items() if key != 'properties'})
            nested = current.get('properties')
            if not isinstance(nested, dict):
                break
            current = nested
        merged = {}
        for layer in reversed(layers):
            merged.update(layer)
        return merged

    def _i600_flatten_snapshot_properties(snapshot):
        out = _i568_clone(snapshot) if isinstance(snapshot, dict) else snapshot
        if not isinstance(out, dict):
            return out, 0
        flattened = 0
        for collection in ('objects', 'mission_uids'):
            rows = out.get(collection)
            if not isinstance(rows, list):
                continue
            for row in rows:
                if not isinstance(row, dict) or not isinstance(row.get('properties'), dict):
                    continue
                before = row.get('properties')
                nested = isinstance(before.get('properties'), dict)
                row['properties'] = _i600_flatten_properties_dict(before)
                if nested:
                    flattened += 1
        return out, flattened

    def _i600_mission_lkg_from_snapshot(snapshot):
        if not isinstance(snapshot, dict):
            return {}
        access_rows = list(snapshot.get('mission_access_i599') or snapshot.get('mission_access_i596') or [])
        access_map = {
            _i599_mission_name(row).casefold(): row
            for row in access_rows if isinstance(row, dict) and _i599_mission_name(row)
        }
        per_mission = dict((snapshot.get('data_sync_reconciliation_i599') or {}).get('per_mission') or {})
        names = set()
        for collection in _I600_REQUIRED_COLLECTIONS:
            for row in list(snapshot.get(collection) or []):
                mission = _i599_row_mission(row, collection) if isinstance(row, dict) else ''
                if mission:
                    names.add(mission)
        for mission in per_mission:
            if _i600_text(mission):
                names.add(_i600_text(mission))
        for row in access_rows:
            mission = _i599_mission_name(row) if isinstance(row, dict) else ''
            if mission:
                names.add(mission)

        out = {}
        for mission in names:
            folded = mission.casefold()
            access = access_map.get(folded) or {}
            if access.get('locked'):
                continue
            info = dict(per_mission.get(mission) or per_mission.get(folded) or {})
            objects = _i599_rows_for_mission(snapshot, 'objects', mission)
            authoritative = bool(
                info.get('authoritative') or access.get('content_authoritative_i599') or
                info.get('cot_refresh_completed_i599') or objects
            )
            out[folded] = {
                'mission': mission,
                'authoritative': authoritative,
                'captured_epoch': time.time(),
                'objects': objects,
                'mission_uids': _i599_rows_for_mission(snapshot, 'mission_uids', mission),
                'mission_content': _i599_rows_for_mission(snapshot, 'mission_content', mission),
                'mission_content_mission': _i599_rows_for_mission(snapshot, 'mission_content_mission', mission),
                'packages': _i599_rows_for_mission(snapshot, 'packages', mission),
                'mission_logs': _i599_rows_for_mission(snapshot, 'mission_logs', mission),
                'mission_roles': _i599_rows_for_mission(snapshot, 'mission_roles', mission),
            }
        return out

    def _i600_merge_lkg(existing, snapshot):
        merged = _i568_clone(existing) if isinstance(existing, dict) else {}
        for key, value in _i600_mission_lkg_from_snapshot(snapshot).items():
            if key not in merged or value.get('authoritative'):
                merged[key] = value
        return merged

    def _i600_replace_mission_rows(snapshot, collection, mission, rows):
        wanted = _i600_text(mission).casefold()
        kept = []
        for row in list(snapshot.get(collection) or []):
            if isinstance(row, dict) and _i599_row_mission(row, collection).casefold() == wanted:
                continue
            kept.append(row)
        kept.extend(_i568_clone(rows or []))
        snapshot[collection] = _i599_dedupe(kept, collection)

    def _i600_access_row(access, mission):
        wanted = _i600_text(mission).casefold()
        for row in access or []:
            if isinstance(row, dict) and _i599_mission_name(row).casefold() == wanted:
                return row
        return None

    def _i600_reconcile(result, acquired, previous, cfg, sess, mission_lkg=None):
        current, access = _i599_reconcile(result, acquired, previous, cfg, sess)
        lkg = _i568_clone(mission_lkg) if isinstance(mission_lkg, dict) else {}
        lkg = _i600_merge_lkg(lkg, previous)
        mission_results = dict((acquired or {}).get('mission_results_i599') or {})
        per_mission = dict((current.get('data_sync_reconciliation_i599') or {}).get('per_mission') or {})
        continuity = {}

        for folded, info_raw in mission_results.items():
            info = dict(info_raw or {})
            mission = _i600_text(info.get('mission'))
            if not mission:
                continue
            skipped = bool(info.get('cot_skipped_i599'))
            failed = bool(info.get('state') == 'error' or info.get('cot_error'))
            entry = dict(lkg.get(mission.casefold()) or {})
            if not (skipped or failed):
                continue

            source_objects = list(entry.get('objects') or [])
            source_uids = list(entry.get('mission_uids') or [])
            discovered_uids = set(_i600_text(uid) for uid in (info.get('discovery_uids_i599') or []) if _i600_text(uid))
            explicit_uids = bool(info.get('discovery_uids_present_i599'))
            if explicit_uids:
                source_objects = [row for row in source_objects if _i599_uid(row) in discovered_uids]
                source_uids = [row for row in source_uids if _i599_uid(row) in discovered_uids]

            if source_objects or entry.get('authoritative'):
                _i600_replace_mission_rows(current, 'objects', mission, source_objects)
                _i600_replace_mission_rows(current, 'mission_uids', mission, source_uids)
                if skipped:
                    for collection in ('mission_content', 'mission_content_mission', 'packages', 'mission_logs', 'mission_roles'):
                        if not _i599_rows_for_mission(current, collection, mission):
                            _i600_replace_mission_rows(current, collection, mission, entry.get(collection) or [])
                row = _i600_access_row(access, mission)
                if row is not None:
                    row['content_state_i599'] = 'error' if failed else 'ready'
                    row['content_authoritative_i599'] = bool(entry.get('authoritative'))
                    if not failed:
                        row['content_error_i599'] = ''
                per_mission[mission] = dict(per_mission.get(mission) or {})
                per_mission[mission].update({
                    'state': 'error' if failed else 'ready',
                    'authoritative': bool(entry.get('authoritative')),
                    'object_count': len(source_objects),
                    'membership_refresh_only_i599': bool(skipped),
                    'cot_refresh_completed_i599': False,
                    'last_known_good_preserved': True,
                })
                continuity[mission] = {
                    'source': 'per-mission-last-completed-cot-i600',
                    'object_count': len(source_objects),
                    'explicit_discovery_uids': explicit_uids,
                    'authoritative': bool(entry.get('authoritative')),
                    'reason': 'cot-skipped' if skipped else 'cot-failed',
                }
            elif skipped:
                row = _i600_access_row(access, mission)
                if row is not None:
                    row['content_state_i599'] = 'loading'
                    row['content_authoritative_i599'] = False
                per_mission[mission] = dict(per_mission.get(mission) or {})
                per_mission[mission].update({
                    'state': 'loading', 'authoritative': False,
                    'object_count': 0, 'membership_refresh_only_i599': True,
                    'cot_refresh_completed_i599': False,
                })
                continuity[mission] = {
                    'source': 'no-prior-cot-i600', 'object_count': 0,
                    'explicit_discovery_uids': explicit_uids,
                    'authoritative': False, 'reason': 'cot-skipped-without-lkg',
                }

        current['version'] = _I600_VERSION
        current['data_sync_reconciliation_i599'] = dict(current.get('data_sync_reconciliation_i599') or {})
        current['data_sync_reconciliation_i599']['per_mission'] = per_mission
        current['data_sync_reconciliation_i599']['membership_only_cycle_preserves_completed_cot'] = True
        current['data_sync_reconciliation_i599']['membership_only_continuity_owner'] = _I600_VERSION
        current['data_sync_continuity_i600'] = {
            'version': _I600_VERSION,
            'per_mission': continuity,
            'membership_only_reuses_last_completed_cot': True,
            'no_cot_request_is_never_authoritative_empty': True,
            'successful_empty_cot_required_to_clear': True,
        }
        for key in ('mission_access_i599', 'mission_access_i596', 'mission_access_i595', 'mission_access_i594', 'mission_access_i591', 'mission_access_i576'):
            current[key] = _i568_clone(access)
        return current, access, lkg

    def _i600_supplement_from_snapshot(snapshot, mission_names=None):
        out = _i600_empty_snapshot_base()
        wanted = {str(name).casefold() for name in (mission_names or []) if _i600_text(name)}
        for collection in ('mission_content', 'mission_content_mission', 'packages', 'mission_logs', 'mission_roles'):
            rows = []
            for row in list((snapshot or {}).get(collection) or []):
                if not isinstance(row, dict):
                    continue
                mission = _i599_row_mission(row, collection)
                if wanted and (not mission or mission.casefold() not in wanted):
                    continue
                rows.append(_i568_clone(row))
            out[collection] = rows
        out['sources'] = list((snapshot or {}).get('sources') or [])
        return out

    def _i600_pg_supplement_fast(cfg, mission_names=None):
        started = time.monotonic()
        rows_by_key = {name: [] for name in ('mission_content', 'mission_content_mission', 'packages', 'mission_logs', 'mission_roles')}
        pg_uris, cfg_errors = _candidate_ots_pg_uris()
        if not pg_uris:
            return {
                'ok': True, 'available': False, 'configured': False,
                'duration_seconds': round(time.monotonic() - started, 4),
                'rows': rows_by_key, 'errors': list(cfg_errors or [])[:3],
            }
        uri = pg_uris[0]
        table_limits = {
            'mission_content': 240, 'mission_content_mission': 240,
            'packages': 240, 'mission_logs': 120, 'mission_roles': 240,
        }
        names_sql = ','.join(_pg_sql_literal(name) for name in table_limits)
        lines, err = _pg_query(
            uri,
            "select table_name from information_schema.tables where table_schema='public' and table_name in (" + names_sql + ")",
            timeout=_I600_SUPPLEMENT_QUERY_TIMEOUT_SECONDS,
        )
        if lines is None:
            return {
                'ok': False, 'available': False, 'configured': True,
                'duration_seconds': round(time.monotonic() - started, 4),
                'rows': rows_by_key, 'error': err or 'PostgreSQL supplemental table discovery failed.',
            }
        existing = {str(line).strip() for line in lines if str(line).strip() in table_limits}
        if not existing:
            return {
                'ok': True, 'available': True, 'configured': True,
                'duration_seconds': round(time.monotonic() - started, 4),
                'rows': rows_by_key,
            }
        pairs = []
        for table in sorted(existing):
            limit = table_limits[table]
            sub = "coalesce((select json_agg(row_to_json(q)) from (select * from " + _pg_table_ref('public', table) + f" limit {limit}) q),'[]'::json)"
            pairs.extend((_pg_sql_literal(table), sub))
        sql = 'select json_build_object(' + ','.join(pairs) + ')'
        payload_lines, err = _pg_query(uri, sql, timeout=_I600_SUPPLEMENT_QUERY_TIMEOUT_SECONDS)
        if payload_lines is None:
            return {
                'ok': False, 'available': False, 'configured': True,
                'duration_seconds': round(time.monotonic() - started, 4),
                'rows': rows_by_key, 'error': err or 'PostgreSQL supplemental query failed.',
            }
        try:
            parsed = json.loads(payload_lines[0]) if payload_lines else {}
        except Exception:
            parsed = {}
        wanted = {str(name).casefold() for name in (mission_names or []) if _i600_text(name)}
        for table in rows_by_key:
            for row in list(parsed.get(table) or []):
                if not isinstance(row, dict):
                    continue
                mission = _i599_row_mission(row, table)
                # Supplemental PostgreSQL data must be explicitly Mission-scoped.
                # Unscoped historical rows are never injected into a per-user
                # browser snapshot.
                if not mission or (wanted and mission.casefold() not in wanted):
                    continue
                rows_by_key[table].append(row)
        return {
            'ok': True, 'available': True, 'configured': True,
            'duration_seconds': round(time.monotonic() - started, 4),
            'rows': rows_by_key,
        }

    def _i600_supplement_worker(key, cfg, mission_names):
        result = _i600_pg_supplement_fast(cfg, mission_names)
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            state['i600_supplement_running'] = False
            state['i600_supplement_last_attempt_epoch'] = time.time()
            state['i600_supplement_status'] = result
            if result.get('ok'):
                base = _i600_empty_snapshot_base()
                for collection, rows in dict(result.get('rows') or {}).items():
                    if collection in base:
                        base[collection] = _i568_clone(rows)
                state['i600_supplement_snapshot'] = base
                state['i600_supplement_last_success_epoch'] = time.time()

    def _i600_schedule_supplement(key, cfg, mission_names):
        now = time.time()
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            if state.get('i600_supplement_running'):
                return False
            last = float(state.get('i600_supplement_last_attempt_epoch') or 0)
            if last and now - last < _I600_SUPPLEMENT_INTERVAL_SECONDS:
                return False
            state['i600_supplement_running'] = True
            state['i600_supplement_last_attempt_epoch'] = now
        threading.Thread(
            target=_i600_supplement_worker,
            args=(key, _i568_clone(cfg), list(mission_names or [])),
            name='tak-map-i600-pg-supplement-' + str(key)[:8], daemon=True,
        ).start()
        return True

    def _i600_base_for_fast_path(previous, supplement, mission_names):
        base = _i600_empty_snapshot_base()
        previous_supp = _i600_supplement_from_snapshot(previous, mission_names)
        cached_supp = _i600_supplement_from_snapshot(supplement, mission_names)
        for collection in ('mission_content', 'mission_content_mission', 'packages', 'mission_logs', 'mission_roles'):
            base[collection] = _i599_dedupe(
                list(cached_supp.get(collection) or []) + list(previous_supp.get(collection) or []),
                collection,
            )
        base['sources'] = list(cached_supp.get('sources') or previous_supp.get('sources') or [])
        return base

    def _i600_build_raw_snapshot(cfg, sess, token, reason, refresh_policy=None, previous=None, supplement=None):
        total_started = time.monotonic()
        stage = {}
        started = time.monotonic()
        acquired = _i568_parallel_acquisition(cfg, sess, refresh_policy)
        stage['authoritative_acquisition_seconds'] = round(time.monotonic() - started, 4)
        summary = dict((acquired or {}).get('summary') or {})
        if not summary.get('discovery_ok'):
            errors = [_i600_text(row.get('error')) for row in list((acquired or {}).get('timings') or [])
                      if isinstance(row, dict) and _i600_text(row.get('error'))]
            raise RuntimeError('OpenTAKServer Mission discovery did not complete successfully. ' + '; '.join(errors[:4]))

        mission_names = [_i599_mission_name(row) for row in list((acquired or {}).get('mission_rows') or []) if _i599_mission_name(row)]
        started = time.monotonic()
        _i568_seed_scope_cache(cfg, sess, acquired)
        _i568_seed_enrichment_cache(cfg, sess, acquired)
        _I568_REQUEST_CONTEXT.responses = acquired.get('responses') or {}
        stage['cache_seed_seconds'] = round(time.monotonic() - started, 4)

        started = time.monotonic()
        base = _i600_base_for_fast_path(previous, supplement, mission_names)
        base = _i568_seed_remote_mission_data(base, cfg, acquired)
        stage['remote_seed_seconds'] = round(time.monotonic() - started, 4)

        started = time.monotonic()
        result = _i568_augment_before(base, cfg, sess)
        stage['compatibility_finalize_seconds'] = round(time.monotonic() - started, 4)
        if not isinstance(result, dict):
            raise RuntimeError('Data Sync compatibility finalization returned an invalid response.')
        result = _i568_clone(result)
        result['ok'] = bool(result.get('ok', True))
        result['version'] = _I600_VERSION
        if '_i590_normalize_remote_payload' in globals():
            try:
                result = _i590_normalize_remote_payload(result, acquired)
            except Exception:
                pass
        stage['total_raw_snapshot_seconds'] = round(time.monotonic() - total_started, 4)
        result['data_sync_background_worker_i599'] = {
            'version': _I600_VERSION,
            'phase': 'authoritative-fast-path',
            'acquisition': summary,
            'endpoint_timings': list((acquired or {}).get('timings') or [])[:240],
            'legacy_postgresql_scan_on_critical_path': False,
            'legacy_worker_chain_bypassed': True,
            'behavior_preserving_compatibility_finalize': True,
            'second_generic_cot_request': False,
            'network_get_contents_calls': 0,
            'stage_timings_i600': stage,
        }
        result['data_sync_performance_i600'] = {
            'version': _I600_VERSION,
            'critical_path': 'Mission API acquisition + bounded compatibility finalization',
            'legacy_postgresql_scan_on_critical_path': False,
            'supplemental_postgresql_refresh_async': True,
            'supplemental_postgresql_refresh_interval_seconds': _I600_SUPPLEMENT_INTERVAL_SECONDS,
            'stage_timings': stage,
        }
        return result, acquired

    def _i600_validate_snapshot(result, acquired, lkg):
        errors = []
        mission_results = dict((acquired or {}).get('mission_results_i599') or {})
        for folded, info_raw in mission_results.items():
            info = dict(info_raw or {})
            mission = _i600_text(info.get('mission'))
            if not mission or not info.get('cot_skipped_i599'):
                continue
            entry = dict((lkg or {}).get(mission.casefold()) or {})
            if not entry.get('authoritative'):
                continue
            expected = list(entry.get('objects') or [])
            if info.get('discovery_uids_present_i599'):
                discovered = set(info.get('discovery_uids_i599') or [])
                expected = [row for row in expected if _i599_uid(row) in discovered]
            actual = _i599_rows_for_mission(result, 'objects', mission)
            expected_map = {_i599_uid(row): row for row in expected if _i599_uid(row)}
            actual_map = {_i599_uid(row): row for row in actual if _i599_uid(row)}
            if set(expected_map) != set(actual_map):
                errors.append('Membership-only generation changed the completed CoT UID set for ' + mission + '.')
                continue
            for uid, before in expected_map.items():
                after = actual_map.get(uid) or {}
                for field in ('lat', 'lon', 'raw_lat', 'raw_lon', 'coords'):
                    if field in before and before.get(field) != after.get(field):
                        errors.append('Membership-only generation changed ' + field + ' for ' + uid + '.')
                        break
        for collection in ('objects', 'mission_uids'):
            for row in list(result.get(collection) or []):
                props = row.get('properties') if isinstance(row, dict) else None
                if isinstance(props, dict) and isinstance(props.get('properties'), dict):
                    errors.append('Recursive properties wrapper remained in ' + collection + '.')
                    break
        return errors

    def _i600_update_lkg(lkg, result, acquired):
        out = _i568_clone(lkg) if isinstance(lkg, dict) else {}
        per_mission = dict((result.get('data_sync_reconciliation_i599') or {}).get('per_mission') or {})
        mission_results = dict((acquired or {}).get('mission_results_i599') or {})
        current_names = set()
        for folded, info_raw in mission_results.items():
            info = dict(info_raw or {})
            mission = _i600_text(info.get('mission'))
            if not mission:
                continue
            key = mission.casefold()
            current_names.add(key)
            state = _i600_text(info.get('state')).lower()
            if state == 'locked' or not info.get('unlocked', not info.get('protected')):
                out.pop(key, None)
                continue
            detail = dict(per_mission.get(mission) or {})
            if detail.get('cot_refresh_completed_i599'):
                out[key] = {
                    'mission': mission,
                    'authoritative': True,
                    'captured_epoch': time.time(),
                    'objects': _i599_rows_for_mission(result, 'objects', mission),
                    'mission_uids': _i599_rows_for_mission(result, 'mission_uids', mission),
                    'mission_content': _i599_rows_for_mission(result, 'mission_content', mission),
                    'mission_content_mission': _i599_rows_for_mission(result, 'mission_content_mission', mission),
                    'packages': _i599_rows_for_mission(result, 'packages', mission),
                    'mission_logs': _i599_rows_for_mission(result, 'mission_logs', mission),
                    'mission_roles': _i599_rows_for_mission(result, 'mission_roles', mission),
                }
            elif key not in out:
                derived = _i600_mission_lkg_from_snapshot(result).get(key)
                if derived:
                    out[key] = derived
        return {key: value for key, value in out.items() if key in current_names}

    def _i568_build_snapshot(cfg, sess, token, reason):
        policy = {'force_cot': True, 'last_cot_epoch_by_mission': {}, 'previous_uid_by_mission': {}}
        raw, acquired = _i600_build_raw_snapshot(cfg, sess, token, reason, policy, None, None)
        reconciled, _access, lkg = _i600_reconcile(raw, acquired, None, cfg, sess, {})
        reconciled, flattened = _i600_flatten_snapshot_properties(reconciled)
        reconciled['data_sync_performance_i600']['recursive_properties_rows_flattened'] = flattened
        errors = _i600_validate_snapshot(reconciled, acquired, lkg)
        if errors:
            raise RuntimeError('; '.join(errors[:8]))
        return reconciled, acquired
    globals()['_i568_build_snapshot'] = _i568_build_snapshot

    def _i568_refresh_worker(key, cfg, sess, token, reason, generation, force_cot=False):
        total_started = time.monotonic()
        _i568_set_context(token, sess)
        try:
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                previous = _i568_clone(state.get('snapshot')) if isinstance(state.get('snapshot'), dict) else None
                last_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
                lkg = _i568_clone(state.get('i600_mission_lkg')) if isinstance(state.get('i600_mission_lkg'), dict) else {}
                supplement = _i568_clone(state.get('i600_supplement_snapshot')) if isinstance(state.get('i600_supplement_snapshot'), dict) else None
            lkg = _i600_merge_lkg(lkg, previous)
            policy = {
                'force_cot': bool(force_cot),
                'last_cot_epoch_by_mission': last_cot,
                'previous_uid_by_mission': _i599_snapshot_uid_map(previous),
            }
            raw, acquired = _i600_build_raw_snapshot(cfg, sess, token, reason, policy, previous, supplement)
            reconcile_started = time.monotonic()
            result, access, lkg = _i600_reconcile(raw, acquired, previous, cfg, sess, lkg)
            reconcile_seconds = round(time.monotonic() - reconcile_started, 4)
            finalize_started = time.monotonic()
            result, flattened = _i600_flatten_snapshot_properties(result)
            finalize_seconds = round(time.monotonic() - finalize_started, 4)
            validation_errors = _i600_validate_snapshot(result, acquired, lkg)
            if validation_errors:
                raise RuntimeError('Data Sync i600 invariant validation failed: ' + '; '.join(validation_errors[:8]))
            completed = time.time()
            per_mission = dict((result.get('data_sync_reconciliation_i599') or {}).get('per_mission') or {})
            lkg = _i600_update_lkg(lkg, result, acquired)
            performance = dict(result.get('data_sync_performance_i600') or {})
            stage = dict(performance.get('stage_timings') or {})
            stage['reconciliation_seconds'] = reconcile_seconds
            stage['property_flatten_seconds'] = finalize_seconds
            stage['total_worker_seconds'] = round(time.monotonic() - total_started, 4)
            performance['stage_timings'] = stage
            performance['recursive_properties_rows_flattened'] = flattened
            performance['invariant_validation_passed'] = True
            result['data_sync_performance_i600'] = performance
            worker_diag = dict(result.get('data_sync_background_worker_i599') or {})
            worker_diag['stage_timings_i600'] = stage
            worker_diag['invariant_validation_passed'] = True
            result['data_sync_background_worker_i599'] = worker_diag
            result['version'] = _I600_VERSION

            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) != int(generation):
                    return False
                updated_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
                current_names = set()
                for mission, info in per_mission.items():
                    folded = _i600_text(mission).casefold()
                    if not folded:
                        continue
                    current_names.add(folded)
                    if info.get('cot_refresh_completed_i599'):
                        updated_cot[folded] = completed
                    if info.get('state') == 'locked':
                        updated_cot.pop(folded, None)
                state['i599_last_cot_epoch_by_mission'] = {
                    name: value for name, value in updated_cot.items() if name in current_names
                }
                state['i600_mission_lkg'] = lkg
                state['snapshot'] = result
                state['last_success_epoch'] = completed
                state['last_attempt_completed_epoch'] = completed
                state['last_attempt_duration_seconds'] = round(time.monotonic() - total_started, 4)
                state['last_error'] = ''
                state['endpoint_timings'] = list((acquired or {}).get('timings') or [])[:240]
                state['acquisition_summary'] = dict((acquired or {}).get('summary') or {})
                state['completed_generation_i599'] = int(generation)
                state['snapshot_generation_i599'] = int(generation)
                state['completed_generation_i600'] = int(generation)
                state['snapshot_generation_i600'] = int(generation)
                _i599_set_access(state, access)
                _i568_persist_success(state)
            mission_names = [_i599_mission_name(row) for row in list((acquired or {}).get('mission_rows') or []) if _i599_mission_name(row)]
            _i600_schedule_supplement(key, cfg, mission_names)
            return True
        except Exception as exc:
            error = _i600_text(exc)[:1200]
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['last_attempt_completed_epoch'] = time.time()
                    state['last_attempt_duration_seconds'] = round(time.monotonic() - total_started, 4)
                    state['last_error'] = error
                    rows = _i599_current_access(state, sess)
                    for row in rows:
                        if row.get('unlocked') and row.get('content_state_i599') == 'loading':
                            row['content_state_i599'] = 'error'
                            row['content_authoritative_i599'] = False
                            row['content_error_i599'] = error
                    _i599_set_access(state, rows)
            return False
        finally:
            _i568_clear_context()
            try:
                _I591_CONTEXT.locked_missions = []
            except Exception:
                pass
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['i599_worker_running'] = False
                    state['in_flight'] = False
    globals()['_i568_refresh_worker'] = _i568_refresh_worker

    def _i568_schedule_refresh(key, cfg, sess, token, reason, force=False):
        now = time.time()
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            if state.get('i599_worker_running') or state.get('in_flight'):
                return False, 'already-running-singleflight-i600'
            last_attempt = float(state.get('last_attempt_started_epoch') or 0)
            if not force and last_attempt and now - last_attempt < 2.0:
                return False, 'minimum-worker-interval-i600'
            state['generation'] = int(state.get('generation') or 0) + 1
            generation = int(state['generation'])
            state['i599_worker_running'] = True
            state['in_flight'] = True
            state['last_attempt_started_epoch'] = now
            state['last_reason'] = _i600_text(reason) or ('manual' if force else 'automatic')
            last_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
            rows = _i599_current_access(state, sess)
            for row in rows:
                if not row.get('unlocked'):
                    continue
                folded = _i599_mission_name(row).casefold()
                prior = float(last_cot.get(folded) or 0)
                cot_due = bool(force or not prior or now - prior >= _I599_COT_INTERVAL_SECONDS)
                if cot_due:
                    row['content_state_i599'] = 'loading'
                    row['content_authoritative_i599'] = False
                    row['content_error_i599'] = ''
            _i599_set_access(state, rows)
        threading.Thread(
            target=_i568_refresh_worker,
            args=(key, _i568_clone(cfg), _i568_clone(sess), _i600_text(token), _i600_text(reason), generation, bool(force)),
            name='tak-map-i600-data-sync-' + str(key)[:8], daemon=True,
        ).start()
        return True, 'scheduled-i600'
    globals()['_i568_schedule_refresh'] = _i568_schedule_refresh

    _i600_response_payload_before = _i568_response_payload
    def _i568_response_payload(state):
        payload = _i600_response_payload_before(state)
        if not isinstance(payload, dict):
            return payload
        payload['version'] = _I600_VERSION
        background = dict(payload.get('data_sync_background_i599') or {})
        background['version'] = _I600_VERSION
        background['completed_generation_i600'] = int((state or {}).get('completed_generation_i600') or background.get('completed_generation') or 0)
        background['snapshot_generation_i600'] = int((state or {}).get('snapshot_generation_i600') or background.get('snapshot_generation') or 0)
        background['last_known_good_preserved'] = True
        background['legacy_postgresql_scan_on_critical_path'] = False
        payload['data_sync_background_i599'] = background
        payload['data_sync_background_i583'] = dict(background)
        supplement = dict((state or {}).get('i600_supplement_status') or {})
        payload['data_sync_supplement_i600'] = {
            'version': _I600_VERSION,
            'running': bool((state or {}).get('i600_supplement_running')),
            'last_success_at': _i568_iso((state or {}).get('i600_supplement_last_success_epoch') or 0),
            'status': supplement,
            'critical_path': False,
        }
        return payload
    globals()['_i568_response_payload'] = _i568_response_payload

    _i600_config_before = tak_map_config
    def tak_map_config():
        cfg = dict(_i600_config_before() or {})
        cfg['version'] = _I600_PACKAGE_VERSION
        cfg['tak_map_iteration'] = _I600_VERSION
        details = dict(cfg.get('data_sync_authoritative_i599') or {})
        details.update({
            'version': _I600_VERSION,
            'membership_only_cycle_preserves_completed_cot': True,
            'no_cot_request_is_never_authoritative_empty': True,
            'successful_empty_cot_required_to_clear': True,
            'legacy_postgresql_scan_on_critical_path': False,
            'supplemental_postgresql_refresh_async': True,
            'behavior_preserving_compatibility_finalize': True,
            'recursive_properties_flattened_once': True,
            'snapshot_invariant_validation': True,
        })
        cfg['data_sync_authoritative_i600'] = details
        cfg['data_sync_authoritative_i599'] = details
        return cfg
    globals()['tak_map_config'] = tak_map_config

    def _i600_patch_html(html):
        html = str(html or '')
        html = re.sub(r'1\.3\.0-i599', _I600_PACKAGE_VERSION, html)
        html = re.sub(r'TAKDashboard/i599', 'TAKDashboard/i600', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i599', 'TAK-Map/1.3.0 i600', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i600\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i600\2', html)
        return html

    TAK_MAP_HTML = _i600_patch_html(TAK_MAP_HTML)
    INDEX_HTML = TAK_MAP_HTML
    TAK_MAP_LOGIN_HTML = _i600_patch_html(TAK_MAP_LOGIN_HTML)
    LOGIN_HTML = TAK_MAP_LOGIN_HTML
    TAK_MAP_ITERATION = _I600_VERSION
except Exception as _i600_exc:
    try:
        print('TAK Map i600 Data Sync continuity/performance patch failed:', _i600_exc)
    except Exception:
        pass
# --- end TAK Map i600 Data Sync snapshot continuity and behavior-preserving fast path ---


# --- TAK Map i601 Data Sync discovery/CoT identity separation and continuity correction ---
try:
    _I601_VERSION = 'i601'
    _I601_PACKAGE_VERSION = '1.3.0-i601'

    def _i601_text(value):
        return '' if value is None else str(value).strip()

    def _i601_discovery_uid_map_from_acquired(acquired):
        out = {}
        for folded, info_raw in dict((acquired or {}).get('mission_results_i599') or {}).items():
            info = dict(info_raw or {})
            mission = _i601_text(info.get('mission'))
            if not mission:
                continue
            out[mission.casefold()] = sorted({
                _i601_text(uid) for uid in list(info.get('discovery_uids_i599') or [])
                if _i601_text(uid)
            })
        return out

    def _i601_discovery_uid_map_from_snapshot(snapshot):
        out = {}
        for row in list((snapshot or {}).get('missions') or []):
            if not isinstance(row, dict):
                continue
            mission = _i599_mission_name(row)
            if not mission:
                continue
            out[mission.casefold()] = sorted(_i599_discovery_uid_set(row))
        return out

    # The i599 acquisition function already has the correct cadence behavior,
    # but its historical policy key was named previous_uid_by_mission. i601
    # supplies only prior discovery/content UUIDs through that key. CoT event
    # UIDs are never used for discovery fingerprint comparison.
    _i601_parallel_acquisition_before = _i568_parallel_acquisition
    def _i568_parallel_acquisition(cfg, sess, refresh_policy=None):
        policy = dict(refresh_policy or {})
        if 'previous_discovery_uid_by_mission' in policy:
            policy['previous_uid_by_mission'] = dict(policy.get('previous_discovery_uid_by_mission') or {})
        result = _i601_parallel_acquisition_before(cfg, sess, policy)
        summary = dict((result or {}).get('summary') or {})
        summary['discovery_uid_tracking_owner'] = _I601_VERSION
        summary['discovery_uids_separate_from_cot_event_uids'] = True
        summary['discovery_uid_change_forces_cot_refresh_only'] = True
        result['summary'] = summary
        for info in dict((result or {}).get('mission_results_i599') or {}).values():
            if not isinstance(info, dict):
                continue
            values = sorted({_i601_text(uid) for uid in list(info.get('discovery_uids_i599') or []) if _i601_text(uid)})
            info['discovery_uid_fingerprint_i601'] = json.dumps(values, separators=(',', ':'))
            info['discovery_uid_identity_domain_i601'] = 'mission-content-identifiers'
            info['cot_event_uid_identity_domain_i601'] = 'cot-event-identifiers'
        return result
    globals()['_i568_parallel_acquisition'] = _i568_parallel_acquisition

    def _i601_reconcile(result, acquired, previous, cfg, sess, mission_lkg=None):
        current, access = _i599_reconcile(result, acquired, previous, cfg, sess)
        lkg = _i568_clone(mission_lkg) if isinstance(mission_lkg, dict) else {}
        lkg = _i600_merge_lkg(lkg, previous)
        mission_results = dict((acquired or {}).get('mission_results_i599') or {})
        per_mission = dict((current.get('data_sync_reconciliation_i599') or {}).get('per_mission') or {})
        continuity = {}

        for folded, info_raw in mission_results.items():
            info = dict(info_raw or {})
            mission = _i601_text(info.get('mission'))
            if not mission:
                continue
            skipped = bool(info.get('cot_skipped_i599'))
            failed = bool(info.get('state') == 'error' or info.get('cot_error'))
            if not (skipped or failed):
                continue

            entry = dict(lkg.get(mission.casefold()) or {})
            # Critical i601 rule: discovery uids are Mission content identifiers,
            # not authoritative CoT event UIDs. Never use them to prune cached
            # /cot objects or mission_uids when /cot was skipped or failed.
            source_objects = list(entry.get('objects') or [])
            source_uids = list(entry.get('mission_uids') or [])
            discovered_uids = sorted({_i601_text(uid) for uid in list(info.get('discovery_uids_i599') or []) if _i601_text(uid)})
            explicit_uids = bool(info.get('discovery_uids_present_i599'))

            if source_objects or entry.get('authoritative'):
                _i600_replace_mission_rows(current, 'objects', mission, source_objects)
                _i600_replace_mission_rows(current, 'mission_uids', mission, source_uids)
                if skipped:
                    for collection in ('mission_content', 'mission_content_mission', 'packages', 'mission_logs', 'mission_roles'):
                        if not _i599_rows_for_mission(current, collection, mission):
                            _i600_replace_mission_rows(current, collection, mission, entry.get(collection) or [])
                row = _i600_access_row(access, mission)
                if row is not None:
                    row['content_state_i599'] = 'error' if failed else 'ready'
                    row['content_authoritative_i599'] = bool(entry.get('authoritative'))
                    if not failed:
                        row['content_error_i599'] = ''
                per_mission[mission] = dict(per_mission.get(mission) or {})
                per_mission[mission].update({
                    'state': 'error' if failed else 'ready',
                    'authoritative': bool(entry.get('authoritative')),
                    'object_count': len(source_objects),
                    'membership_refresh_only_i599': bool(skipped),
                    'cot_refresh_completed_i599': False,
                    'last_known_good_preserved': True,
                    'discovery_uid_pruning_disabled_i601': True,
                })
                continuity[mission] = {
                    'source': 'per-mission-last-completed-cot-i601',
                    'object_count': len(source_objects),
                    'explicit_discovery_uids': explicit_uids,
                    'discovery_uid_count': len(discovered_uids),
                    'authoritative': bool(entry.get('authoritative')),
                    'reason': 'cot-skipped' if skipped else 'cot-failed',
                    'discovery_uids_used_to_prune_cot': False,
                }
            elif skipped:
                row = _i600_access_row(access, mission)
                if row is not None:
                    row['content_state_i599'] = 'loading'
                    row['content_authoritative_i599'] = False
                per_mission[mission] = dict(per_mission.get(mission) or {})
                per_mission[mission].update({
                    'state': 'loading', 'authoritative': False,
                    'object_count': 0, 'membership_refresh_only_i599': True,
                    'cot_refresh_completed_i599': False,
                    'discovery_uid_pruning_disabled_i601': True,
                })
                continuity[mission] = {
                    'source': 'no-prior-cot-i601', 'object_count': 0,
                    'explicit_discovery_uids': explicit_uids,
                    'discovery_uid_count': len(discovered_uids),
                    'authoritative': False, 'reason': 'cot-skipped-without-lkg',
                    'discovery_uids_used_to_prune_cot': False,
                }

        current['version'] = _I601_VERSION
        current['data_sync_reconciliation_i599'] = dict(current.get('data_sync_reconciliation_i599') or {})
        current['data_sync_reconciliation_i599']['per_mission'] = per_mission
        current['data_sync_reconciliation_i599']['membership_only_cycle_preserves_completed_cot'] = True
        current['data_sync_reconciliation_i599']['membership_only_continuity_owner'] = _I601_VERSION
        current['data_sync_reconciliation_i599']['discovery_uids_never_prune_cot_events_i601'] = True
        current['data_sync_continuity_i601'] = {
            'version': _I601_VERSION,
            'per_mission': continuity,
            'membership_only_reuses_complete_last_cot': True,
            'discovery_uids_separate_from_cot_event_uids': True,
            'discovery_uids_never_prune_cot_events': True,
            'discovery_uid_change_forces_cot_refresh_only': True,
            'no_cot_request_is_never_authoritative_empty': True,
            'successful_empty_cot_required_to_clear': True,
        }
        # Keep the prior diagnostic key available for existing browser tooling,
        # but make i601 the authoritative continuity owner.
        current['data_sync_continuity_i600'] = _i568_clone(current['data_sync_continuity_i601'])
        for key in ('mission_access_i599', 'mission_access_i596', 'mission_access_i595', 'mission_access_i594', 'mission_access_i591', 'mission_access_i576'):
            current[key] = _i568_clone(access)
        return current, access, lkg

    def _i601_validate_snapshot(result, acquired, lkg):
        errors = []
        mission_results = dict((acquired or {}).get('mission_results_i599') or {})
        for folded, info_raw in mission_results.items():
            info = dict(info_raw or {})
            mission = _i601_text(info.get('mission'))
            if not mission or not info.get('cot_skipped_i599'):
                continue
            entry = dict((lkg or {}).get(mission.casefold()) or {})
            if not entry.get('authoritative'):
                continue
            expected = list(entry.get('objects') or [])
            actual = _i599_rows_for_mission(result, 'objects', mission)
            expected_map = {_i599_uid(row): row for row in expected if _i599_uid(row)}
            actual_map = {_i599_uid(row): row for row in actual if _i599_uid(row)}
            if set(expected_map) != set(actual_map):
                errors.append('Membership-only generation changed the completed CoT UID set for ' + mission + '.')
                continue
            for uid, before in expected_map.items():
                after = actual_map.get(uid) or {}
                for field in ('lat', 'lon', 'raw_lat', 'raw_lon', 'coords', 'geometry'):
                    if field in before and before.get(field) != after.get(field):
                        errors.append('Membership-only generation changed ' + field + ' for ' + uid + '.')
                        break
        for collection in ('objects', 'mission_uids'):
            for row in list(result.get(collection) or []):
                props = row.get('properties') if isinstance(row, dict) else None
                if isinstance(props, dict) and isinstance(props.get('properties'), dict):
                    errors.append('Recursive properties wrapper remained in ' + collection + '.')
                    break
        return errors

    def _i568_build_snapshot(cfg, sess, token, reason):
        policy = {
            'force_cot': True,
            'last_cot_epoch_by_mission': {},
            'previous_discovery_uid_by_mission': {},
        }
        raw, acquired = _i600_build_raw_snapshot(cfg, sess, token, reason, policy, None, None)
        reconciled, _access, lkg = _i601_reconcile(raw, acquired, None, cfg, sess, {})
        reconciled, flattened = _i600_flatten_snapshot_properties(reconciled)
        reconciled['data_sync_performance_i600']['recursive_properties_rows_flattened'] = flattened
        errors = _i601_validate_snapshot(reconciled, acquired, lkg)
        if errors:
            raise RuntimeError('; '.join(errors[:8]))
        return reconciled, acquired
    globals()['_i568_build_snapshot'] = _i568_build_snapshot

    def _i568_refresh_worker(key, cfg, sess, token, reason, generation, force_cot=False):
        total_started = time.monotonic()
        _i568_set_context(token, sess)
        try:
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                previous = _i568_clone(state.get('snapshot')) if isinstance(state.get('snapshot'), dict) else None
                last_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
                lkg = _i568_clone(state.get('i601_mission_lkg')) if isinstance(state.get('i601_mission_lkg'), dict) else (
                    _i568_clone(state.get('i600_mission_lkg')) if isinstance(state.get('i600_mission_lkg'), dict) else {}
                )
                previous_discovery = dict(state.get('i601_last_discovery_uids_by_mission') or {})
                supplement = _i568_clone(state.get('i600_supplement_snapshot')) if isinstance(state.get('i600_supplement_snapshot'), dict) else None
            lkg = _i600_merge_lkg(lkg, previous)
            if not previous_discovery:
                previous_discovery = _i601_discovery_uid_map_from_snapshot(previous)
            policy = {
                'force_cot': bool(force_cot),
                'last_cot_epoch_by_mission': last_cot,
                'previous_discovery_uid_by_mission': previous_discovery,
            }
            raw, acquired = _i600_build_raw_snapshot(cfg, sess, token, reason, policy, previous, supplement)
            reconcile_started = time.monotonic()
            result, access, lkg = _i601_reconcile(raw, acquired, previous, cfg, sess, lkg)
            reconcile_seconds = round(time.monotonic() - reconcile_started, 4)
            finalize_started = time.monotonic()
            result, flattened = _i600_flatten_snapshot_properties(result)
            finalize_seconds = round(time.monotonic() - finalize_started, 4)
            validation_errors = _i601_validate_snapshot(result, acquired, lkg)
            if validation_errors:
                raise RuntimeError('Data Sync i601 invariant validation failed: ' + '; '.join(validation_errors[:8]))
            completed = time.time()
            per_mission = dict((result.get('data_sync_reconciliation_i599') or {}).get('per_mission') or {})
            lkg = _i600_update_lkg(lkg, result, acquired)
            discovery_map = _i601_discovery_uid_map_from_acquired(acquired)
            performance = dict(result.get('data_sync_performance_i600') or {})
            stage = dict(performance.get('stage_timings') or {})
            stage['reconciliation_seconds'] = reconcile_seconds
            stage['property_flatten_seconds'] = finalize_seconds
            stage['total_worker_seconds'] = round(time.monotonic() - total_started, 4)
            performance['version'] = _I601_VERSION
            performance['stage_timings'] = stage
            performance['recursive_properties_rows_flattened'] = flattened
            performance['invariant_validation_passed'] = True
            performance['discovery_uids_separate_from_cot_event_uids'] = True
            result['data_sync_performance_i600'] = performance
            result['data_sync_performance_i601'] = _i568_clone(performance)
            worker_diag = dict(result.get('data_sync_background_worker_i599') or {})
            worker_diag['stage_timings_i601'] = stage
            worker_diag['invariant_validation_passed'] = True
            worker_diag['discovery_uid_tracking_owner'] = _I601_VERSION
            result['data_sync_background_worker_i599'] = worker_diag
            result['version'] = _I601_VERSION

            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) != int(generation):
                    return False
                updated_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
                current_names = set()
                for mission, info in per_mission.items():
                    folded = _i601_text(mission).casefold()
                    if not folded:
                        continue
                    current_names.add(folded)
                    if info.get('cot_refresh_completed_i599'):
                        updated_cot[folded] = completed
                    if info.get('state') == 'locked':
                        updated_cot.pop(folded, None)
                state['i599_last_cot_epoch_by_mission'] = {
                    name: value for name, value in updated_cot.items() if name in current_names
                }
                state['i601_last_discovery_uids_by_mission'] = {
                    name: values for name, values in discovery_map.items() if name in current_names
                }
                state['i601_mission_lkg'] = lkg
                state['i600_mission_lkg'] = lkg
                state['snapshot'] = result
                state['last_success_epoch'] = completed
                state['last_attempt_completed_epoch'] = completed
                state['last_attempt_duration_seconds'] = round(time.monotonic() - total_started, 4)
                state['last_error'] = ''
                state['endpoint_timings'] = list((acquired or {}).get('timings') or [])[:240]
                state['acquisition_summary'] = dict((acquired or {}).get('summary') or {})
                state['completed_generation_i599'] = int(generation)
                state['snapshot_generation_i599'] = int(generation)
                state['completed_generation_i600'] = int(generation)
                state['snapshot_generation_i600'] = int(generation)
                state['completed_generation_i601'] = int(generation)
                state['snapshot_generation_i601'] = int(generation)
                _i599_set_access(state, access)
                _i568_persist_success(state)
            mission_names = [_i599_mission_name(row) for row in list((acquired or {}).get('mission_rows') or []) if _i599_mission_name(row)]
            _i600_schedule_supplement(key, cfg, mission_names)
            return True
        except Exception as exc:
            error = _i601_text(exc)[:1200]
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['last_attempt_completed_epoch'] = time.time()
                    state['last_attempt_duration_seconds'] = round(time.monotonic() - total_started, 4)
                    state['last_error'] = error
                    rows = _i599_current_access(state, sess)
                    for row in rows:
                        if row.get('unlocked') and row.get('content_state_i599') == 'loading':
                            row['content_state_i599'] = 'error'
                            row['content_authoritative_i599'] = False
                            row['content_error_i599'] = error
                    _i599_set_access(state, rows)
            return False
        finally:
            _i568_clear_context()
            try:
                _I591_CONTEXT.locked_missions = []
            except Exception:
                pass
            with _I568_STATE_LOCK:
                state = _i568_state(key)
                if int(state.get('generation') or 0) == int(generation):
                    state['i599_worker_running'] = False
                    state['in_flight'] = False
    globals()['_i568_refresh_worker'] = _i568_refresh_worker

    def _i568_schedule_refresh(key, cfg, sess, token, reason, force=False):
        now = time.time()
        with _I568_STATE_LOCK:
            state = _i568_state(key)
            if state.get('i599_worker_running') or state.get('in_flight'):
                return False, 'already-running-singleflight-i601'
            last_attempt = float(state.get('last_attempt_started_epoch') or 0)
            if not force and last_attempt and now - last_attempt < 2.0:
                return False, 'minimum-worker-interval-i601'
            state['generation'] = int(state.get('generation') or 0) + 1
            generation = int(state['generation'])
            state['i599_worker_running'] = True
            state['in_flight'] = True
            state['last_attempt_started_epoch'] = now
            state['last_reason'] = _i601_text(reason) or ('manual' if force else 'automatic')
            last_cot = dict(state.get('i599_last_cot_epoch_by_mission') or {})
            rows = _i599_current_access(state, sess)
            for row in rows:
                if not row.get('unlocked'):
                    continue
                folded = _i599_mission_name(row).casefold()
                prior = float(last_cot.get(folded) or 0)
                cot_due = bool(force or not prior or now - prior >= _I599_COT_INTERVAL_SECONDS)
                if cot_due:
                    row['content_state_i599'] = 'loading'
                    row['content_authoritative_i599'] = False
                    row['content_error_i599'] = ''
            _i599_set_access(state, rows)
        threading.Thread(
            target=_i568_refresh_worker,
            args=(key, _i568_clone(cfg), _i568_clone(sess), _i601_text(token), _i601_text(reason), generation, bool(force)),
            name='tak-map-i601-data-sync-' + str(key)[:8], daemon=True,
        ).start()
        return True, 'scheduled-i601'
    globals()['_i568_schedule_refresh'] = _i568_schedule_refresh

    _i601_response_payload_before = _i568_response_payload
    def _i568_response_payload(state):
        payload = _i601_response_payload_before(state)
        if not isinstance(payload, dict):
            return payload
        payload['version'] = _I601_VERSION
        background = dict(payload.get('data_sync_background_i599') or {})
        background['version'] = _I601_VERSION
        background['completed_generation_i601'] = int((state or {}).get('completed_generation_i601') or background.get('completed_generation') or 0)
        background['snapshot_generation_i601'] = int((state or {}).get('snapshot_generation_i601') or background.get('snapshot_generation') or 0)
        background['last_known_good_preserved'] = True
        background['discovery_uids_separate_from_cot_event_uids'] = True
        payload['data_sync_background_i599'] = background
        payload['data_sync_background_i583'] = dict(background)
        payload['data_sync_discovery_identity_i601'] = {
            'version': _I601_VERSION,
            'previous_discovery_uids_by_mission': _i568_clone((state or {}).get('i601_last_discovery_uids_by_mission') or {}),
            'discovery_uids_separate_from_cot_event_uids': True,
            'discovery_uid_change_forces_cot_refresh_only': True,
            'discovery_uids_never_prune_cot_events': True,
        }
        return payload
    globals()['_i568_response_payload'] = _i568_response_payload

    _i601_config_before = tak_map_config
    def tak_map_config():
        cfg = dict(_i601_config_before() or {})
        cfg['version'] = _I601_PACKAGE_VERSION
        cfg['tak_map_iteration'] = _I601_VERSION
        details = dict(cfg.get('data_sync_authoritative_i600') or cfg.get('data_sync_authoritative_i599') or {})
        details.update({
            'version': _I601_VERSION,
            'membership_only_cycle_preserves_complete_cot': True,
            'discovery_uids_separate_from_cot_event_uids': True,
            'discovery_uids_never_prune_cot_events': True,
            'discovery_uid_change_forces_cot_refresh_only': True,
            'successful_empty_cot_required_to_clear': True,
        })
        cfg['data_sync_authoritative_i601'] = details
        cfg['data_sync_authoritative_i600'] = details
        cfg['data_sync_authoritative_i599'] = details
        return cfg
    globals()['tak_map_config'] = tak_map_config

    def _i601_patch_html(html):
        html = str(html or '')
        html = re.sub(r'1\.3\.0-i600', _I601_PACKAGE_VERSION, html)
        html = re.sub(r'TAKDashboard/i600', 'TAKDashboard/i601', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i600', 'TAK-Map/1.3.0 i601', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i601\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i601\2', html)
        return html

    TAK_MAP_HTML = _i601_patch_html(TAK_MAP_HTML)
    INDEX_HTML = TAK_MAP_HTML
    TAK_MAP_LOGIN_HTML = _i601_patch_html(TAK_MAP_LOGIN_HTML)
    LOGIN_HTML = TAK_MAP_LOGIN_HTML
    TAK_MAP_ITERATION = _I601_VERSION
except Exception as _i601_exc:
    try:
        print('TAK Map i601 discovery/CoT identity continuity patch failed:', _i601_exc)
    except Exception:
        pass
# --- end TAK Map i601 Data Sync discovery/CoT identity separation and continuity correction ---



# --- TAK Map i602 authoritative Mission deletion identity finalization ---
try:
    _I602_VERSION = 'i602'
    _I602_PACKAGE_VERSION = '1.3.0-i602'

    def _i602_text(value):
        try:
            return str(value if value is not None else '').strip()
        except Exception:
            return ''

    def _i602_is_delete_event(row):
        try:
            checker = globals().get('_i565_delete_event')
            return bool(checker(row)) if callable(checker) else False
        except Exception:
            return False

    def _i602_mission_access_map(payload, access=None):
        rows = list(access or [])
        if not rows and isinstance(payload, dict):
            for key in ('mission_access_i599', 'mission_access_i596', 'mission_access_i595', 'mission_access_i594', 'mission_access_i591', 'mission_access_i576'):
                candidate = payload.get(key)
                if isinstance(candidate, list) and candidate:
                    rows = candidate
                    break
        out = {}
        for row in rows:
            if not isinstance(row, dict):
                continue
            mission = _i599_mission_name(row)
            if mission:
                out[mission.casefold()] = row
        return out

    def _i602_authoritative_mission_map(payload, access=None):
        per_mission = dict(((payload or {}).get('data_sync_reconciliation_i599') or {}).get('per_mission') or {}) if isinstance(payload, dict) else {}
        access_map = _i602_mission_access_map(payload, access)
        out = {}
        names = set()
        for name in per_mission:
            if _i602_text(name):
                names.add(_i602_text(name))
        for folded, row in access_map.items():
            mission = _i599_mission_name(row)
            if mission:
                names.add(mission)
        for mission in names:
            folded = mission.casefold()
            info = dict(per_mission.get(mission) or per_mission.get(folded) or {})
            access_row = dict(access_map.get(folded) or {})
            unlocked = bool(access_row.get('unlocked')) and not bool(access_row.get('locked')) if access_row else info.get('state') != 'locked'
            authoritative = bool(info.get('authoritative') or access_row.get('content_authoritative_i599'))
            out[folded] = {
                'mission': mission,
                'unlocked': bool(unlocked),
                'authoritative': bool(authoritative),
                'state': _i602_text(info.get('state') or access_row.get('content_state_i599')).lower(),
            }
        return out

    def _i602_has_cot_identity_evidence(obj):
        if not isinstance(obj, dict):
            return False
        if obj.get('cot_xml_projected_i598') or obj.get('is_mission_object'):
            return True
        source = _i602_text(obj.get('source')).casefold()
        return ('mission /cot' in source) or ('mission api' in source)

    def _i602_apply_deletion_identity(payload, access=None):
        if not isinstance(payload, dict):
            return payload
        out = dict(payload)
        mission_map = _i602_authoritative_mission_map(out, access)
        objects = []
        eligible = 0
        already_complete = 0
        unavailable = 0
        for raw in list(out.get('objects') or []):
            if not isinstance(raw, dict):
                objects.append(raw)
                continue
            obj = dict(raw)
            mission = _i599_row_mission(obj, 'objects') or _i602_text(obj.get('mission_name') or obj.get('mission'))
            uid = _i599_uid(obj)
            status = mission_map.get(mission.casefold()) if mission else None
            evidence = _i602_has_cot_identity_evidence(obj)
            exact = bool(
                mission and uid and status and status.get('unlocked') and status.get('authoritative') and
                evidence and not _i602_is_delete_event(obj)
            )
            if exact:
                had_complete = bool(
                    obj.get('delete_supported') is True and
                    _i602_text(obj.get('mission_delete_target')) == 'uid' and
                    _i602_text(obj.get('mission_delete_value')) == uid and
                    _i602_text(obj.get('mission_name')) == mission and
                    _i602_text(obj.get('canonical_id'))
                )
                # Canonical Data Sync identity is always derived from the
                # authoritative CoT event UID. Never retain an older object ID
                # that may have been derived from a Mission content UUID.
                object_id = 'datasync-' + hashlib.sha256(('uid:' + uid).encode('utf-8', 'replace')).hexdigest()[:24]
                obj['uid'] = uid
                obj['mission'] = mission
                obj['mission_name'] = mission
                obj['object_id'] = object_id
                obj['canonical_id'] = 'datasync:' + object_id
                obj['source_id'] = uid
                obj['source_kind'] = 'datasync'
                try:
                    obj['object_kind'] = _tak_object_kind(obj)
                except Exception:
                    obj['object_kind'] = obj.get('object_kind') or obj.get('kind') or 'point'
                names = list(obj.get('mission_names') or []) if isinstance(obj.get('mission_names'), list) else []
                if mission not in names:
                    names.append(mission)
                obj['mission_names'] = sorted({_i602_text(name) for name in names if _i602_text(name)})
                obj['mission_delete_target'] = 'uid'
                obj['mission_delete_value'] = uid
                obj['delete_supported'] = True
                obj.pop('delete_unavailable_reason', None)
                obj['deletion_identity_i602'] = {
                    'version': _I602_VERSION,
                    'authority': 'authoritative-mission-cot-event',
                    'mission': mission,
                    'target': 'uid',
                    'value': uid,
                    'post_reconciliation': True,
                    'discovery_content_uuid_not_used': True,
                }
                eligible += 1
                if had_complete:
                    already_complete += 1
            else:
                # Do not accidentally preserve a stale positive identity after a
                # Mission becomes locked or loses authoritative CoT ownership.
                if mission and status and (not status.get('unlocked') or not status.get('authoritative')):
                    obj['delete_supported'] = False
                    obj['mission_delete_target'] = ''
                    obj['mission_delete_value'] = ''
                    obj['delete_unavailable_reason'] = 'Authoritative unlocked Mission CoT ownership is required for deletion.'
                unavailable += 1
            objects.append(obj)
        out['objects'] = objects
        lifecycle = dict(out.get('object_lifecycle') or {})
        lifecycle.update({
            'version': _I602_VERSION,
            'canonical_data_sync': True,
            'mission_api_delete': True,
            'authoritative_mission_cot_delete_identity': True,
            'post_reconciliation_identity': True,
        })
        out['object_lifecycle'] = lifecycle
        out['data_sync_deletion_identity_i602'] = {
            'version': _I602_VERSION,
            'eligible_object_count': eligible,
            'already_complete_count': already_complete,
            'unavailable_object_count': unavailable,
            'identity': 'exact-mission-plus-cot-event-uid',
            'discovery_content_uuid_used_for_delete': False,
            'applied_after_final_reconciliation': True,
            'membership_only_generations_preserve_identity': True,
        }
        return out

    _i602_reconcile_before = _i601_reconcile
    def _i601_reconcile(result, acquired, previous, cfg, sess, mission_lkg=None):
        current, access, lkg = _i602_reconcile_before(result, acquired, previous, cfg, sess, mission_lkg)
        current = _i602_apply_deletion_identity(current, access)
        return current, access, lkg
    globals()['_i601_reconcile'] = _i601_reconcile

    _i602_validate_before = _i601_validate_snapshot
    def _i601_validate_snapshot(result, acquired, lkg):
        errors = list(_i602_validate_before(result, acquired, lkg) or [])
        mission_map = _i602_authoritative_mission_map(result)
        for row in list((result or {}).get('objects') or []):
            if not isinstance(row, dict) or _i602_is_delete_event(row):
                continue
            mission = _i599_row_mission(row, 'objects')
            uid = _i599_uid(row)
            status = mission_map.get(mission.casefold()) if mission else None
            if not (mission and uid and status and status.get('unlocked') and status.get('authoritative') and _i602_has_cot_identity_evidence(row)):
                continue
            expected_id = 'datasync-' + hashlib.sha256(('uid:' + uid).encode('utf-8', 'replace')).hexdigest()[:24]
            checks = {
                'delete_supported': row.get('delete_supported') is True,
                'mission_name': _i602_text(row.get('mission_name')) == mission,
                'mission_delete_target': _i602_text(row.get('mission_delete_target')) == 'uid',
                'mission_delete_value': _i602_text(row.get('mission_delete_value')) == uid,
                'object_id': _i602_text(row.get('object_id')) == expected_id,
                'canonical_id': _i602_text(row.get('canonical_id')) == 'datasync:' + expected_id,
            }
            missing = [name for name, ok in checks.items() if not ok]
            if missing:
                errors.append('Authoritative Mission CoT deletion identity incomplete for ' + mission + '/' + uid + ': ' + ', '.join(missing) + '.')
        return errors
    globals()['_i601_validate_snapshot'] = _i601_validate_snapshot

    if callable(globals().get('_tak_fresh_data_sync_result')):
        _i602_fresh_before = _tak_fresh_data_sync_result
        def _tak_fresh_data_sync_result():
            return _i602_apply_deletion_identity(_i602_fresh_before())
        globals()['_tak_fresh_data_sync_result'] = _tak_fresh_data_sync_result

    _i602_response_before = _i568_response_payload
    def _i568_response_payload(state):
        payload = _i602_response_before(state)
        if not isinstance(payload, dict):
            return payload
        payload = _i602_apply_deletion_identity(payload)
        payload['version'] = _I602_VERSION
        background = dict(payload.get('data_sync_background_i599') or {})
        background['version'] = _I602_VERSION
        background['deletion_identity_owner'] = _I602_VERSION
        payload['data_sync_background_i599'] = background
        payload['data_sync_background_i583'] = dict(background)
        return payload
    globals()['_i568_response_payload'] = _i568_response_payload

    _i602_config_before = tak_map_config
    def tak_map_config():
        cfg = dict(_i602_config_before() or {})
        cfg['version'] = _I602_PACKAGE_VERSION
        cfg['tak_map_iteration'] = _I602_VERSION
        cfg['data_sync_deletion_identity_i602'] = {
            'version': _I602_VERSION,
            'identity': 'exact-mission-plus-cot-event-uid',
            'applied_after_final_reconciliation': True,
            'authoritative_unlocked_mission_required': True,
            'discovery_content_uuid_used_for_delete': False,
            'membership_only_generations_preserve_identity': True,
            'server_authorization_still_enforced': True,
            'ui_unchanged': True,
        }
        delete_cfg = dict(cfg.get('data_sync_mission_delete') or {})
        delete_cfg.update({
            'version': _I602_VERSION,
            'canonical_delete_identity': 'Mission name + CoT event UID',
            'post_reconciliation_identity': True,
            'discovery_content_uuid_used_for_delete': False,
        })
        cfg['data_sync_mission_delete'] = delete_cfg
        return cfg
    globals()['tak_map_config'] = tak_map_config

    def _i602_patch_html(html):
        html = str(html or '')
        html = re.sub(r'1\.3\.0-i601', _I602_PACKAGE_VERSION, html)
        html = re.sub(r'TAKDashboard/i601', 'TAKDashboard/i602', html)
        html = re.sub(r'TAK-Map/1\.3\.0 i601', 'TAK-Map/1.3.0 i602', html)
        html = re.sub(r'(<span class="iteration-chip">)(?:i|v)\d+(</span>)', r'\1i602\2', html)
        html = re.sub(r'(<div class="iteration-marker">)(?:i|v)\d+(</div>)', r'\1i602\2', html)
        return html

    TAK_MAP_HTML = _i602_patch_html(TAK_MAP_HTML)
    INDEX_HTML = TAK_MAP_HTML
    TAK_MAP_LOGIN_HTML = _i602_patch_html(TAK_MAP_LOGIN_HTML)
    LOGIN_HTML = TAK_MAP_LOGIN_HTML
    TAK_MAP_ITERATION = _I602_VERSION
except Exception as _i602_exc:
    try:
        print('TAK Map i602 authoritative Mission deletion identity patch failed:', _i602_exc)
    except Exception:
        pass
# --- end TAK Map i602 authoritative Mission deletion identity finalization ---


# --- TAK Map i613 Source Extension drawing live-marker suppression ---
try:
    _I613_VERSION = 'i613'

    def _i613_text(value):
        return str(value or '').strip()

    def _i613_uid(row):
        if not isinstance(row, dict):
            return ''
        for key in ('uid', 'id', 'cot_uid', 'event_uid', 'source_uid'):
            value = _i613_text(row.get(key))
            if value:
                return value
        return ''

    def _i613_cot_type(row):
        if not isinstance(row, dict):
            return ''
        for key in ('type', 'cot_type', 'event_type', 'category'):
            value = _i613_text(row.get(key))
            if value:
                return value
        try:
            parsed = _parse_cot_text_fields(row) if callable(globals().get('_parse_cot_text_fields')) else {}
            return _i613_text((parsed or {}).get('type'))
        except Exception:
            return ''

    def _i613_source_extension_marker(row):
        if not isinstance(row, dict):
            return False
        uid = _i613_uid(row).casefold()
        if uid.startswith('tkgw-ext:'):
            return True
        for key in ('source_extension', 'source_extension_id', 'extension_id', 'takgateway_source_extension'):
            if row.get(key):
                return True
        try:
            blob = json.dumps(row, default=str, ensure_ascii=False).casefold()
        except Exception:
            blob = ' '.join(_i613_text(value).casefold() for value in row.values())
        return '<takgateway_source_extension' in blob or 'takgateway_source_extension' in blob

    def _i613_source_extension_drawing(row):
        if not _i613_source_extension_marker(row):
            return False
        cot_type = _i613_cot_type(row).casefold()
        return cot_type == 'u-d-f' or cot_type.startswith('u-d-f-')

    def _i613_filter_source_extension_live_payload(payload, endpoint='cot'):
        if not isinstance(payload, dict):
            return payload
        out = dict(payload)
        endpoint = _i613_text(endpoint).casefold() or 'cot'
        rows_key = 'euds' if endpoint == 'euds' else 'markers'
        rows = out.get(rows_key)
        if not isinstance(rows, list):
            return out
        kept = []
        removed = []
        for row in rows:
            # Source Extensions are data objects, never actual EUD devices. The
            # EUD endpoint therefore excludes every Source Extension record.
            # The live CoT marker endpoint excludes only drawing events, keeping
            # legitimate Point Source Extension records available to TAK Map.
            suppress = _i613_source_extension_marker(row) if endpoint == 'euds' else _i613_source_extension_drawing(row)
            if suppress:
                if len(removed) < 40:
                    removed.append({
                        'uid': _i613_uid(row)[:240],
                        'type': _i613_cot_type(row)[:80],
                        'callsign': _i613_text((row or {}).get('callsign') or (row or {}).get('name'))[:160] if isinstance(row, dict) else '',
                        'reason': 'Source Extension drawing representative point is rendered authoritatively by Gateway Data' if endpoint != 'euds' else 'Source Extension data object is not an EUD device',
                    })
                continue
            kept.append(row)
        out[rows_key] = kept
        out['source_extension_live_filter_i613'] = {
            'version': _I613_VERSION,
            'endpoint': endpoint,
            'mode': 'gateway-data-authoritative-drawing-suppression',
            'rows_before': len(rows),
            'rows_after': len(kept),
            'removed_count': len(rows) - len(kept),
            'legitimate_point_source_extensions_preserved': endpoint != 'euds',
            'removed_sample': removed,
        }
        return out

    # Suppress at normalization time when raw CoT rows are available, then
    # filter the final endpoint payload as a second boundary. The endpoint
    # filter also removes a marker that may have been normalized by an older
    # cached/live path before this release was installed.
    if callable(globals().get('_normalize_tak_marker')):
        _i613_normalize_before = _normalize_tak_marker
        def _normalize_tak_marker(row, source_table='cot', default_kind='cot'):
            try:
                if _i613_source_extension_drawing(row):
                    return None
            except Exception:
                pass
            return _i613_normalize_before(row, source_table, default_kind)
        globals()['_normalize_tak_marker'] = _normalize_tak_marker

    _i613_cot_before = tak_map_cot_markers
    def tak_map_cot_markers(*args, **kwargs):
        return _i613_filter_source_extension_live_payload(_i613_cot_before(*args, **kwargs), 'cot')
    globals()['tak_map_cot_markers'] = tak_map_cot_markers

    _i613_euds_before = tak_map_euds
    def tak_map_euds(*args, **kwargs):
        return _i613_filter_source_extension_live_payload(_i613_euds_before(*args, **kwargs), 'euds')
    globals()['tak_map_euds'] = tak_map_euds

    _i613_config_before = tak_map_config
    def tak_map_config():
        cfg = dict(_i613_config_before() or {})
        cfg['source_extension_live_drawing_suppression_i613'] = {
            'version': _I613_VERSION,
            'gateway_data_authoritative_for_drawings': True,
            'live_u_d_f_representative_points_suppressed': True,
            'source_extension_points_preserved': True,
            'eud_device_list_excludes_source_extension_objects': True,
        }
        return cfg
    globals()['tak_map_config'] = tak_map_config
except Exception as _i613_exc:
    try:
        print('TAK Map i613 Source Extension drawing suppression patch failed:', _i613_exc)
    except Exception:
        pass
# --- end TAK Map i613 Source Extension drawing live-marker suppression ---


